package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := in.NextInt()
	for ; t > 0; t-- {
		n := in.NextInt()
		k := in.NextInt()

		minOps := k
		evenCount := 0

		for i := 0; i < n; i++ {
			a := in.NextInt()
			ops := (k - a%k) % k
			if ops < minOps {
				minOps = ops
			}
			if a%2 == 0 {
				evenCount++
			}
		}

		if k == 4 {
			opsForTwoEvens := 2 - evenCount
			if opsForTwoEvens < 0 {
				opsForTwoEvens = 0
			}
			if opsForTwoEvens < minOps {
				minOps = opsForTwoEvens
			}
		}

		fmt.Fprintln(out, minOps)
	}
}
