import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return
	}

	fields := strings.Fields(string(data))
	if len(fields) == 0 {
		return
	}

	rows, err := strconv.Atoi(fields[0])
	if err != nil || rows <= 0 {
		return
	}

	valueCount := len(fields) - 1
	cols := valueCount / rows
	nums := make([][]int, rows)

	pos := 1
	for i := 0; i < rows; i++ {
		nums[i] = make([]int, cols)
		for j := 0; j < cols; j++ {
			nums[i][j], _ = strconv.Atoi(fields[pos])
			pos++
		}
		sort.Ints(nums[i])
	}

	score := 0
	for col := 0; col < cols; col++ {
		maxValue := nums[0][col]
		for row := 1; row < rows; row++ {
			if nums[row][col] > maxValue {
				maxValue = nums[row][col]
			}
		}
		score += maxValue
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, score)
}
