package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func parseInts(line string) []int64 {
	fields := strings.Fields(line)
	values := make([]int64, 0, len(fields))
	for _, field := range fields {
		field = strings.Trim(field, "[],")
		if value, err := strconv.ParseInt(field, 10, 64); err == nil {
			values = append(values, value)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	var nums []int64
	var k uint

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		nums = parseInts(line)
		break
	}

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		values := parseInts(line)
		if len(values) > 0 {
			k = uint(values[0])
		}
		break
	}

	n := len(nums)
	if n == 0 {
		return
	}

	suffixOR := make([]int64, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixOR[i] = suffixOR[i+1] | nums[i]
	}

	var answer, prefixOR int64
	for i := 0; i < n; i++ {
		candidate := prefixOR | (nums[i] << k) | suffixOR[i+1]
		if candidate > answer {
			answer = candidate
		}
		prefixOR |= nums[i]
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
