package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func decrement(s string) string {
	digits := []byte(s)
	i := len(digits) - 1
	for i >= 0 && digits[i] == '0' {
		digits[i] = '9'
		i--
	}
	if i < 0 {
		return ""
	}
	digits[i]--

	start := 0
	for start < len(digits)-1 && digits[start] == '0' {
		start++
	}
	return string(digits[start:])
}

func countUpTo(bound string, minSum, maxSum int) int64 {
	if bound == "" {
		return 0
	}

	dp := make([][2]int64, maxSum+1)
	dp[0][1] = 1

	for _, ch := range bound {
		limitDigit := int(ch - '0')
		next := make([][2]int64, maxSum+1)

		for sum := 0; sum <= maxSum; sum++ {
			for tight := 0; tight <= 1; tight++ {
				ways := dp[sum][tight]
				if ways == 0 {
					continue
				}

				limit := 9
				if tight == 1 {
					limit = limitDigit
				}

				for digit := 0; digit <= limit && sum+digit <= maxSum; digit++ {
					nextTight := 0
					if tight == 1 && digit == limitDigit {
						nextTight = 1
					}
					next[sum+digit][nextTight] =
						(next[sum+digit][nextTight] + ways) % mod
				}
			}
		}
		dp = next
	}

	var result int64
	for sum := minSum; sum <= maxSum; sum++ {
		result = (result + dp[sum][0] + dp[sum][1]) % mod
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var num1, num2 string
	var minSum, maxSum int
	fmt.Fscan(in, &num1, &num2, &minSum, &maxSum)

	answer := (countUpTo(num2, minSum, maxSum) -
		countUpTo(decrement(num1), minSum, maxSum) + mod) % mod

	fmt.Fprintln(out, answer)
}
