		nums = append(nums, x)
	}

	suffixFreq := make(map[int]int)
	for _, x := range nums {
		suffixFreq[x]++
	}

	prefix := make(map[int]struct{})
	diff := make([]int, len(nums))

	for i, x := range nums {
		suffixFreq[x]--
		if suffixFreq[x] == 0 {
			delete(suffixFreq, x)
		}

		prefix[x] = struct{}{}
		diff[i] = len(prefix) - len(suffixFreq)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i, value := range diff {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	if len(diff) > 0 {
		fmt.Fprintln(out)
	}
}
