func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	fmt.Fscan(in, &q)

	nums := make([]int, n)
	adjacent := 0

	for i := 0; i < q; i++ {
		var index, color int
		fmt.Fscan(in, &index, &color)

		oldColor := nums[index]
		if oldColor != color {
			if oldColor != 0 {
				if index > 0 && nums[index-1] == oldColor {
					adjacent--
				}
				if index+1 < n && nums[index+1] == oldColor {
					adjacent--
				}
			}

			nums[index] = color

			if index > 0 && nums[index-1] == color {
				adjacent++
			}
			if index+1 < n && nums[index+1] == color {
				adjacent++
			}
		}

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, adjacent)
	}
	fmt.Fprintln(out)
}
