	fmt.Fscan(in, &s)

	left, pairs, longest := 0, 0, 1

	for right := 1; right < len(s); right++ {
		if s[right] == s[right-1] {
			pairs++
		}

		for pairs > 1 {
			if left+1 <= right && s[left] == s[left+1] {
				pairs--
			}
			left++
		}

		if length := right - left + 1; length > longest {
			longest = length
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
