		if visited[current] {
			break
		}
		visited[current] = true
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	first := true
	for i := 0; i < n; i++ {
		if !visited[i] {
			if !first {
				fmt.Fprint(out, " ")
			}
			fmt.Fprint(out, i+1)
			first = false
		}
	}
