package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func canPartition(square, target int) bool {
	digits := strconv.Itoa(square)

	var dfs func(pos, remaining int) bool
	dfs = func(pos, remaining int) bool {
		if pos == len(digits) {
			return remaining == 0
		}

		value := 0
		for end := pos; end < len(digits); end++ {
			value = value*10 + int(digits[end]-'0')
			if value > remaining {
				break
			}
			if dfs(end+1, remaining-value) {
				return true
			}
		}
		return false
	}

	return dfs(0, target)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	answer := 0
	for i := 1; i <= n; i++ {
		square := i * i
		if canPartition(square, i) {
			answer += square
		}
	}

	fmt.Fprintln(out, answer)
}
