	in := bufio.NewReader(os.Stdin)

	var n, logCount int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	fmt.Fscan(in, &logCount)

	logs := make([]Log, logCount)
	for i := range logs {
		fmt.Fscan(in, &logs[i].server, &logs[i].time)
	}

	var x int
	fmt.Fscan(in, &x)

	var queryValues []int
	for {
		var q int
		if _, err := fmt.Fscan(in, &q); err != nil {
			break
		}
		queryValues = append(queryValues, q)
	}

	sort.Slice(logs, func(i, j int) bool {
		return logs[i].time < logs[j].time
	})

	queries := make([]Query, len(queryValues))
	for i, q := range queryValues {
		queries[i] = Query{time: q, index: i}
	}
	sort.Slice(queries, func(i, j int) bool {
		return queries[i].time < queries[j].time
	})

	answer := make([]int, len(queries))
	serverRequests := make([]int, n+1)
	left, right := 0, 0
	activeServers := 0

	for _, query := range queries {
		for right < len(logs) && logs[right].time <= query.time {
			server := logs[right].server
			if serverRequests[server] == 0 {
				activeServers++
			}
			serverRequests[server]++
			right++
		}

		startTime := query.time - x
		for left < right && logs[left].time < startTime {
			server := logs[left].server
			serverRequests[server]--
			if serverRequests[server] == 0 {
				activeServers--
			}
			left++
		}

		answer[query.index] = n - activeServers
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}
