package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Point struct {
	x, y, sum int64
}

type Query struct {
	x, y int64
	idx  int
}

type FenwickMax struct {
	tree []int64
}

func NewFenwickMax(n int) *FenwickMax {
	tree := make([]int64, n+1)
	for i := range tree {
		tree[i] = -1
	}
	return &FenwickMax{tree: tree}
}

func (f *FenwickMax) Update(i int, value int64) {
	for i < len(f.tree) {
		if value > f.tree[i] {
			f.tree[i] = value
		}
		i += i & -i
	}
}

func (f *FenwickMax) Query(i int) int64 {
	result := int64(-1)
	for i > 0 {
		if f.tree[i] > result {
			result = f.tree[i]
		}
		i -= i & -i
	}
	return result
}

func parseLine(line string) []int64 {
	fields := strings.Fields(line)
	values := make([]int64, len(fields))
	for i, field := range fields {
		values[i], _ = strconv.ParseInt(field, 10, 64)
	}
	return values
}

func nextNonEmptyLine(scanner *bufio.Scanner) string {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line
		}
	}
	return ""
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	nums1 := parseLine(nextNonEmptyLine(scanner))
	nums2 := parseLine(nextNonEmptyLine(scanner))

	qLine := parseLine(nextNonEmptyLine(scanner))
	if len(qLine) == 0 {
		return
	}
	q := int(qLine[0])

	queries := make([]Query, q)
	for i := 0; i < q; i++ {
		values := parseLine(nextNonEmptyLine(scanner))
		queries[i] = Query{x: values[0], y: values[1], idx: i}
	}

	n := len(nums1)
	points := make([]Point, n)
	ys := make([]int64, n)

	for i := 0; i < n; i++ {
		points[i] = Point{
			x:   nums1[i],
			y:   nums2[i],
			sum: nums1[i] + nums2[i],
		}
		ys[i] = nums2[i]
	}

	sort.Slice(points, func(i, j int) bool {
		return points[i].x > points[j].x
	})
	sort.Slice(queries, func(i, j int) bool {
		return queries[i].x > queries[j].x
	})
	sort.Slice(ys, func(i, j int) bool {
		return ys[i] < ys[j]
	})

	uniqueYs := ys[:0]
	for _, y := range ys {
		if len(uniqueYs) == 0 || uniqueYs[len(uniqueYs)-1] != y {
			uniqueYs = append(uniqueYs, y)
		}
	}

	fenwick := NewFenwickMax(len(uniqueYs))
	answers := make([]int64, q)
	pointIndex := 0

	for _, query := range queries {
		for pointIndex < n && points[pointIndex].x >= query.x {
			yIndex := sort.Search(len(uniqueYs), func(i int) bool {
				return uniqueYs[i] >= points[pointIndex].y
			})
			reversedIndex := len(uniqueYs) - yIndex
			fenwick.Update(reversedIndex, points[pointIndex].sum)
			pointIndex++
		}

		lowerBound := sort.Search(len(uniqueYs), func(i int) bool {
			return uniqueYs[i] >= query.y
		})
		if lowerBound == len(uniqueYs) {
			answers[query.idx] = -1
		} else {
			answers[query.idx] = fenwick.Query(len(uniqueYs) - lowerBound)
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
