import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	if n == 0 {
		return
	}

	compatible := make([][]bool, n)
	for i := 0; i < n; i++ {
		compatible[i] = make([]bool, n)
		for j := 0; j < n; j++ {
			if i != j && (nums[i]%nums[j] == 0 || nums[j]%nums[i] == 0) {
				compatible[i][j] = true
			}
		}
	}

	size := 1 << n
	dp := make([][]int64, size)
	for mask := range dp {
		dp[mask] = make([]int64, n)
	}
	for i := 0; i < n; i++ {
		dp[1<<i][i] = 1
	}

	for mask := 1; mask < size; mask++ {
		for last := 0; last < n; last++ {
			if dp[mask][last] == 0 {
				continue
			}
			for next := 0; next < n; next++ {
				if mask&(1<<next) == 0 && compatible[last][next] {
					nextMask := mask | (1 << next)
					dp[nextMask][next] = (dp[nextMask][next] + dp[mask][last]) % mod
				}
			}
		}
	}

	var answer int64
	for last := 0; last < n; last++ {
		answer = (answer + dp[size-1][last]) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
