func main() {
	in := bufio.NewReader(os.Stdin)
	var x, y, z int
	fmt.Fscan(in, &x, &y, &z)

	const (
		empty = iota
		a1
		a2
		b1
		b2
		states
	)

	sizeY := y + 1
	sizeZ := z + 1
	index := func(a, b, c, state int) int {
		return (((a*sizeY)+b)*sizeZ+c)*states + state
	}

	reachable := make([]bool, (x+1)*sizeY*sizeZ*states)
	reachable[index(0, 0, 0, empty)] = true

	maxPieces := 0

	for a := 0; a <= x; a++ {
		for b := 0; b <= y; b++ {
			for c := 0; c <= z; c++ {
				for state := 0; state < states; state++ {
					if !reachable[index(a, b, c, state)] {
						continue
					}

					if a+b+c > maxPieces {
						maxPieces = a + b + c
					}

					// Append "AA": valid only if the current string does not end in A.
					if a < x && state != a1 && state != a2 {
						reachable[index(a+1, b, c, a2)] = true
					}

					// Append "BB": valid only if the current string does not end in B.
					if b < y && state != b1 && state != b2 {
						reachable[index(a, b+1, c, b2)] = true
					}

					// Append "AB": invalid only when the current string ends in "AA".
					if c < z && state != a2 {
						reachable[index(a, b, c+1, b1)] = true
					}
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxPieces*2)
