func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int
	distinctSet := make(map[int]struct{})

	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
		distinctSet[x] = struct{}{}
	}

	required := len(distinctSet)
	freq := make(map[int]int)
	left, distinct := 0, 0
	var answer int64

	for _, x := range nums {
		if freq[x] == 0 {
			distinct++
		}
		freq[x]++

		if distinct == required {
			for freq[nums[left]] > 1 {
				freq[nums[left]]--
				left++
			}
			answer += int64(left + 1)
		}
