import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func merge(a, b string) string {
	if strings.Contains(a, b) {
		return a
	}
	if strings.Contains(b, a) {
		return b
	}

	maxOverlap := 0
	limit := len(a)
	if len(b) < limit {
		limit = len(b)
	}
	for overlap := 1; overlap <= limit; overlap++ {
		if a[len(a)-overlap:] == b[:overlap] {
			maxOverlap = overlap
		}
	}
	return a + b[maxOverlap:]
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var stringsInput [3]string
	fmt.Fscan(in, &stringsInput[0], &stringsInput[1], &stringsInput[2])

	permutations := [][3]int{
		{0, 1, 2},
		{0, 2, 1},
		{1, 0, 2},
		{1, 2, 0},
		{2, 0, 1},
		{2, 1, 0},
	}

	best := ""
	for _, p := range permutations {
		candidate := merge(merge(stringsInput[p[0]], stringsInput[p[1]]), stringsInput[p[2]])
		if best == "" || len(candidate) < len(best) ||
			(len(candidate) == len(best) && candidate < best) {
			best = candidate
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
}
