	var n, x int
	if _, err := fmt.Fscan(in, &n, &x); err != nil {
		return
	}

	dp := make([]int, n+1)
	dp[0] = 1

	for base := 1; ; base++ {
		value := power(base, x)
		if value > n {
			break
		}

		for sum := n; sum >= value; sum-- {
			dp[sum] += dp[sum-value]
			if dp[sum] >= mod {
				dp[sum] -= mod
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[n])
