			continue
		}

		value := 0
		for j := i; j < n; j++ {
			value = value*2 + int(s[j]-'0')
			if powers[value] && dp[j+1] > dp[i]+1 {
				dp[j+1] = dp[i] + 1
			}
		}
	}

	if dp[n] == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, dp[n])
