	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 2 {
		return
	}

	fields := strings.Fields(lines[0])
	nums := make([]int64, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			nums = append(nums, value)
		}
	}
	if len(nums) == 0 {
		return
	}

	xField := strings.Fields(lines[1])
	if len(xField) == 0 {
		return
	}
	x, err := strconv.ParseInt(xField[0], 10, 64)
	if err != nil {
		return
	}

	const negInf int64 = -1 << 60
	best := [2]int64{negInf, negInf}
	best[nums[0]%2] = nums[0]

	for i := 1; i < len(nums); i++ {
		value := nums[i]
		parity := value % 2

		candidate := best[parity] + value
		if best[1-parity] != negInf {
			switched := best[1-parity] + value - x
			if switched > candidate {
				candidate = switched
			}
		}

		if candidate > best[parity] {
			best[parity] = candidate
		}
	}

	answer := best[0]
	if best[1] > answer {
		answer = best[1]
	}

	writer := bufio.NewWriter(os.Stdout)
