		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}

	if len(values) < 3 {
		return
	}

	nums := values[:len(values)-2]
	modulo := values[len(values)-2]
	k := values[len(values)-1]

	frequency := make(map[int64]int64)
	frequency[0] = 1

	var prefix, answer int64
	for _, num := range nums {
		if num%modulo == k {
			prefix = (prefix + 1) % modulo
		}

		required := (prefix - k + modulo) % modulo
		answer += frequency[required]
		frequency[prefix]++
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
