package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func countStepping(bound string) int64 {
	// prev == 10 means the number has not started yet.
	var dp [2][11]int64
	dp[1][10] = 1

	for _, ch := range bound {
		digit := int(ch - '0')
		var next [2][11]int64

		for tight := 0; tight <= 1; tight++ {
			for prev := 0; prev <= 10; prev++ {
				ways := dp[tight][prev]
				if ways == 0 {
					continue
				}

				limit := 9
				if tight == 1 {
					limit = digit
				}

				for d := 0; d <= limit; d++ {
					nextTight := 0
					if tight == 1 && d == digit {
						nextTight = 1
					}

					if prev == 10 {
						if d == 0 {
							next[nextTight][10] = (next[nextTight][10] + ways) % mod
						} else {
							next[nextTight][d] = (next[nextTight][d] + ways) % mod
						}
					} else if d-prev == 1 || prev-d == 1 {
						next[nextTight][d] = (next[nextTight][d] + ways) % mod
					}
				}
			}
		}
		dp = next
	}

	var result int64
	for tight := 0; tight <= 1; tight++ {
		for prev := 0; prev < 10; prev++ {
			result = (result + dp[tight][prev]) % mod
		}
	}
	return result
}

func decrement(s string) string {
	digits := []byte(s)
	i := len(digits) - 1

	for i >= 0 && digits[i] == '0' {
		digits[i] = '9'
		i--
	}
	if i >= 0 {
		digits[i]--
	}

	start := 0
	for start < len(digits)-1 && digits[start] == '0' {
		start++
	}
	return string(digits[start:])
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var low, high string
	fmt.Fscan(in, &low, &high)

	answer := (countStepping(high) - countStepping(decrement(low)) + mod) % mod
	fmt.Fprintln(out, answer)
}
