	}

	numFields := strings.Fields(lines[0])
	nums := make([]int64, len(numFields))
	for i, field := range numFields {
		nums[i], _ = strconv.ParseInt(field, 10, 64)
	}

	m, _ := strconv.Atoi(strings.Fields(lines[1])[0])
	k, _ := strconv.Atoi(strings.Fields(lines[2])[0])

	frequencies := make(map[int64]int)
	var windowSum int64
	var maxSum int64

	for i, value := range nums {
		windowSum += value
		frequencies[value]++

		if i >= k {
			removed := nums[i-k]
			windowSum -= removed
			frequencies[removed]--
			if frequencies[removed] == 0 {
				delete(frequencies, removed)
			}
		}

		if i >= k-1 && len(frequencies) >= m && windowSum > maxSum {
			maxSum = windowSum
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, maxSum)
}
