package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Node struct {
	key      int
	priority uint32
	left     *Node
	right    *Node
}

var seed uint32 = 2463534242

func randomPriority() uint32 {
	seed ^= seed << 13
	seed ^= seed >> 17
	seed ^= seed << 5
	return seed
}

func rotateRight(root *Node) *Node {
	child := root.left
	root.left = child.right
	child.right = root
	return child
}

func rotateLeft(root *Node) *Node {
	child := root.right
	root.right = child.left
	child.left = root
	return child
}

func insert(root *Node, key int) *Node {
	if root == nil {
		return &Node{key: key, priority: randomPriority()}
	}
	if key < root.key {
		root.left = insert(root.left, key)
		if root.left.priority < root.priority {
			root = rotateRight(root)
		}
	} else if key > root.key {
		root.right = insert(root.right, key)
		if root.right.priority < root.priority {
			root = rotateLeft(root)
		}
	}
	return root
}

func nearestDifference(root *Node, value int) int64 {
	const inf int64 = 1 << 62
	best := inf

	for root != nil {
		diff := int64(root.key) - int64(value)
		if diff < 0 {
			if -diff < best {
				best = -diff
			}
			root = root.right
		} else {
			if diff < best {
				best = diff
			}
			root = root.left
		}
	}
	return best
}

func parseInts(line string) []int {
	line = strings.NewReplacer("[", " ", "]", " ", ",", " ").Replace(line)
	fields := strings.Fields(line)
	values := make([]int, 0, len(fields))
	for _, field := range fields {
		if value, err := strconv.Atoi(field); err == nil {
			values = append(values, value)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}

	if len(lines) < 2 {
		return
	}

	nums := parseInts(lines[0])
	xValues := parseInts(lines[1])
	if len(nums) == 0 || len(xValues) == 0 {
		return
	}
	x := xValues[0]

	if x == 0 {
		fmt.Println(0)
		return
	}

	const inf int64 = 1 << 62
	answer := inf
	var root *Node

	for i := x; i < len(nums); i++ {
		root = insert(root, nums[i-x])
		diff := nearestDifference(root, nums[i])
		if diff < answer {
			answer = diff
		}
		if answer == 0 {
			break
		}
	}

	fmt.Println(answer)
}
