package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

type Matrix [2][2]int64

func multiply(a, b Matrix) Matrix {
	var c Matrix
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			for p := 0; p < 2; p++ {
				c[i][j] = (c[i][j] + a[i][p]*b[p][j]) % mod
			}
		}
	}
	return c
}

func power(base Matrix, exponent int64) Matrix {
	result := Matrix{{1, 0}, {0, 1}}
	for exponent > 0 {
		if exponent&1 == 1 {
			result = multiply(result, base)
		}
		base = multiply(base, base)
		exponent >>= 1
	}
	return result
}

func countMatchingRotations(s, t string) int64 {
	n := len(s)

	pi := make([]int, n)
	for i, j := 1, 0; i < n; i++ {
		for j > 0 && t[i] != t[j] {
			j = pi[j-1]
		}
		if t[i] == t[j] {
			j++
		}
		pi[i] = j
	}

	var count int64
	j := 0
	for i := 0; i < 2*n-1; i++ {
		c := s[i%n]
		for j > 0 && c != t[j] {
			j = pi[j-1]
		}
		if c == t[j] {
			j++
		}
		if j == n {
			start := i - n + 1
			if start < n {
				count++
			}
			j = pi[j-1]
		}
	}
	return count
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s, t string
	var k int64
	if _, err := fmt.Fscan(in, &s, &t, &k); err != nil {
		return
	}

	n := len(s)
	matches := countMatchingRotations(s, t)

	transition := Matrix{
		{0, int64(n - 1) % mod},
		{1, int64(n - 2) % mod},
	}
	result := power(transition, k)

	waysZero := result[0][0]
	waysNonZero := result[1][0]

	var answer int64
	if s == t {
		answer = (waysZero + ((matches-1)%mod)*waysNonZero) % mod
	} else {
		answer = (matches % mod) * waysNonZero % mod
	}

	fmt.Fprintln(out, answer)
}
