	for i := 0; i < len(data); {
		if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, value)
	}

	if len(values) < 2 {
		return
	}

	n := len(values) - 1
	k := values[n]

	jump := make([]int, n)
	gain := make([]int64, n)
	position := make([]int, n)
	total := make([]int64, n)

	for i := 0; i < n; i++ {
		jump[i] = int(values[i])
		gain[i] = values[i]
		position[i] = i
		total[i] = int64(i)
	}

	for k > 0 {
		if k&1 == 1 {
			for i := 0; i < n; i++ {
				total[i] += gain[position[i]]
				position[i] = jump[position[i]]
			}
		}

		k >>= 1
		if k == 0 {
			break
		}

		nextJump := make([]int, n)
		nextGain := make([]int64, n)
		for i := 0; i < n; i++ {
			mid := jump[i]
			nextJump[i] = jump[mid]
			nextGain[i] = gain[i] + gain[mid]
		}
		jump = nextJump
		gain = nextGain
	}

	answer := total[0]
	for i := 1; i < n; i++ {
		if total[i] > answer {
			answer = total[i]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
