func squareFreePart(x int) int {
	result := 1
	for p := 2; p*p <= x; p++ {
		odd := false
		for x%p == 0 {
			x /= p
			odd = !odd
		}
		if odd {
			result *= p
		}
	}
	if x > 1 {
		result *= x
	}
	return result
}

