package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Fenwick struct {
	tree []int64
}

func (f *Fenwick) Update(i int, value int64) {
	for i < len(f.tree) {
		if value > f.tree[i] {
			f.tree[i] = value
		}
		i += i & -i
	}
}

func (f *Fenwick) Query(i int) int64 {
	var best int64
	for i > 0 {
		if f.tree[i] > best {
			best = f.tree[i]
		}
		i -= i & -i
	}
	return best
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var nums []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	if len(nums) == 0 {
		return
	}

	keys := make([]int64, len(nums))
	sortedKeys := make([]int64, len(nums))
	for i, x := range nums {
		keys[i] = x - int64(i)
		sortedKeys[i] = keys[i]
	}

	sort.Slice(sortedKeys, func(i, j int) bool {
		return sortedKeys[i] < sortedKeys[j]
	})

	unique := sortedKeys[:0]
	for _, x := range sortedKeys {
		if len(unique) == 0 || unique[len(unique)-1] != x {
			unique = append(unique, x)
		}
	}

	fenwick := Fenwick{tree: make([]int64, len(unique)+1)}
	answer := int64(-1 << 63)

	for i, x := range nums {
		position := sort.Search(len(unique), func(j int) bool {
			return unique[j] >= keys[i]
		}) + 1

		dp := x + fenwick.Query(position)
		if dp > answer {
			answer = dp
		}
		fenwick.Update(position, dp)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
