	var a, b uint64
	var n int
	fmt.Fscan(in, &a, &b, &n)

	var lowMask uint64
	if n > 0 {
		lowMask = (uint64(1) << n) - 1
	}

	xorA := a &^ lowMask
	xorB := b &^ lowMask

	for i := n - 1; i >= 0; i-- {
		bit := uint64(1) << i
		aBit := a & bit
		bBit := b & bit

		if (aBit == 0) == (bBit == 0) {
			xorA |= bit
			xorB |= bit
		} else if xorA <= xorB {
			xorA |= bit
		} else {
			xorB |= bit
		}
	}

	const mod uint64 = 1_000_000_007
	answer := ((xorA % mod) * (xorB % mod)) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
