		dp[i] = dp[j] + 1
		lastSum[i] = prefix[i] - prefix[j]
		threshold := prefix[i] + lastSum[i]

		for len(queue) > head {
			back := queue[len(queue)-1]
			if prefix[back]+lastSum[back] < threshold {
				break
			}
			queue = queue[:len(queue)-1]
		}
