package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func modPow(base, exp int64) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	sick := make([]int, 0)
	for {
		var position int
		if _, err := fmt.Fscan(in, &position); err != nil {
			break
		}
		sick = append(sick, position)
	}

	healthy := n - len(sick)

	factorial := make([]int64, healthy+1)
	factorial[0] = 1
	for i := 1; i <= healthy; i++ {
		factorial[i] = factorial[i-1] * int64(i) % mod
	}

	answer := factorial[healthy]

	applyGap := func(length int, internal bool) {
		if length <= 0 {
			return
		}
		answer = answer * modPow(factorial[length], mod-2) % mod
		if internal {
			answer = answer * modPow(2, int64(length-1)) % mod
		}
	}

	applyGap(sick[0], false)

	for i := 1; i < len(sick); i++ {
		gap := sick[i] - sick[i-1] - 1
		applyGap(gap, true)
	}

	applyGap(n-1-sick[len(sick)-1], false)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
