import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	var k int
	if _, err := fmt.Fscan(in, &s, &k); err != nil {
		return
	}

	if k == 26 {
		fmt.Println(1)
		return
	}

	n := len(s)
	memo := make(map[uint64]int)

	var dfs func(index int, mask uint32, canChange bool) int
	dfs = func(index int, mask uint32, canChange bool) int {
		if index == n {
			return 1
		}

		changeFlag := uint64(0)
		if canChange {
			changeFlag = 1
		}
		key := (uint64(index) << 27) | (uint64(mask) << 1) | changeFlag
		if value, ok := memo[key]; ok {
			return value
		}

		original := int(s[index] - 'a')
		originalBit := uint32(1) << original
		nextMask := mask | originalBit

		best := 0
		if bits.OnesCount32(nextMask) > k {
			best = 1 + dfs(index+1, originalBit, canChange)
		} else {
			best = dfs(index+1, nextMask, canChange)
		}

		if canChange {
			for letter := 0; letter < 26; letter++ {
				if letter == original {
					continue
				}

				replacementBit := uint32(1) << letter
				changedMask := mask | replacementBit

				var candidate int
				if bits.OnesCount32(changedMask) > k {
					candidate = 1 + dfs(index+1, replacementBit, false)
				} else {
					candidate = dfs(index+1, changedMask, false)
				}

				if candidate > best {
					best = candidate
				}
			}
		}

		memo[key] = best
		return best
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintln(out, dfs(0, 0, true))
}
