	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}

	if len(lines) < 5 {
		return
	}

	source := strings.Fields(lines[0])[0]
	target := strings.Fields(lines[1])[0]
	original := strings.Fields(lines[2])
	changed := strings.Fields(lines[3])
	costFields := strings.Fields(lines[4])

	const inf int64 = 1 << 60
	var dist [26][26]int64
	for i := 0; i < 26; i++ {
		for j := 0; j < 26; j++ {
			if i == j {
				dist[i][j] = 0
			} else {
				dist[i][j] = inf
			}
		}
	}

	m := len(original)
	if len(changed) < m {
		m = len(changed)
	}
	if len(costFields) < m {
		m = len(costFields)
	}

	for i := 0; i < m; i++ {
		c, err := strconv.ParseInt(costFields[i], 10, 64)
		if err != nil || len(original[i]) == 0 || len(changed[i]) == 0 {
			continue
		}
		from := original[i][0] - 'a'
		to := changed[i][0] - 'a'
		if c < dist[from][to] {
			dist[from][to] = c
		}
	}

	for k := 0; k < 26; k++ {
		for i := 0; i < 26; i++ {
			if dist[i][k] == inf {
				continue
			}
			for j := 0; j < 26; j++ {
				if dist[k][j] == inf {
					continue
				}
				if dist[i][k]+dist[k][j] < dist[i][j] {
					dist[i][j] = dist[i][k] + dist[k][j]
				}
			}
		}
	}

	var answer int64
	for i := 0; i < len(source); i++ {
		from := source[i] - 'a'
		to := target[i] - 'a'
		if dist[from][to] == inf {
			fmt.Println(-1)
			return
		}
		answer += dist[from][to]
	}

	fmt.Println(answer)
}
