func parseInts(s string) []int {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r < '0' || r > '9'
	})
	values := make([]int, 0, len(fields))
	for _, field := range fields {
		v, err := strconv.Atoi(field)
		if err == nil {
			values = append(values, v)
		}
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	var nums []int
	k := 0

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if nums == nil {
			nums = parseInts(line)
		} else {
			values := parseInts(line)
			if len(values) > 0 {
				k = values[0]
				break
			}
		}
	}

	n := len(nums)
	requiredGroups := n - k
	const allBits = (1 << 30) - 1

	feasible := func(zeroMask int) bool {
		groups := 0
		currentAnd := allBits

		for _, value := range nums {
			currentAnd &= value
			if currentAnd&zeroMask == 0 {
				groups++
				currentAnd = allBits
			}
		}
		return groups >= requiredGroups
	}

	answer := 0
	zeroMask := 0

	for bit := 29; bit >= 0; bit-- {
		candidate := zeroMask | (1 << bit)
		if feasible(candidate) {
			zeroMask = candidate
		} else {
			answer |= 1 << bit
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
