func parseInts(s string) []int64 {
	var result []int64
	for i := 0; i < len(s); {
		sign := int64(1)
		if s[i] == '-' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			sign = -1
			i++
		} else if s[i] < '0' || s[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
		}
		result = append(result, sign*value)
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

