	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type element struct {
	value int
	index int
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	var line string
	for {
		var err error
		line, err = reader.ReadString('\n')
		line = strings.TrimSpace(line)
		if line != "" || err != nil {
			break
		}
	}

	fields := strings.Fields(line)
	nums := make([]int, len(fields))
	var sum int64
	for i, field := range fields {
		nums[i], _ = strconv.Atoi(field)
		sum += int64(nums[i])
	}

	n := len(nums)
	elements := make([]element, n)
	for i, value := range nums {
		elements[i] = element{value: value, index: i}
	}

	sort.Slice(elements, func(i, j int) bool {
		if elements[i].value == elements[j].value {
			return elements[i].index < elements[j].index
		}
		return elements[i].value < elements[j].value
	})

	var m int
	fmt.Fscan(reader, &m)

	marked := make([]bool, n)
	answers := make([]int64, m)
	next := 0

	for q := 0; q < m; q++ {
		var index, k int
		fmt.Fscan(reader, &index, &k)

		if !marked[index] {
			marked[index] = true
			sum -= int64(nums[index])
		}

		for k > 0 {
			for next < n && marked[elements[next].index] {
				next++
			}
			if next == n {
				break
			}

			e := elements[next]
			marked[e.index] = true
			sum -= int64(e.value)
			next++
			k--
		}

		answers[q] = sum
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, answer := range answers {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, answer)
	}
	fmt.Fprintln(writer)
}
