func parseIntegers(data []byte) []int64 {
	values := make([]int64, 0)
	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		if i >= len(data) || data[i] < '0' || data[i] > '9' {
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, sign*value)
	}
	return values
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	values := parseIntegers(data)
	if len(values) < 2 {
		return
	}

	k := int(values[len(values)-1])
	nums := values[:len(values)-1]

	const negInf int64 = -1 << 62

	dp := make([]int64, k+1)
	end := make([]int64, k+1)
	for j := 1; j <= k; j++ {
		dp[j] = negInf
		end[j] = negInf
	}

	for i, value := range nums {
		limit := k
		if i+1 < limit {
			limit = i + 1
		}

		for j := limit; j >= 1; j-- {
			coefficient := int64(k - j + 1)
			if j%2 == 0 {
				coefficient = -coefficient
			}

			bestPrevious := end[j]
			if dp[j-1] > bestPrevious {
				bestPrevious = dp[j-1]
			}

			end[j] = bestPrevious + value*coefficient
			if end[j] > dp[j] {
				dp[j] = end[j]
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(writer, dp[k])
	writer.Flush()
