package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(line string) []int64 {
	var nums []int64
	var value int64
	inNumber := false

	for _, ch := range line {
		if ch >= '0' && ch <= '9' {
			value = value*10 + int64(ch-'0')
			inNumber = true
		} else if inNumber {
			nums = append(nums, value)
			value = 0
			inNumber = false
		}
	}
	if inNumber {
		nums = append(nums, value)
	}
	return nums
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int64
	for scanner.Scan() {
		nums := parseInts(scanner.Text())
		if len(nums) > 0 {
			lines = append(lines, nums)
		}
	}

	if len(lines) < 2 || len(lines[0]) == 0 || len(lines[1]) == 0 {
		return
	}

	rawCoins := lines[0]
	k := lines[1][0]

	// Remove denominations whose multiples are already covered by a smaller coin.
	coins := make([]int64, 0, len(rawCoins))
	for i, coin := range rawCoins {
		redundant := false
		for j, other := range rawCoins {
			if i != j && coin%other == 0 {
				redundant = true
				break
			}
		}
		if !redundant {
			coins = append(coins, coin)
		}
	}

	minCoin := coins[0]
	for _, coin := range coins[1:] {
		if coin < minCoin {
			minCoin = coin
		}
	}
	high := minCoin * k

	// Aggregate inclusion-exclusion coefficients by LCM.
	coefficients := make(map[int64]int64)
	n := len(coins)
	for mask := 1; mask < (1 << n); mask++ {
		lcm := int64(1)
		bits := 0
		valid := true

		for i := 0; i < n; i++ {
			if mask&(1<<i) == 0 {
				continue
			}
			bits++
			g := gcd(lcm, coins[i])
			factor := coins[i] / g
			if lcm > high/factor {
				valid = false
				break
			}
			lcm *= factor
		}

		if valid && lcm <= high {
			if bits%2 == 1 {
				coefficients[lcm]++
			} else {
				coefficients[lcm]--
			}
		}
	}

	countAmounts := func(limit int64) int64 {
		var count int64
		for lcm, coefficient := range coefficients {
			count += coefficient * (limit / lcm)
		}
		return count
	}

	low := int64(1)
	for low < high {
		mid := low + (high-low)/2
		if countAmounts(mid) >= k {
			high = mid
		} else {
			low = mid + 1
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, low)
}
