	if err != nil {
		return
	}

	var lines []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 2 {
		return
	}

	wordsContainer := strings.Fields(lines[0])
	wordsQuery := strings.Fields(lines[1])
	if len(wordsContainer) == 0 {
		return
	}

	nodes := make([]TrieNode, 1)
	nodes[0].best = -1

	updateBest := func(node, index int) {
		current := nodes[node].best
		if current == -1 ||
			len(wordsContainer[index]) < len(wordsContainer[current]) ||
			(len(wordsContainer[index]) == len(wordsContainer[current]) && index < current) {
			nodes[node].best = index
		}
	}

	for index, word := range wordsContainer {
		node := 0
		updateBest(node, index)

		for i := len(word) - 1; i >= 0; i-- {
			c := int(word[i] - 'a')
			next := nodes[node].children[c]
			if next == 0 {
				nodes = append(nodes, TrieNode{best: -1})
				next = len(nodes) - 1
				nodes[node].children[c] = next
			}
			node = next
			updateBest(node, index)
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for qi, query := range wordsQuery {
		node := 0
		answer := nodes[0].best

