			next := nodes[node].children[c]
			if next == 0 {
				break
			}
			node = next
			answer = nodes[node].best
		}

		if qi > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer)
	}
	fmt.Fprintln(out)
