package main

import (
	"bufio"
	"fmt"
	"os"
)

func totalSetBits(n int64) int64 {
	if n <= 0 {
		return 0
	}

	values := n + 1 // Count integers from 0 through n.
	var total int64

	for bit := 0; bit <= 60; bit++ {
		power := int64(1) << bit
		cycle := power << 1

		total += (values / cycle) * power
		remainder := values % cycle
		if remainder > power {
			total += remainder - power
		}
	}
	return total
}

func totalBitPositionSum(n int64) int64 {
	if n <= 0 {
		return 0
	}

	values := n + 1
	var total int64

	for bit := 0; bit <= 60; bit++ {
		power := int64(1) << bit
		cycle := power << 1

		ones := (values / cycle) * power
		remainder := values % cycle
		if remainder > power {
			ones += remainder - power
		}

		total += ones * int64(bit)
	}
	return total
}

// prefixExponentSum returns the sum of exponents of the first k elements
// of big_nums.
func prefixExponentSum(k int64) int64 {
	if k <= 0 {
		return 0
	}

	// Find the largest n such that the powerful arrays for 1..n
	// contain at most k elements.
	var low, high int64 = 0, k
	var n int64

	for low <= high {
		mid := low + (high-low)/2
		if totalSetBits(mid) <= k {
			n = mid
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	result := totalBitPositionSum(n)
	remaining := k - totalSetBits(n)

	// Take the first remaining set bits of n+1, in ascending order.
	next := n + 1
	for bit := 0; bit <= 60 && remaining > 0; bit++ {
		if next&(int64(1)<<bit) != 0 {
			result += int64(bit)
			remaining--
		}
	}

	return result
}

func modPow2(exponent, mod int64) int64 {
	if mod == 1 {
		return 0
	}

	result := int64(1)
	base := int64(2) % mod

	for exponent > 0 {
		if exponent&1 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		exponent >>= 1
	}

	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var q int
	if _, err := fmt.Fscan(in, &q); err != nil {
		return
	}

	for i := 0; i < q; i++ {
		var from, to, mod int64
		fmt.Fscan(in, &from, &to, &mod)

		exponent := prefixExponentSum(to+1) - prefixExponentSum(from)
		answer := modPow2(exponent, mod)

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, answer)
	}
	fmt.Fprintln(out)
}
