func combination(n, r int64) int64 {
	if r < 0 || r > n {
		return 0
	}
	if r > n-r {
		r = n - r
	}

	var result int64 = 1
	for i := int64(1); i <= r; i++ {
		result = result * (n - r + i) / i
	}
	return result
}

