	power := int64(1)

	for jumps := int64(0); ; jumps++ {
		downs := power - k

		if downs >= 0 && downs <= jumps+1 {
			ways += combination(jumps+1, downs)
		}

		if downs > jumps+1 {
			break
		}
		power *= 2
	}

	fmt.Fprintln(out, ways)
