)

type Node struct {
	dp [2][2]int64
}

func leaf(value int64) Node {
	node := Node{}
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			node.dp[i][j] = negInf
		}
	}
	node.dp[0][0] = 0
	node.dp[1][1] = value
	return node
}

func merge(left, right Node) Node {
	var result Node
	for first := 0; first < 2; first++ {
		for last := 0; last < 2; last++ {
			result.dp[first][last] = negInf
			for leftLast := 0; leftLast < 2; leftLast++ {
				for rightFirst := 0; rightFirst < 2; rightFirst++ {
					if leftLast == 1 && rightFirst == 1 {
						continue
					}
					if left.dp[first][leftLast] == negInf ||
						right.dp[rightFirst][last] == negInf {
						continue
					}
					value := left.dp[first][leftLast] + right.dp[rightFirst][last]
					if value > result.dp[first][last] {
						result.dp[first][last] = value
					}
				}
			}
		}
	}
	return result
}

type SegmentTree struct {
	n    int
	tree []Node
}

func NewSegmentTree(nums []int64) *SegmentTree {
	st := &SegmentTree{
		n:    len(nums),
		tree: make([]Node, 4*len(nums)),
	}
	st.build(1, 0, len(nums)-1, nums)
	return st
}

func (st *SegmentTree) build(node, left, right int, nums []int64) {
	if left == right {
		st.tree[node] = leaf(nums[left])
		return
	}
	mid := left + (right-left)/2
	st.build(node*2, left, mid, nums)
	st.build(node*2+1, mid+1, right, nums)
	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) Update(index int, value int64) {
	st.update(1, 0, st.n-1, index, value)
}

func (st *SegmentTree) update(node, left, right, index int, value int64) {
	if left == right {
		st.tree[node] = leaf(value)
		return
	}
	mid := left + (right-left)/2
	if index <= mid {
		st.update(node*2, left, mid, index, value)
	} else {
		st.update(node*2+1, mid+1, right, index, value)
	}
	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) MaximumSum() int64 {
	result := int64(0)
	root := st.tree[1]
	for first := 0; first < 2; first++ {
		for last := 0; last < 2; last++ {
			if root.dp[first][last] > result {
				result = root.dp[first][last]
			}
		}
	}
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	var firstLine string
	for {
		line, err := reader.ReadString('\n')
		if strings.TrimSpace(line) != "" {
			firstLine = line
			break
		}
		if err == io.EOF {
			return
		}
	}

	fields := strings.Fields(firstLine)
	nums := make([]int64, len(fields))
	for i, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err != nil {
			return
		}
		nums[i] = value
	}

	var queryCount int
	if _, err := fmt.Fscan(reader, &queryCount); err != nil {
		return
	}

	tree := NewSegmentTree(nums)
	var answer int64

	for i := 0; i < queryCount; i++ {
		var position int
		var value int64
		fmt.Fscan(reader, &position, &value)

		tree.Update(position, value)
		answer = (answer + tree.MaximumSum()) % mod
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
