	if len(lines) < 2 {
		return
	}

	fields := strings.Fields(lines[0])
	nums := make([]int64, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			nums = append(nums, value)
		}
	}

	kField := strings.Fields(lines[1])
	if len(nums) == 0 || len(kField) == 0 {
		return
	}
	k, err := strconv.ParseInt(kField[0], 10, 64)
	if err != nil {
		return
	}

	const maxInt64 = int64(^uint64(0) >> 1)
	answer := maxInt64
	var previous []int64

	for _, num := range nums {
		current := make([]int64, 0, len(previous)+1)
		seen := make(map[int64]struct{}, len(previous)+1)

		current = append(current, num)
		seen[num] = struct{}{}

		for _, value := range previous {
			orValue := value | num
			if _, exists := seen[orValue]; !exists {
				seen[orValue] = struct{}{}
				current = append(current, orValue)
			}
		}

		for _, value := range current {
			diff := value - k
			if diff < 0 {
				diff = -diff
			}
			if diff < answer {
				answer = diff
			}
		}

