			i++
		}
		rewards = append(rewards, value)
	}

	if len(rewards) == 0 {
		return
	}

	sort.Ints(rewards)
	maxValue := rewards[len(rewards)-1]
	reachable := make([]bool, 2*maxValue+1)
	reachable[0] = true

	answer := 0
	for _, reward := range rewards {
		for total := reward - 1; total >= 0; total-- {
			if reachable[total] {
				newTotal := total + reward
				reachable[newTotal] = true
				if newTotal > answer {
					answer = newTotal
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
