	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	fmt.Fscan(in, &m)

	requirement := make([]int, n)
	for i := range requirement {
		requirement[i] = -1
	}

	for i := 0; i < m; i++ {
		var end, count int
		fmt.Fscan(in, &end, &count)
		requirement[end] = count
	}

	finalCount := requirement[n-1]
	dp := make([]int64, finalCount+1)
	dp[0] = 1

	for length := 1; length <= n; length++ {
		next := make([]int64, finalCount+1)
		var window int64

		for inversions := 0; inversions <= finalCount; inversions++ {
			window += dp[inversions]
			if inversions-length >= 0 {
				window -= dp[inversions-length]
			}
			window %= mod
			if window < 0 {
				window += mod
			}
			next[inversions] = window
		}

		required := requirement[length-1]
		if required != -1 {
			if required > finalCount {
				fmt.Println(0)
				return
			}
			value := next[required]
			for i := range next {
				next[i] = 0
			}
			next[required] = value
		}

		dp = next
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[finalCount])
}
