	var values []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		values = append(values, x)
	}

	if len(values) < 3 {
		return
	}

	d := values[len(values)-1]
	start := values[:len(values)-1]
	sort.Slice(start, func(i, j int) bool {
		return start[i] < start[j]
	})

	feasible := func(gap int64) bool {
		chosen := start[0]
		for i := 1; i < len(start); i++ {
			next := chosen + gap
			if next < start[i] {
				next = start[i]
			}
			if next > start[i]+d {
				return false
			}
			chosen = next
		}
		return true
	}

	low := int64(0)
	high := (start[len(start)-1]+d-start[0])/int64(len(start)-1) + 1

	for low+1 < high {
		mid := low + (high-low)/2
		if feasible(mid) {
			low = mid
		} else {
			high = mid
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, low)
}
