import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type MaxHeap []int64

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x interface{}) {
	*h = append(*h, x.(int64))
}

func (h *MaxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	distances := make([]int64, n)
	for i := 0; i < n; i++ {
		var x, y int64
		fmt.Fscan(in, &x, &y)
		distances[i] = abs(x) + abs(y)
	}

	var k int
	fmt.Fscan(in, &k)

	h := &MaxHeap{}
	heap.Init(h)

	for i, distance := range distances {
		if h.Len() < k {
			heap.Push(h, distance)
		} else if distance < (*h)[0] {
			heap.Pop(h)
			heap.Push(h, distance)
		}

		if i > 0 {
			fmt.Fprint(out, " ")
		}
		if h.Len() < k {
			fmt.Fprint(out, -1)
		} else {
			fmt.Fprint(out, (*h)[0])
		}
	}
	fmt.Fprintln(out)
}
