	for limit*limit > r {
		limit--
	}

	isPrime := make([]bool, int(limit+1))
	for i := int64(2); i <= limit; i++ {
		isPrime[i] = true
	}
	for i := int64(2); i*i <= limit; i++ {
		if isPrime[i] {
			for j := i * i; j <= limit; j += i {
				isPrime[j] = false
			}
		}
	}

	var special int64
	for p := int64(2); p <= limit; p++ {
		if isPrime[p] {
			square := p * p
			if square >= l && square <= r {
				special++
			}
		}
	}

	fmt.Fprintln(out, r-l+1-special)
