	}

	answer := 0
	for i := 0; i < len(nums); i++ {
		for j := i + 1; j < len(nums); j++ {
			if canBecome(nums[i], nums[j]) || canBecome(nums[j], nums[i]) {
				answer++
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
