const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var nums []int
	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	if len(nums) == 0 {
		return
	}

	dp := make([]int64, nums[0]+1)
	for x := 0; x <= nums[0]; x++ {
		dp[x] = 1
	}

	for i := 1; i < len(nums); i++ {
		prefix := make([]int64, len(dp))
		prefix[0] = dp[0]
		for x := 1; x < len(dp); x++ {
			prefix[x] = (prefix[x-1] + dp[x]) % mod
		}

		next := make([]int64, nums[i]+1)
		for y := 0; y <= nums[i]; y++ {
			limit := y
			if v := y + nums[i-1] - nums[i]; v < limit {
				limit = v
			}
			if limit >= 0 {
				if limit >= len(prefix) {
					limit = len(prefix) - 1
				}
				next[y] = prefix[limit]
			}
		}
		dp = next
	}

	var answer int64
	for _, ways := range dp {
		answer = (answer + ways) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
