	n := len(fields)
	nums := make([]int64, n)
	for i, field := range fields {
		value, _ := strconv.ParseInt(field, 10, 64)
		nums[i] = value
	}

	best := make([]int64, n*n)
	prev := make([]int64, n)

	for i, value := range nums {
		prev[i] = value
		best[i*n+i] = value
	}

	for length := 2; length <= n; length++ {
		count := n - length + 1
		cur := make([]int64, count)

		for left := 0; left < count; left++ {
			right := left + length - 1
			score := prev[left] ^ prev[left+1]
			cur[left] = score

			maxScore := score
			if v := best[(left+1)*n+right]; v > maxScore {
				maxScore = v
			}
			if v := best[left*n+right-1]; v > maxScore {
				maxScore = v
			}
			best[left*n+right] = maxScore
		}

		prev = cur
	}

	var q int
	if _, err := fmt.Fscan(reader, &q); err != nil {
		return
	}

