func main() {
	in := bufio.NewReader(os.Stdin)

	var kx, ky, n int
	if _, err := fmt.Fscan(in, &kx); err != nil {
		return
	}
	fmt.Fscan(in, &ky)
	fmt.Fscan(in, &n)

	points := make([]Point, n+1)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &points[i].x, &points[i].y)
	}
	points[n] = Point{kx, ky}

	dist := make([][]int, n+1)
	for i := range dist {
		dist[i] = make([]int, n+1)
	}

	directions := [8][2]int{
		{2, 1}, {2, -1}, {-2, 1}, {-2, -1},
		{1, 2}, {1, -2}, {-1, 2}, {-1, -2},
	}

	for source := 0; source <= n; source++ {
		boardDist := [50][50]int{}
		for x := 0; x < 50; x++ {
			for y := 0; y < 50; y++ {
				boardDist[x][y] = -1
			}
		}

		queue := make([]Point, 0, 2500)
		start := points[source]
		boardDist[start.x][start.y] = 0
		queue = append(queue, start)

		for head := 0; head < len(queue); head++ {
			cur := queue[head]
			for _, d := range directions {
				nx, ny := cur.x+d[0], cur.y+d[1]
				if nx >= 0 && nx < 50 && ny >= 0 && ny < 50 && boardDist[nx][ny] == -1 {
					boardDist[nx][ny] = boardDist[cur.x][cur.y] + 1
					queue = append(queue, Point{nx, ny})
				}
			}
		}

		for target := 0; target <= n; target++ {
			p := points[target]
			dist[source][target] = boardDist[p.x][p.y]
		}
	}

	totalMasks := 1 << n
	memo := make([]int, totalMasks*(n+1))
	for i := range memo {
		memo[i] = -1
	}

	fullMask := totalMasks - 1

	var solve func(mask, current int) int
	solve = func(mask, current int) int {
		if mask == fullMask {
			return 0
		}

		index := mask*(n+1) + current
		if memo[index] != -1 {
			return memo[index]
		}

		aliceTurn := bits.OnesCount(uint(mask))%2 == 0
		if aliceTurn {
			best := -1
			for pawn := 0; pawn < n; pawn++ {
				if mask&(1<<pawn) == 0 {
					value := dist[current][pawn] + solve(mask|(1<<pawn), pawn)
					if value > best {
						best = value
					}
				}
			}
			memo[index] = best
		} else {
			best := int(^uint(0) >> 1)
			for pawn := 0; pawn < n; pawn++ {
				if mask&(1<<pawn) == 0 {
					value := dist[current][pawn] + solve(mask|(1<<pawn), pawn)
					if value < best {
						best = value
					}
				}
			}
			memo[index] = best
		}

		return memo[index]
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, solve(0, n))
}
