	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	rows := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		rows, _ = strconv.Atoi(line)
		break
	}

	valueRows := make([]int, 101)
	row := 0
	for row < rows && scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		for _, field := range strings.Fields(line) {
			value, err := strconv.Atoi(field)
			if err == nil && value >= 1 && value <= 100 {
				valueRows[value] |= 1 << row
			}
		}
		row++
	}

	size := 1 << rows
	dp := make([]int, size)
	for i := 1; i < size; i++ {
		dp[i] = -1
	}

	for value := 1; value <= 100; value++ {
		available := valueRows[value]
		if available == 0 {
			continue
		}

		next := make([]int, size)
		copy(next, dp)

		for mask, score := range dp {
			if score < 0 {
				continue
			}

			choices := available &^ mask
			for choices != 0 {
				bit := choices & -choices
				newMask := mask | bit
				if score+value > next[newMask] {
					next[newMask] = score + value
				}
				choices -= bit
			}
		}
		dp = next
	}

	answer := 0
	for _, score := range dp {
		if score > answer {
			answer = score
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
