	if _, err := fmt.Fscan(in, &word1, &word2); err != nil {
		return
	}

	var required, window [26]int
	for i := 0; i < len(word2); i++ {
		required[word2[i]-'a']++
	}

	missing := len(word2)
	left := 0
	var answer int64

	for right := 0; right < len(word1); right++ {
		c := int(word1[right] - 'a')
		if window[c] < required[c] {
			missing--
		}
		window[c]++

		for missing == 0 {
			cLeft := int(word1[left] - 'a')
			window[cLeft]--
			if window[cLeft] < required[cLeft] {
				missing++
			}
			left++
		}

		answer += int64(left)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
