func zFunction(str string) []int {
	n := len(str)
	z := make([]int, n)
	for i, l, r := 1, 0, 0; i < n; i++ {
		if i <= r {
			z[i] = min(r-i+1, z[i-l])
		}
		for i+z[i] < n && str[z[i]] == str[i+z[i]] {
			z[i]++
		}
		if i+z[i]-1 > r {
			l, r = i, i+z[i]-1
		}
	}
	return z
}

func reverse(str string) string {
	b := []byte(str)
	for l, r := 0, len(b)-1; l < r; l, r = l+1, r-1 {
		b[l], b[r] = b[r], b[l]
	}
	return string(b)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s, pattern string
	if _, err := fmt.Fscan(in, &s, &pattern); err != nil {
		return
	}

	n, m := len(s), len(pattern)
	if m > n {
		fmt.Fprintln(out, -1)
		return
	}

	forward := zFunction(pattern + "#" + s)
	backward := zFunction(reverse(pattern) + "#" + reverse(s))

	for i := 0; i+m <= n; i++ {
		prefixMatch := min(forward[m+1+i], m)
		suffixStartInReversedS := n - (i + m)
		suffixMatch := min(backward[m+1+suffixStartInReversedS], m)

		if prefixMatch+suffixMatch >= m-1 {
			fmt.Fprintln(out, i)
			return
		}
	}

	fmt.Fprintln(out, -1)
}
