func parseLine(line string) []int64 {
	fields := strings.Fields(line)
	values := make([]int64, len(fields))
	for i, field := range fields {
		values[i], _ = strconv.ParseInt(field, 10, 64)
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 16*1024*1024)

	lines := make([]string, 0, 2)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
			if len(lines) == 2 {
				break
			}
		}
	}
	if len(lines) < 2 {
		return
	}

	numValues := parseLine(lines[0])
	queries := parseLine(lines[1])

	maxValue := 0
	for _, value := range numValues {
		if int(value) > maxValue {
			maxValue = int(value)
		}
	}

	frequency := make([]int64, maxValue+1)
	for _, value := range numValues {
		frequency[int(value)]++
	}

	exactPairs := make([]int64, maxValue+1)

	for gcd := maxValue; gcd >= 1; gcd-- {
		var divisibleCount int64
		for multiple := gcd; multiple <= maxValue; multiple += gcd {
			divisibleCount += frequency[multiple]
		}

		pairs := divisibleCount * (divisibleCount - 1) / 2
		for multiple := gcd * 2; multiple <= maxValue; multiple += gcd {
			pairs -= exactPairs[multiple]
		}
		exactPairs[gcd] = pairs
	}

	prefix := make([]int64, maxValue+1)
	for gcd := 1; gcd <= maxValue; gcd++ {
		prefix[gcd] = prefix[gcd-1] + exactPairs[gcd]
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for i, query := range queries {
		left, right := 1, maxValue
		for left < right {
			mid := left + (right-left)/2
			if prefix[mid] > query {
				right = mid
			} else {
				left = mid + 1
			}
		}

		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, left)
	}
	fmt.Fprintln(writer)
}
