const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, x, y int
	if _, err := fmt.Fscan(in, &n, &x, &y); err != nil {
		return
	}

	limit := n
	if x < limit {
		limit = x
	}

	// dp[k] is the Stirling number S(n, k) after all iterations.
	dp := make([]int64, limit+1)
	dp[0] = 1

	for i := 1; i <= n; i++ {
		upper := i
		if upper > limit {
			upper = limit
		}
		for k := upper; k >= 1; k-- {
			dp[k] = (dp[k-1] + int64(k)*dp[k]) % mod
		}
		dp[0] = 0
	}

	var answer int64
	falling := int64(1)
	scoreWays := int64(1)

	for k := 1; k <= limit; k++ {
		falling = falling * int64(x-k+1) % mod
		scoreWays = scoreWays * int64(y) % mod
		term := dp[k] * falling % mod * scoreWays % mod
		answer = (answer + term) % mod
	}

	fmt.Fprintln(out, answer)
}
