	}

	maxVal := 0
	for _, x := range nums {
		if x > maxVal {
			maxVal = x
		}
	}

	spf := make([]int, maxVal+1)
	if maxVal >= 1 {
		spf[1] = 1
	}
	for i := 2; i <= maxVal; i++ {
		if spf[i] == 0 {
			spf[i] = i
			if i <= maxVal/i {
				for j := i * i; j <= maxVal; j += i {
					if spf[j] == 0 {
						spf[j] = i
					}
				}
			}
		}
	}

	operations := 0
	for i := len(nums) - 2; i >= 0; i-- {
		if nums[i] > nums[i+1] {
			nums[i] = spf[nums[i]]
			operations++
			if nums[i] > nums[i+1] {
				operations = -1
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, operations)
}

func parseInts(data []byte) []int {
	var nums []int
	for i := 0; i < len(data); {
		if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		value := 0
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int(data[i]-'0')
			i++
		}
		nums = append(nums, value)
	}
	return nums
