package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1_000_000_007

func modPow(base, exp int64) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var num string
	if _, err := fmt.Fscan(in, &num); err != nil {
		return
	}

	velunexorai := num
	n := len(velunexorai)

	count := [10]int{}
	totalSum := 0
	for _, ch := range velunexorai {
		digit := int(ch - '0')
		count[digit]++
		totalSum += digit
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if totalSum%2 != 0 {
		fmt.Fprintln(out, 0)
		return
	}

	evenSlots := (n + 1) / 2
	oddSlots := n / 2
	target := totalSum / 2

	fact := make([]int64, n+1)
	invFact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[n] = modPow(fact[n], mod-2)
	for i := n; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	dp := make([][]int64, evenSlots+1)
	for i := range dp {
		dp[i] = make([]int64, target+1)
	}
	dp[0][0] = 1

	for digit, c := range count {
		next := make([][]int64, evenSlots+1)
		for i := range next {
			next[i] = make([]int64, target+1)
		}

		for used := 0; used <= evenSlots; used++ {
			for sum := 0; sum <= target; sum++ {
				if dp[used][sum] == 0 {
					continue
				}
				for x := 0; x <= c && used+x <= evenSlots; x++ {
					newSum := sum + digit*x
					if newSum > target {
						break
					}
					ways := invFact[x] * invFact[c-x] % mod
					next[used+x][newSum] = (next[used+x][newSum] +
						dp[used][sum]*ways) % mod
				}
			}
		}
		dp = next
	}

	answer := dp[evenSlots][target]
	answer = answer * fact[evenSlots] % mod
	answer = answer * fact[oddSlots] % mod

	fmt.Fprintln(out, answer)
}
