	"fmt"
	"os"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	var count [26]int
	for _, ch := range s {
		count[ch-'a']++
	}

	const inf = int(1e9)
	answer := inf

	for target := 1; target <= len(s); target++ {
		var dp [2]int
		dp[0] = count[0]
		dp[1] = abs(count[0] - target)

		for i := 1; i < 26; i++ {
			next := [2]int{inf, inf}

			for prevState := 0; prevState < 2; prevState++ {
				prevTarget := 0
				if prevState == 1 {
					prevTarget = target
				}
				surplus := count[i-1] - prevTarget
				if surplus < 0 {
					surplus = 0
				}

				for state := 0; state < 2; state++ {
					currentTarget := 0
					if state == 1 {
						currentTarget = target
					}

					deficit := currentTarget - count[i]
					if deficit < 0 {
						deficit = 0
					}

					saved := min(surplus, deficit)
					cost := dp[prevState] + abs(count[i]-currentTarget) - saved
					if cost < next[state] {
						next[state] = cost
					}
				}
			}

			dp = next
		}

		answer = min(answer, min(dp[0], dp[1]))
	}

	fmt.Fprintln(out, answer)
}
