		adjacentSum %= mod

		newCount := (1 + adjacentCount) % mod
		newSum := (int64(x) + adjacentSum + int64(x)*adjacentCount) % mod

		count[x] = (count[x] + newCount) % mod
		sum[x] = (sum[x] + newSum) % mod
		answer = (answer + newSum) % mod
	}

	out := bufio.NewWriter(os.Stdout)
