	size := 1 << n
	const inf int64 = 1 << 62

	dp := make([]int64, size)
	for i := 1; i < size; i++ {
		dp[i] = inf
	}

	for mask := 0; mask < size; mask++ {
		broken := 0
		for x := mask; x > 0; x &= x - 1 {
			broken++
		}

		factor := int64(1) + int64(broken)*k
		for i, required := range strength {
			if mask&(1<<i) != 0 {
				continue
			}

			minutes := (required + factor - 1) / factor
			nextMask := mask | (1 << i)
			if dp[mask]+minutes < dp[nextMask] {
				dp[nextMask] = dp[mask] + minutes
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
