func hasThreeSections(intervals []interval) bool {
	sort.Slice(intervals, func(i, j int) bool {
		if intervals[i].start == intervals[j].start {
			return intervals[i].end < intervals[j].end
		}
		return intervals[i].start < intervals[j].start
	})

	sections := 0
	currentEnd := -1

	for _, in := range intervals {
		if sections == 0 || in.start >= currentEnd {
			sections++
			currentEnd = in.end
			if sections >= 3 {
				return true
			}
		} else if in.end > currentEnd {
			currentEnd = in.end
		}
	}

	return false
}

func main() {
