package main

import (
	"fmt"
	"io"
	"os"
)

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := make([]int64, 0)

	for i := 0; i < len(data); {
		for i < len(data) && (data[i] < '0' || data[i] > '9') && data[i] != '-' {
			i++
		}
		if i >= len(data) {
			break
		}

		sign := int64(1)
		if data[i] == '-' {
			sign = -1
			i++
		}

		if i >= len(data) || data[i] < '0' || data[i] > '9' {
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		nums = append(nums, sign*value)
	}

	n := len(nums)
	if n < 2 {
		fmt.Println(0)
		return
	}

	var fixedMax int64
	const inf int64 = 1 << 62
	minBoundary, maxBoundary := inf, int64(-1)

	for i := 0; i < n-1; i++ {
		if nums[i] != -1 && nums[i+1] != -1 {
			d := abs(nums[i] - nums[i+1])
			if d > fixedMax {
				fixedMax = d
			}
		}
	}

	for i := 0; i < n; i++ {
		if nums[i] == -1 {
			continue
		}
		if (i > 0 && nums[i-1] == -1) || (i+1 < n && nums[i+1] == -1) {
			if nums[i] < minBoundary {
				minBoundary = nums[i]
			}
			if nums[i] > maxBoundary {
				maxBoundary = nums[i]
			}
		}
	}

	if minBoundary == inf {
		fmt.Println(fixedMax)
		return
	}

	can := func(limit int64) bool {
		if fixedMax > limit {
			return false
		}

		x := minBoundary + limit
		y := maxBoundary - limit
		if y < 1 {
			y = 1
		}

		covers := func(value, replacement int64) bool {
			return abs(value-replacement) <= limit
		}

		for i := 0; i < n; {
			if nums[i] != -1 {
				i++
				continue
			}

			start := i
			for i < n && nums[i] == -1 {
				i++
			}
			length := i - start

			hasLeft := start > 0
			hasRight := i < n

			if !hasLeft && !hasRight {
				continue
			}

			if hasLeft && !hasRight {
				left := nums[start-1]
				if !covers(left, x) && !covers(left, y) {
					return false
				}
				continue
			}

			if !hasLeft && hasRight {
				right := nums[i]
				if !covers(right, x) && !covers(right, y) {
					return false
				}
				continue
			}

			left, right := nums[start-1], nums[i]

			xBoth := covers(left, x) && covers(right, x)
			yBoth := covers(left, y) && covers(right, y)
			if xBoth || yBoth {
				continue
			}

			if length == 1 {
				return false
			}

			if abs(x-y) > limit {
				return false
			}

			opposite := (covers(left, x) && covers(right, y)) ||
				(covers(left, y) && covers(right, x))
			if !opposite {
				return false
			}
		}

		return true
	}

	low, high := fixedMax, int64(1_000_000_000)
	for low < high {
		mid := low + (high-low)/2
		if can(mid) {
			high = mid
		} else {
			low = mid + 1
		}
	}

	fmt.Println(low)
}
