package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DSU struct {
	parent []int
	size   []int
	count  int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size, count: n}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}

func (d *DSU) Union(a, b int) {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return
	}
	if d.size[ra] < d.size[rb] {
		ra, rb = rb, ra
	}
	d.parent[rb] = ra
	d.size[ra] += d.size[rb]
	d.count--
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 4*1024*1024)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) < 2 {
		return
	}

	fields := strings.Fields(lines[0])
	nums := make([]int, 0, len(fields))
	for _, field := range fields {
		value, err := strconv.Atoi(field)
		if err == nil {
			nums = append(nums, value)
		}
	}

	thresholdFields := strings.Fields(lines[1])
	if len(thresholdFields) == 0 {
		return
	}
	threshold, err := strconv.Atoi(thresholdFields[0])
	if err != nil {
		return
	}

	dsu := NewDSU(len(nums))
	owner := make([]int, threshold+1)
	for i := range owner {
		owner[i] = -1
	}

	for i, value := range nums {
		if value > threshold {
			continue
		}
		for multiple := value; multiple <= threshold; multiple += value {
			if owner[multiple] == -1 {
				owner[multiple] = i
			} else {
				dsu.Union(i, owner[multiple])
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, dsu.count)
}
