type Point struct {
	x, y int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	points := make([]Point, n)
	exists := make(map[Point]bool, n)
	for i := range points {
		fmt.Fscan(in, &points[i].x, &points[i].y)
		exists[points[i]] = true
	}

	maxArea := -1

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if points[i].x == points[j].x || points[i].y == points[j].y {
				continue
			}

			minX, maxX := points[i].x, points[j].x
			if minX > maxX {
				minX, maxX = maxX, minX
			}
			minY, maxY := points[i].y, points[j].y
			if minY > maxY {
				minY, maxY = maxY, minY
			}

			if !exists[Point{minX, minY}] ||
				!exists[Point{minX, maxY}] ||
				!exists[Point{maxX, minY}] ||
				!exists[Point{maxX, maxY}] {
				continue
			}

			valid := true
			for _, p := range points {
				if p.x < minX || p.x > maxX || p.y < minY || p.y > maxY {
					continue
				}
				isCorner := (p.x == minX || p.x == maxX) &&
					(p.y == minY || p.y == maxY)
				if !isCorner {
					valid = false
					break
				}
			}

			if valid {
				area := (maxX - minX) * (maxY - minY)
				if area > maxArea {
					maxArea = area
				}
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxArea)
}
