const mod int64 = 1_000_000_007

func modPow(base, exp int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m, k int64
	if _, err := fmt.Fscan(in, &n, &m, &k); err != nil {
		return
	}

	total := n - 1

	fact := make([]int64, total+1)
	invFact := make([]int64, total+1)
	fact[0] = 1
	for i := int64(1); i <= total; i++ {
		fact[i] = fact[i-1] * i % mod
	}

	invFact[total] = modPow(fact[total], mod-2)
	for i := total; i > 0; i-- {
		invFact[i-1] = invFact[i] * i % mod
	}

	combinations := fact[total] * invFact[k] % mod * invFact[total-k] % mod
	answer := (m % mod) * combinations % mod
	answer = answer * modPow(m-1, total-k) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
