func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	nums := make([]int, 0, 5000)
	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	n := len(nums)
	if n < 3 {
		fmt.Println(0)
		return
	}

	// Z[i] is the longest common prefix of nums and nums[i:].
	z := make([]int, n)
	z[0] = n
	for i, left, right := 1, 0, 0; i < n; i++ {
		if i <= right {
			k := i - left
			if z[k] < right-i+1 {
				z[i] = z[k]
			} else {
				z[i] = right - i + 1
			}
		}
		for i+z[i] < n && nums[z[i]] == nums[i+z[i]] {
			z[i]++
		}
		if i+z[i]-1 > right {
			left = i
			right = i + z[i] - 1
		}
	}

	// next[j] stores LCP(nums[i+1:], nums[j:]) for the previous row.
	next := make([]int, n+1)
	current := make([]int, n+1)

	answer := 0

	for i := n - 2; i >= 1; i-- {
		for j := i + 1; j < n; j++ {
			if nums[i] == nums[j] {
				current[j] = next[j+1] + 1
			} else {
				current[j] = 0
			}

			firstCondition := j >= 2*i && z[i] >= i

			middleLength := j - i
			thirdLength := n - j
			secondCondition := thirdLength >= middleLength &&
				current[j] >= middleLength

			if firstCondition || secondCondition {
				answer++
			}
		}

		next, current = current, next
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
