package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	sum    int64
	prefix int64
	suffix int64
	best   int64
}

type SegmentTree struct {
	n    int
	tree []Node
}

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func merge(left, right Node) Node {
	return Node{
		sum:    left.sum + right.sum,
		prefix: max(left.prefix, left.sum+right.prefix),
		suffix: max(right.suffix, right.sum+left.suffix),
		best:   max(max(left.best, right.best), left.suffix+right.prefix),
	}
}

func NewSegmentTree(nums []int64) *SegmentTree {
	st := &SegmentTree{
		n:    len(nums),
		tree: make([]Node, 4*len(nums)),
	}
	st.build(1, 0, len(nums)-1, nums)
	return st
}

func (st *SegmentTree) build(node, left, right int, nums []int64) {
	if left == right {
		value := nums[left]
		st.tree[node] = Node{value, value, value, value}
		return
	}

	mid := left + (right-left)/2
	st.build(node*2, left, mid, nums)
	st.build(node*2+1, mid+1, right, nums)
	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) Update(index int, value int64) {
	st.update(1, 0, st.n-1, index, value)
}

func (st *SegmentTree) update(node, left, right, index int, value int64) {
	if left == right {
		st.tree[node] = Node{value, value, value, value}
		return
	}

	mid := left + (right-left)/2
	if index <= mid {
		st.update(node*2, left, mid, index, value)
	} else {
		st.update(node*2+1, mid+1, right, index, value)
	}
	st.tree[node] = merge(st.tree[node*2], st.tree[node*2+1])
}

func (st *SegmentTree) MaxSubarraySum() int64 {
	return st.tree[1].best
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var nums []int64
	var value int64
	for {
		if _, err := fmt.Fscan(in, &value); err != nil {
			break
		}
		nums = append(nums, value)
	}

	if len(nums) == 0 {
		return
	}

	positions := make(map[int64][]int)
	for i, v := range nums {
		if v < 0 {
			positions[v] = append(positions[v], i)
		}
	}

	tree := NewSegmentTree(nums)
	answer := tree.MaxSubarraySum()

	for v, indices := range positions {
		for _, index := range indices {
			tree.Update(index, 0)
		}

		candidate := tree.MaxSubarraySum()
		if candidate > 0 && candidate > answer {
			answer = candidate
		}

		for _, index := range indices {
			tree.Update(index, v)
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
