func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	var numOps int
	if _, err := fmt.Fscan(in, &s, &numOps); err != nil {
		return
	}

	canAchieve := func(maxRun int) bool {
		if maxRun == 1 {
			mismatch0, mismatch1 := 0, 0
			for i := 0; i < len(s); i++ {
				expected0 := byte('0' + byte(i%2))
				expected1 := byte('1' - byte(i%2))
				if s[i] != expected0 {
					mismatch0++
				}
				if s[i] != expected1 {
					mismatch1++
				}
			}
			if mismatch1 < mismatch0 {
				mismatch0 = mismatch1
			}
			return mismatch0 <= numOps
		}

		operations := 0
		for i := 0; i < len(s); {
			j := i + 1
			for j < len(s) && s[j] == s[i] {
				j++
			}
			operations += (j - i) / (maxRun + 1)
			if operations > numOps {
				return false
			}
			i = j
		}
		return true
	}

	left, right := 1, len(s)
	for left < right {
		mid := left + (right-left)/2
		if canAchieve(mid) {
			right = mid
		} else {
			left = mid + 1
		}
	}

	fmt.Fprintln(out, left)
}
