	var answer int64

	for r := 4; r <= n-3; r++ {
		q := r - 2

		for p := 0; p <= q-2; p++ {
			g := gcd(nums[p], nums[q])
			key := ratio{nums[p] / g, nums[q] / g}
			counts[key]++
		}

		for s := r + 2; s < n; s++ {
			g := gcd(nums[s], nums[r])
			key := ratio{nums[s] / g, nums[r] / g}
			answer += counts[key]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
