package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const mod int64 = 1_000_000_007

func choose(count int64, selected int) int64 {
	switch selected {
	case 0:
		return 1
	case 1:
		return count
	case 2:
		if count < 2 {
			return 0
		}
		return count * (count - 1) / 2
	default:
		return 0
	}
}

// Counts ways to select one element from singleSide and two elements
// from pairSide such that all three values are distinct and none equals x.
func distinctTriples(
	singleSide, pairSide map[int64]int64,
	x int64,
	pairTotal int64,
) int64 {
	distinctPairs := choose(pairTotal, 2)
	for value, count := range pairSide {
		if value != x {
			distinctPairs -= choose(count, 2)
		}
	}

	var result int64
	for value, singleCount := range singleSide {
		if value == x {
			continue
		}
		pairCount := pairSide[value]
		validPairs := distinctPairs - pairCount*(pairTotal-pairCount)
		result += singleCount * validPairs
	}
	return result
}

func parseIntegers(data []byte) []int64 {
	nums := make([]int64, 0)
	for i := 0; i < len(data); {
		sign := int64(1)
		if data[i] == '-' && i+1 < len(data) &&
			data[i+1] >= '0' && data[i+1] <= '9' {
			sign = -1
			i++
		} else if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		nums = append(nums, sign*value)
	}
	return nums
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	nums := parseIntegers(data)

	n := len(nums)
	if n < 5 {
		fmt.Println(0)
		return
	}

	left := make(map[int64]int64)
	right := make(map[int64]int64)
	for _, value := range nums {
		right[value]++
	}

	var answer int64

	for i, x := range nums {
		right[x]--
		if right[x] == 0 {
			delete(right, x)
		}

		leftTotal := int64(i)
		rightTotal := int64(n - i - 1)

		leftX := left[x]
		rightX := right[x]
		leftNonX := leftTotal - leftX
		rightNonX := rightTotal - rightX

		// At least two additional occurrences of x are selected.
		// Then x appears at least three times and is automatically
		// the unique mode.
		for selectedLeftX := 0; selectedLeftX <= 2; selectedLeftX++ {
			for selectedRightX := 0; selectedRightX <= 2; selectedRightX++ {
				if selectedLeftX+selectedRightX < 2 {
					continue
				}

				waysLeft := choose(leftX, selectedLeftX) *
					choose(leftNonX, 2-selectedLeftX)
				waysRight := choose(rightX, selectedRightX) *
					choose(rightNonX, 2-selectedRightX)

				answer += waysLeft * waysRight
			}
		}

		// Exactly one additional x is selected. The other three values
		// must be pairwise distinct for x to be the unique mode.
		if leftX > 0 {
			answer += leftX * distinctTriples(
				left, right, x, rightNonX,
			)
		}
		if rightX > 0 {
			answer += rightX * distinctTriples(
				right, left, x, leftNonX,
			)
		}

		left[x]++
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer%mod)
}
