package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

type Point struct {
	r, c int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var H, W, T int
	fmt.Fscan(in, &H, &W, &T)

	grid := make([][]byte, H)
	var start, goal Point
	candies := make([]Point, 0, 18)

	for i := 0; i < H; i++ {
		var row string
		fmt.Fscan(in, &row)
		grid[i] = []byte(row)
		for j, ch := range grid[i] {
			switch ch {
			case 'S':
				start = Point{i, j}
			case 'G':
				goal = Point{i, j}
			case 'o':
				candies = append(candies, Point{i, j})
			}
		}
	}

	n := len(candies)
	points := make([]Point, 0, n+2)
	points = append(points, candies...)
	points = append(points, start, goal)

	k := len(points)
	pairDist := make([]int32, k*k)
	for i := range pairDist {
		pairDist[i] = -1
	}

	totalCells := H * W
	dist := make([]int32, totalCells)
	queue := make([]int, totalCells)

	for source := 0; source < k; source++ {
		for i := range dist {
			dist[i] = -1
		}

		startIndex := points[source].r*W + points[source].c
		head, tail := 0, 1
		queue[0] = startIndex
		dist[startIndex] = 0

		for head < tail {
			v := queue[head]
			head++
			r, c := v/W, v%W
			nextDist := dist[v] + 1

			if r > 0 {
				to := v - W
				if grid[r-1][c] != '#' && dist[to] == -1 {
					dist[to] = nextDist
					queue[tail] = to
					tail++
				}
			}
			if r+1 < H {
				to := v + W
				if grid[r+1][c] != '#' && dist[to] == -1 {
					dist[to] = nextDist
					queue[tail] = to
					tail++
				}
			}
			if c > 0 {
				to := v - 1
				if grid[r][c-1] != '#' && dist[to] == -1 {
					dist[to] = nextDist
					queue[tail] = to
					tail++
				}
			}
			if c+1 < W {
				to := v + 1
				if grid[r][c+1] != '#' && dist[to] == -1 {
					dist[to] = nextDist
					queue[tail] = to
					tail++
				}
			}
		}

		for j, p := range points {
			pairDist[source*k+j] = dist[p.r*W+p.c]
		}
	}

	startID, goalID := n, n+1
	direct := pairDist[startID*k+goalID]
	if direct < 0 || int(direct) > T {
		fmt.Fprintln(out, -1)
		return
	}

	if n == 0 {
		fmt.Fprintln(out, 0)
		return
	}

	const inf int32 = 1 << 30
	maskCount := 1 << n
	dp := make([]int32, maskCount*n)
	for i := range dp {
		dp[i] = inf
	}

	for i := 0; i < n; i++ {
		d := pairDist[startID*k+i]
		if d >= 0 && int(d) <= T {
			dp[(1<<i)*n+i] = d
		}
	}

	answer := 0

	for mask := 1; mask < maskCount; mask++ {
		count := bits.OnesCount(uint(mask))
		base := mask * n

		for last := 0; last < n; last++ {
			if mask&(1<<last) == 0 {
				continue
			}

			current := dp[base+last]
			if current == inf {
				continue
			}

			toGoal := pairDist[last*k+goalID]
			if toGoal >= 0 && int(current+toGoal) <= T && count > answer {
				answer = count
			}

			remaining := (maskCount - 1) ^ mask
			for remaining != 0 {
				bit := remaining & -remaining
				next := bits.TrailingZeros(uint(bit))
				remaining -= bit

				d := pairDist[last*k+next]
				if d < 0 {
					continue
				}

				nextDist := current + d
				if int(nextDist) > T {
					continue
				}

				nextMask := mask | bit
				index := nextMask*n + next
				if nextDist < dp[index] {
					dp[index] = nextDist
				}
			}
		}
	}

	fmt.Fprintln(out, answer)
}
