	for i := 1; i <= 26; i++ {
		inv[i] = modPow(int64(i), mod-2)
	}

	// mono[i] is the number of replacements of s[i:] whose character
	// categories have the form uppercase* lowercase*.
	mono := make([]int64, n+1)
	mono[n] = 1
	lowNext := int64(1)

	for i := n - 1; i >= 0; i-- {
		ch := s[i]
		var currentMono, currentLow int64

		switch {
		case ch == '?':
			currentMono = 26 * ((mono[i+1] + lowNext) % mod) % mod
			currentLow = 26 * lowNext % mod
		case ch >= 'A' && ch <= 'Z':
			currentMono = mono[i+1]
			currentLow = 0
		default:
			currentMono = lowNext
			currentLow = lowNext
		}

		mono[i] = currentMono
		lowNext = currentLow
	}

	// For a prefix containing w question marks and r distinct fixed
	// uppercase letters:
	// F is the number of replacements with all uppercase letters distinct.
	// G is the sum of the number of uppercase letters over those replacements.
	calc := func(w, r int) (int64, int64) {
		available := 26 - r
		limit := w
		if limit > available {
			limit = available
		}

		comb := int64(1)
		falling := int64(1)
		var f, g int64

		for m := 0; m <= limit; m++ {
			term := comb * falling % mod * pow26[w-m] % mod
			f += term
			if f >= mod {
				f -= mod
			}
			g = (g + term*int64(r+m)) % mod

			if m < limit {
				comb = comb * int64(w-m) % mod * inv[m+1] % mod
				falling = falling * int64(available-m) % mod
			}
		}
		return f, g
	}

	var answer int64
	var fixedMask uint32
	wildcards := 0
	distinctFixed := 0
	uniquePrefixPossible := true

	for i := 0; i < n; i++ {
		ch := s[i]

		if uniquePrefixPossible {
			f, g := calc(wildcards, distinctFixed)

			if ch == '?' {
				// Choose an uppercase letter already present in the prefix.
				answer = (answer + g*mono[i+1]) % mod
				wildcards++
			} else if ch >= 'A' && ch <= 'Z' {
				bit := uint32(1) << uint(ch-'A')
				var repeatWays int64

				if fixedMask&bit != 0 {
					repeatWays = f
				} else {
					available := 26 - distinctFixed
					weightedWildUpper := (g - int64(distinctFixed)*f) % mod
					if weightedWildUpper < 0 {
						weightedWildUpper += mod
					}
					repeatWays = weightedWildUpper * inv[available] % mod
				}

				answer = (answer + repeatWays*mono[i+1]) % mod

				if fixedMask&bit != 0 {
					uniquePrefixPossible = false
				} else {
					fixedMask |= bit
					distinctFixed++
				}
			}
		}
	}

	// Replacements having no repeated uppercase letter at all.
	if uniquePrefixPossible {
		f, _ := calc(wildcards, distinctFixed)
		answer = (answer + f) % mod
	}

	fmt.Fprintln(out, answer)
}

func modPow(base, exp int64) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}
