type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	sets := make([][]int, n)
	containing := make([][]int, m+1)
	hasM := make([]bool, n)

	for i := 0; i < n; i++ {
		a := in.NextInt()
		sets[i] = make([]int, a)
		for j := 0; j < a; j++ {
			x := in.NextInt()
			sets[i][j] = x
			containing[x] = append(containing[x], i)
			if x == m {
				hasM[i] = true
			}
		}
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}

	queue := make([]int, 0, n)
	for _, setID := range containing[1] {
		dist[setID] = 0
		queue = append(queue, setID)
	}

	usedElement := make([]bool, m+1)

	for head := 0; head < len(queue); head++ {
		setID := queue[head]

		if hasM[setID] {
			fmt.Fprintln(out, dist[setID])
			return
		}

		for _, x := range sets[setID] {
			if usedElement[x] {
				continue
			}
			usedElement[x] = true

			for _, nextSet := range containing[x] {
				if dist[nextSet] == -1 {
					dist[nextSet] = dist[setID] + 1
					queue = append(queue, nextSet)
				}
			}
		}
	}

	fmt.Fprintln(out, -1)
}
