	for i := 0; i < n; i++ {
		if len(graph[i]) == 1 {
			start = i
			break
		}
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}
	dist[start] = 0

	queue := make([]int, 0, n)
	queue = append(queue, start)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, next := range graph[v] {
			if dist[next] == -1 {
				dist[next] = dist[v] + 1
				queue = append(queue, next)
			}
		}
	}

	levels := make([]int, 0)
	for v := 0; v < n; v++ {
		if dist[v]%3 == 1 {
			levels = append(levels, len(graph[v]))
		}
