package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Item struct {
	vertex  int
	stamina int
}

type MaxHeap []Item

func (h MaxHeap) Len() int {
	return len(h)
}

func (h MaxHeap) Less(i, j int) bool {
	return h[i].stamina > h[j].stamina
}

func (h MaxHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Item))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, k int
	fmt.Fscan(in, &n, &m, &k)

	graph := make([][]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	best := make([]int, n)
	for i := range best {
		best[i] = -1
	}

	pq := &MaxHeap{}
	heap.Init(pq)

	for i := 0; i < k; i++ {
		var p, h int
		fmt.Fscan(in, &p, &h)
		p--
		if h > best[p] {
			best[p] = h
			heap.Push(pq, Item{vertex: p, stamina: h})
		}
	}

	for pq.Len() > 0 {
		current := heap.Pop(pq).(Item)
		v, stamina := current.vertex, current.stamina

		if best[v] != stamina {
			continue
		}
		if stamina == 0 {
			continue
		}

		nextStamina := stamina - 1
		for _, next := range graph[v] {
			if best[next] < nextStamina {
				best[next] = nextStamina
				heap.Push(pq, Item{vertex: next, stamina: nextStamina})
			}
		}
	}

	guarded := make([]int, 0)
	for i, stamina := range best {
		if stamina >= 0 {
			guarded = append(guarded, i+1)
		}
	}

	fmt.Fprintln(out, len(guarded))
	for i, v := range guarded {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v)
	}
	fmt.Fprintln(out)
}
