const mod int64 = 998244353

func modPow(base, exp int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int64
	fmt.Fscan(in, &n, &m)

	x := (m - 1) % mod
	answer := modPow(x, n)
	if n%2 == 0 {
		answer = (answer + x) % mod
	} else {
		answer = (answer - x + mod) % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
