func main() {
	in := bufio.NewReader(os.Stdin)

	var n, t, m int
	fmt.Fscan(in, &n, &t, &m)

	incompatible := make([]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		incompatible[a] |= 1 << b
		incompatible[b] |= 1 << a
	}

	teams := make([]int, t)

	var dfs func(player, teamCount int) int64
	dfs = func(player, teamCount int) int64 {
		if teamCount > t || teamCount+n-player < t {
			return 0
		}
		if player == n {
			if teamCount == t {
				return 1
			}
			return 0
		}

		var ways int64

		for i := 0; i < teamCount; i++ {
			if teams[i]&incompatible[player] == 0 {
				teams[i] |= 1 << player
				ways += dfs(player+1, teamCount)
				teams[i] &^= 1 << player
			}
		}

		if teamCount < t {
			teams[teamCount] = 1 << player
			ways += dfs(player+1, teamCount+1)
			teams[teamCount] = 0
		}

		return ways
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 0))
}
