	fmt.Fscan(in, &n, &m)

	grid := make([]string, n)
	for i := range grid {
		fmt.Fscan(in, &grid[i])
	}

	reached := make([][]bool, n)
	touched := make([][]bool, n)
	for i := 0; i < n; i++ {
		reached[i] = make([]bool, m)
		touched[i] = make([]bool, m)
	}

	start := Point{1, 1}
	reached[start.r][start.c] = true
	touched[start.r][start.c] = true

	queue := make([]Point, 0, n*m)
	queue = append(queue, start)

	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for head := 0; head < len(queue); head++ {
		cur := queue[head]

		for d := 0; d < 4; d++ {
			r, c := cur.r, cur.c

			for grid[r+dr[d]][c+dc[d]] == '.' {
				r += dr[d]
				c += dc[d]
				touched[r][c] = true
			}

			if !reached[r][c] {
				reached[r][c] = true
				queue = append(queue, Point{r, c})
			}
		}
	}

	answer := 0
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if touched[i][j] {
				answer++
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
