import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	h := in.NextInt()
	w := in.NextInt()
	n := in.NextInt()

	holed := make([]bool, h*w)
	for i := 0; i < n; i++ {
		a := in.NextInt() - 1
		b := in.NextInt() - 1
		holed[a*w+b] = true
	}

	dp := make([]int, w+1)
	var answer int64

	for i := 0; i < h; i++ {
		diagonal := 0
		for j := 1; j <= w; j++ {
			top := dp[j]
			if holed[i*w+j-1] {
				dp[j] = 0
			} else {
				dp[j] = min3(top, dp[j-1], diagonal) + 1
				answer += int64(dp[j])
			}
			diagonal = top
		}
	}

	fmt.Fprintln(out, answer)
}
