package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	n := in.NextInt()

	const size = 100
	const yz = size * size
	grid := make([]int32, size*size*size)

	for id := 1; id <= n; id++ {
		x1 := in.NextInt()
		y1 := in.NextInt()
		z1 := in.NextInt()
		x2 := in.NextInt()
		y2 := in.NextInt()
		z2 := in.NextInt()

		for x := x1; x < x2; x++ {
			for y := y1; y < y2; y++ {
				base := x*yz + y*size
				for z := z1; z < z2; z++ {
					grid[base+z] = int32(id)
				}
			}
		}
	}

	pairs := make([]uint64, 0, 3*size*size*(size-1))

	addPair := func(a, b int32) {
		if a == 0 || b == 0 || a == b {
			return
		}
		if a > b {
			a, b = b, a
		}
		key := uint64(uint32(a))<<32 | uint64(uint32(b))
		pairs = append(pairs, key)
	}

	for x := 0; x < size; x++ {
		for y := 0; y < size; y++ {
			base := x*yz + y*size
			for z := 0; z < size; z++ {
				idx := base + z
				id := grid[idx]
				if id == 0 {
					continue
				}
				if x+1 < size {
					addPair(id, grid[idx+yz])
				}
				if y+1 < size {
					addPair(id, grid[idx+size])
				}
				if z+1 < size {
					addPair(id, grid[idx+1])
				}
			}
		}
	}

	sort.Slice(pairs, func(i, j int) bool {
		return pairs[i] < pairs[j]
	})

	answer := make([]int, n+1)
	var previous uint64
	for i, key := range pairs {
		if i > 0 && key == previous {
			continue
		}
		previous = key
		a := int(key >> 32)
		b := int(uint32(key))
		answer[a]++
		answer[b]++
	}

	out := make([]byte, 0, n*4)
	for i := 1; i <= n; i++ {
		out = strconv.AppendInt(out, int64(answer[i]), 10)
		out = append(out, '\n')
	}
	_, _ = os.Stdout.Write(out)
}
