package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

type Wheel struct {
	cost   int
	p      int
	scores []int
	zeros  int
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	fmt.Fscan(in, &n, &m)

	wheels := make([]Wheel, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &wheels[i].cost, &wheels[i].p)
		wheels[i].scores = make([]int, wheels[i].p)
		for j := 0; j < wheels[i].p; j++ {
			fmt.Fscan(in, &wheels[i].scores[j])
			if wheels[i].scores[j] == 0 {
				wheels[i].zeros++
			}
		}
	}

	// dp[r] is the minimum expected additional cost when r more points
	// are needed. Positive outcomes always transition to a smaller r.
	dp := make([]float64, m+1)

	for r := 1; r <= m; r++ {
		best := math.Inf(1)

		for _, w := range wheels {
			numerator := float64(w.cost * w.p)

			for _, score := range w.scores {
				if score == 0 {
					continue
				}
				next := r - score
				if next < 0 {
					next = 0
				}
				numerator += dp[next]
			}

			expected := numerator / float64(w.p-w.zeros)
			if expected < best {
				best = expected
			}
		}

		dp[r] = best
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintf(out, "%.17g\n", dp[m])
}
