package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func find(parent []int, x int) int {
	root := x
	for parent[root] != root {
		root = parent[root]
	}
	for parent[x] != x {
		next := parent[x]
		parent[x] = root
		x = next
	}
	return root
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	totalNodes := 2*n - 1

	parent := make([]int, totalNodes)
	size := make([]int, totalNodes)
	left := make([]int, totalNodes)
	right := make([]int, totalNodes)
	value := make([]int64, totalNodes)

	for i := 0; i < totalNodes; i++ {
		parent[i] = i
	}
	for i := 0; i < n; i++ {
		size[i] = 1
	}

	inv := make([]int64, n+1)
	inv[1] = 1
	for i := 2; i <= n; i++ {
		inv[i] = MOD - (MOD/int64(i))*inv[int(MOD%int64(i))]%MOD
	}

	for i := 0; i < n-1; i++ {
		p := in.NextInt() - 1
		q := in.NextInt() - 1

		rootP := find(parent, p)
		rootQ := find(parent, q)
		newRoot := n + i

		left[newRoot] = rootP
		right[newRoot] = rootQ

		combinedSize := size[rootP] + size[rootQ]
		value[rootP] = (value[rootP] + int64(size[rootP])*inv[combinedSize]) % MOD
		value[rootQ] = (value[rootQ] + int64(size[rootQ])*inv[combinedSize]) % MOD

		size[newRoot] = combinedSize
		parent[rootP] = newRoot
		parent[rootQ] = newRoot
		parent[newRoot] = newRoot
	}

	root := find(parent, 0)
	stack := make([]int, 0, totalNodes)
	stack = append(stack, root)

	for len(stack) > 0 {
		last := len(stack) - 1
		node := stack[last]
		stack = stack[:last]

		if node >= n {
			l, r := left[node], right[node]
			value[l] = (value[l] + value[node]) % MOD
			value[r] = (value[r] + value[node]) % MOD
			stack = append(stack, l, r)
		}
	}

	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value[i])
	}
	fmt.Fprintln(out)
}
