package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) Next() []byte {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func (fs *FastScanner) NextInt() int {
	token := fs.Next()
	n := 0
	for _, c := range token {
		n = n*10 + int(c-'0')
	}
	return n
}

func main() {
	in := NewFastScanner()
	H := in.NextInt()
	W := in.NextInt()

	grid := make([][]byte, H)
	rowCount := make([][26]int, H)
	colCount := make([][26]int, W)
	rowKinds := make([]int, H)
	colKinds := make([]int, W)

	for i := 0; i < H; i++ {
		s := in.Next()
		grid[i] = append([]byte(nil), s...)
		for j, ch := range grid[i] {
			k := int(ch - 'a')
			if rowCount[i][k] == 0 {
				rowKinds[i]++
			}
			if colCount[j][k] == 0 {
				colKinds[j]++
			}
			rowCount[i][k]++
			colCount[j][k]++
		}
	}

	activeRow := make([]bool, H)
	activeCol := make([]bool, W)
	for i := range activeRow {
		activeRow[i] = true
	}
	for j := range activeCol {
		activeCol[j] = true
	}

	activeRows, activeCols := H, W
	removeRows := make([]int, 0)
	removeCols := make([]int, 0)

	if activeCols >= 2 {
		for i := 0; i < H; i++ {
			if rowKinds[i] == 1 {
				removeRows = append(removeRows, i)
			}
		}
	}
	if activeRows >= 2 {
		for j := 0; j < W; j++ {
			if colKinds[j] == 1 {
				removeCols = append(removeCols, j)
			}
		}
	}

	for len(removeRows) > 0 || len(removeCols) > 0 {
		for _, i := range removeRows {
			activeRow[i] = false
		}
		for _, j := range removeCols {
			activeCol[j] = false
		}
		activeRows -= len(removeRows)
		activeCols -= len(removeCols)

		for _, i := range removeRows {
			for j := 0; j < W; j++ {
				if !activeCol[j] {
					continue
				}
				k := int(grid[i][j] - 'a')
				colCount[j][k]--
				if colCount[j][k] == 0 {
					colKinds[j]--
				}
			}
		}

		for _, j := range removeCols {
			for i := 0; i < H; i++ {
				if !activeRow[i] {
					continue
				}
				k := int(grid[i][j] - 'a')
				rowCount[i][k]--
				if rowCount[i][k] == 0 {
					rowKinds[i]--
				}
			}
		}

		hadRemovedRows := len(removeRows) > 0
		hadRemovedCols := len(removeCols) > 0
		nextRows := make([]int, 0)
		nextCols := make([]int, 0)

		if hadRemovedCols && activeCols >= 2 {
			for i := 0; i < H; i++ {
				if activeRow[i] && rowKinds[i] == 1 {
					nextRows = append(nextRows, i)
				}
			}
		}
		if hadRemovedRows && activeRows >= 2 {
			for j := 0; j < W; j++ {
				if activeCol[j] && colKinds[j] == 1 {
					nextCols = append(nextCols, j)
				}
			}
		}

		removeRows = nextRows
		removeCols = nextCols
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, activeRows*activeCols)
}
