	var n, d int
	var p int64
	fmt.Fscan(in, &n, &d, &p)

	fares := make([]int64, n)
	var total int64
	for i := range fares {
		fmt.Fscan(in, &fares[i])
		total += fares[i]
	}

	sort.Slice(fares, func(i, j int) bool {
		return fares[i] > fares[j]
	})

	answer := total
	var coveredFare int64

	batches := (n + d - 1) / d
	for k := 1; k <= batches; k++ {
		end := k * d
		if end > n {
			end = n
		}
		start := (k - 1) * d
		for i := start; i < end; i++ {
			coveredFare += fares[i]
		}

		cost := int64(k)*p + total - coveredFare
		if cost < answer {
			answer = cost
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
