	var dfs func(mask int)
	dfs = func(mask int) {
		if mask == (1<<9)-1 {
			good++
			return
		}

		for cell := 0; cell < 9; cell++ {
			if mask&(1<<cell) != 0 {
				continue
			}

			disappointed := false
			for _, line := range lines {
				pos := -1
				for i := 0; i < 3; i++ {
					if line[i] == cell {
						pos = i
						break
					}
				}
				if pos == -1 {
					continue
				}

				a := line[(pos+1)%3]
				b := line[(pos+2)%3]
				if mask&(1<<a) != 0 &&
					mask&(1<<b) != 0 &&
					values[a] == values[b] &&
					values[cell] != values[a] {
					disappointed = true
					break
				}
			}

			if !disappointed {
				dfs(mask | (1 << cell))
			}
		}
	}

	dfs(0)

