	var n, m int
	fmt.Fscan(in, &n, &m)

	lengths := make([]int64, n)
	var maxLength, totalWidth int64

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &lengths[i])
		if lengths[i] > maxLength {
			maxLength = lengths[i]
		}
		totalWidth += lengths[i]
	}
	totalWidth += int64(n - 1)

	canFit := func(width int64) bool {
		lines := 1
		currentWidth := int64(0)

		for _, length := range lengths {
			if currentWidth == 0 {
				currentWidth = length
			} else if currentWidth+1+length <= width {
				currentWidth += 1 + length
			} else {
				lines++
				currentWidth = length
				if lines > m {
					return false
				}
			}
		}
		return true
	}

	low := maxLength - 1
	high := totalWidth

	for high-low > 1 {
		mid := low + (high-low)/2
		if canFit(mid) {
			high = mid
		} else {
			low = mid
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, high)
