package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	x := in.NextInt64()
	y := in.NextInt64()

	const period = 840
	arrival := make([]int64, period)
	for r := 0; r < period; r++ {
		arrival[r] = int64(r) + x
	}

	for i := 0; i < n-1; i++ {
		p := in.NextInt64()
		t := in.NextInt64()

		for r := 0; r < period; r++ {
			current := arrival[r]
			if rem := current % p; rem != 0 {
				current += p - rem
			}
			arrival[r] = current + t
		}
	}

	for r := 0; r < period; r++ {
		arrival[r] += y
	}

	q := int(in.NextInt64())
	for i := 0; i < q; i++ {
		start := in.NextInt64()
		residue := start % period
		answer := start - residue + arrival[int(residue)]
		fmt.Fprintln(out, answer)
	}
}
