			for i, j := left, right; i < j; i, j = i+1, j-1 {
				if s[i] != s[j] {
					palindrome = false
					break
				}
			}
			if palindrome && right-left+1 > maxLen {
				maxLen = right - left + 1
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, maxLen)
}
