	for i := 0; i < m; i++ {
		var a, b int
		var x, y int64
		fmt.Fscan(in, &a, &b, &x, &y)
		a--
		b--
		graph[a] = append(graph[a], Edge{to: b, dx: x, dy: y})
		graph[b] = append(graph[b], Edge{to: a, dx: -x, dy: -y})
	}

	x := make([]int64, n)
	y := make([]int64, n)
	known := make([]bool, n)

	queue := make([]int, 0, n)
	queue = append(queue, 0)
	known[0] = true

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, e := range graph[v] {
			if known[e.to] {
				continue
			}
			known[e.to] = true
			x[e.to] = x[v] + e.dx
			y[e.to] = y[v] + e.dy
			queue = append(queue, e.to)
		}
	}

	for i := 0; i < n; i++ {
		if known[i] {
			fmt.Fprintf(out, "%d %d\n", x[i], y[i])
		} else {
			fmt.Fprintln(out, "undecidable")
		}
	}
