package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

type ReturnEvent struct {
	time int64
	id   int
}

type ReturnHeap []ReturnEvent

func (h ReturnHeap) Len() int { return len(h) }
func (h ReturnHeap) Less(i, j int) bool {
	if h[i].time == h[j].time {
		return h[i].id < h[j].id
	}
	return h[i].time < h[j].time
}
func (h ReturnHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *ReturnHeap) Push(x any)    { *h = append(*h, x.(ReturnEvent)) }
func (h *ReturnHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	available := make(IntHeap, n)
	for i := 0; i < n; i++ {
		available[i] = i
	}
	heap.Init(&available)

	returning := &ReturnHeap{}
	heap.Init(returning)

	received := make([]int64, n)

	for i := 0; i < m; i++ {
		var t, w, s int64
		fmt.Fscan(in, &t, &w, &s)

		for returning.Len() > 0 && (*returning)[0].time <= t {
			event := heap.Pop(returning).(ReturnEvent)
			heap.Push(&available, event.id)
		}

		if available.Len() > 0 {
			id := heap.Pop(&available).(int)
			received[id] += w
			heap.Push(returning, ReturnEvent{time: t + s, id: id})
		}
	}

	for _, amount := range received {
		fmt.Fprintln(out, amount)
	}
}
