	"os"
)

func countDescendants(n, v, depth int64) int64 {
	if depth < 0 || depth >= 60 {
		return 0
	}

	width := int64(1) << uint(depth)
	if v > n/width {
		return 0
	}

	left := v * width
	remaining := n - left + 1
	if remaining < width {
		return remaining
	}
	return width
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var t int
	fmt.Fscan(in, &t)

	for ; t > 0; t-- {
		var n, x, k int64
		fmt.Fscan(in, &n, &x, &k)

		answer := countDescendants(n, x, k)

		current := x
		for distance := int64(1); distance <= k && current > 1; distance++ {
			child := current
			current /= 2
			remaining := k - distance

			answer += countDescendants(n, current, remaining)
			answer -= countDescendants(n, child, remaining-1)
		}

		fmt.Fprintln(out, answer)
	}
}
