	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, k, p int
	fmt.Fscan(in, &n, &k, &p)

	base := p + 1
	stateCount := 1
	for i := 0; i < k; i++ {
		stateCount *= base
	}

	const inf int64 = 1 << 62
	dp := make([]int64, stateCount)
	for i := 1; i < stateCount; i++ {
		dp[i] = inf
	}

	for i := 0; i < n; i++ {
		var cost int64
		fmt.Fscan(in, &cost)

		gain := make([]int, k)
		for j := 0; j < k; j++ {
			fmt.Fscan(in, &gain[j])
		}

		next := make([]int64, stateCount)
		copy(next, dp)

		for state := 0; state < stateCount; state++ {
			if dp[state] == inf {
				continue
			}

			x := state
			newState := 0
			multiplier := 1

			for j := 0; j < k; j++ {
				value := x % base
				x /= base

				value += gain[j]
				if value > p {
					value = p
				}

				newState += value * multiplier
				multiplier *= base
			}

			if candidate := dp[state] + cost; candidate < next[newState] {
				next[newState] = candidate
			}
		}

		dp = next
	}

	answer := dp[stateCount-1]
	if answer == inf {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
	}
}
