				p++
			}
		}
		prefix[i] = p

		q := m - 1
		for j := len(s) - 1; j >= 0 && q >= 0; j-- {
			if s[j] == t[q] {
				q--
			}
		}
		suffix[i] = m - 1 - q
	}

	sort.Ints(suffix)

	var answer int64
	for _, p := range prefix {
		required := m - p
		pos := sort.SearchInts(suffix, required)
		answer += int64(n - pos)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
