type Edge struct {
	to int
	b  float64
	c  float64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	fmt.Fscan(in, &n, &m)

	graph := make([][]Edge, n)
	high := 0.0

	for i := 0; i < m; i++ {
		var u, v int
		var b, c float64
		fmt.Fscan(in, &u, &v, &b, &c)
		u--
		v--
		graph[u] = append(graph[u], Edge{to: v, b: b, c: c})
		if ratio := b / c; ratio > high {
			high = ratio
		}
	}

	dp := make([]float64, n)
	feasible := func(x float64) bool {
		for i := range dp {
			dp[i] = math.Inf(-1)
		}
		dp[0] = 0

		for u := 0; u < n; u++ {
			if math.IsInf(dp[u], -1) {
				continue
			}
			for _, e := range graph[u] {
				value := dp[u] + e.b - x*e.c
				if value > dp[e.to] {
					dp[e.to] = value
				}
			}
		}
		return dp[n-1] >= 0
	}

	low := 0.0
	for i := 0; i < 100; i++ {
		mid := (low + high) / 2
		if feasible(mid) {
			low = mid
		} else {
			high = mid
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	fmt.Fprintf(out, "%.15f\n", low)
}
