package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

type Product struct {
	start    int64
	deadline int64
}

type MinHeap []int64

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x any) {
	*h = append(*h, x.(int64))
}

func (h *MinHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	products := make([]Product, n)
	for i := 0; i < n; i++ {
		var t, d int64
		fmt.Fscan(in, &t, &d)
		products[i] = Product{
			start:    t,
			deadline: t + d,
		}
	}

	sort.Slice(products, func(i, j int) bool {
		return products[i].start < products[j].start
	})

	h := &MinHeap{}
	heap.Init(h)

	var current int64
	index, answer := 0, 0

	for index < n || h.Len() > 0 {
		if h.Len() == 0 && index < n && current < products[index].start {
			current = products[index].start
		}

		for index < n && products[index].start <= current {
			heap.Push(h, products[index].deadline)
			index++
		}

		for h.Len() > 0 && (*h)[0] < current {
			heap.Pop(h)
		}

		if h.Len() > 0 {
			heap.Pop(h)
			answer++
			current++
		}
	}

	fmt.Fprintln(out, answer)
}
