package main

import (
	"bufio"
	"fmt"
	"os"
)

const inf int64 = 1 << 62

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n
}

func dijkstra(n, start int, d []int64, multiplier, extra int64) []int64 {
	dist := make([]int64, n)
	used := make([]bool, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[start] = 0

	for iter := 0; iter < n; iter++ {
		v := -1
		for i := 0; i < n; i++ {
			if !used[i] && (v == -1 || dist[i] < dist[v]) {
				v = i
			}
		}
		if v == -1 || dist[v] == inf {
			break
		}
		used[v] = true

		base := v * n
		for to := 0; to < n; to++ {
			if used[to] {
				continue
			}
			cost := d[base+to]*multiplier + extra
			if dist[to] > dist[v]+cost {
				dist[to] = dist[v] + cost
			}
		}
	}
	return dist
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	a := in.NextInt64()
	b := in.NextInt64()
	c := in.NextInt64()

	d := make([]int64, n*n)
	for i := range d {
		d[i] = in.NextInt64()
	}

	carDist := dijkstra(n, 0, d, a, 0)
	trainDist := dijkstra(n, n-1, d, b, c)

	answer := inf
	for i := 0; i < n; i++ {
		if carDist[i]+trainDist[i] < answer {
			answer = carDist[i] + trainDist[i]
		}
	}

	fmt.Fprintln(out, answer)
}
