package main

import (
	"bufio"
	"fmt"
	"os"
)

type Sensor struct {
	L int64
	C int64
	K int
}

type Option struct {
	a int
	b int
}

type State struct {
	a int
	b int
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func buildOptions(d int64, aType, bType Sensor) []Option {
	maxA := minInt(aType.K, int((d+aType.L-1)/aType.L))
	options := make([]Option, 0, maxA+1)
	lastB := bType.K + 1

	for a := 0; a <= maxA; a++ {
		remaining := d - int64(a)*aType.L
		b := 0
		if remaining > 0 {
			b = int((remaining + bType.L - 1) / bType.L)
		}

		if b <= bType.K && b < lastB {
			options = append(options, Option{a: a, b: b})
			lastB = b
		}
	}
	return options
}

func estimate(ds []int64, aType, bType Sensor) int64 {
	var result int64
	reachMax := 0

	for _, d := range ds {
		options := buildOptions(d, aType, bType)
		if len(options) == 0 {
			return 1 << 60
		}
		result += int64(reachMax+1) * int64(len(options))
		reachMax = minInt(aType.K, reachMax+options[len(options)-1].a)
	}
	return result
}

func solve(ds []int64, aType, bType Sensor) (int64, bool) {
	states := []State{{a: 0, b: 0}}
	inf := bType.K + 1
	next := make([]int, aType.K+1)

	for _, d := range ds {
		options := buildOptions(d, aType, bType)
		if len(options) == 0 {
			return 0, false
		}

		for i := range next {
			next[i] = inf
		}

		for _, state := range states {
			for _, option := range options {
				na := state.a + option.a
				if na > aType.K {
					break
				}
				nb := state.b + option.b
				if nb <= bType.K && nb < next[na] {
					next[na] = nb
				}
			}
		}

		newStates := make([]State, 0, aType.K+1)
		bestB := inf
		for a, b := range next {
			if b < bestB {
				newStates = append(newStates, State{a: a, b: b})
				bestB = b
			}
		}

		if len(newStates) == 0 {
			return 0, false
		}
		states = newStates
	}

	var answer int64 = 1<<63 - 1
	for _, state := range states {
		cost := int64(state.a)*aType.C + int64(state.b)*bType.C
		if cost < answer {
			answer = cost
		}
	}
	return answer, true
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	ds := make([]int64, n)
	for i := range ds {
		fmt.Fscan(in, &ds[i])
	}

	var sensors [2]Sensor
	for i := 0; i < 2; i++ {
		fmt.Fscan(in, &sensors[i].L, &sensors[i].C, &sensors[i].K)
	}

	aType, bType := sensors[0], sensors[1]
	if estimate(ds, sensors[1], sensors[0]) < estimate(ds, sensors[0], sensors[1]) {
		aType, bType = sensors[1], sensors[0]
	}

	answer, possible := solve(ds, aType, bType)
	if !possible {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
	}
}
