package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var r, c string
	fmt.Fscan(in, &n, &r, &c)

	permutations := [][]byte{
		{'A', 'B', 'C'},
		{'A', 'C', 'B'},
		{'B', 'A', 'C'},
		{'B', 'C', 'A'},
		{'C', 'A', 'B'},
		{'C', 'B', 'A'},
	}

	candidates := make([][][]byte, n)
	for row := 0; row < n; row++ {
		for mask := 0; mask < (1 << n); mask++ {
			if bits.OnesCount(uint(mask)) != 3 {
				continue
			}

			positions := make([]int, 0, 3)
			for col := 0; col < n; col++ {
				if mask&(1<<col) != 0 {
					positions = append(positions, col)
				}
			}

			for _, perm := range permutations {
				if perm[0] != r[row] {
					continue
				}
				line := make([]byte, n)
				for i := range line {
					line[i] = '.'
				}
				for i, col := range positions {
					line[col] = perm[i]
				}
				candidates[row] = append(candidates[row], line)
			}
		}
	}

	columnMasks := make([]int, n)
	answer := make([][]byte, n)

	var dfs func(int) bool
	dfs = func(row int) bool {
		if row == n {
			for col := 0; col < n; col++ {
				if columnMasks[col] != 7 {
					return false
				}
			}
			return true
		}

		for _, line := range candidates[row] {
			valid := true

			for col, ch := range line {
				if ch == '.' {
					continue
				}
				bit := 1 << (ch - 'A')
				if columnMasks[col]&bit != 0 {
					valid = false
					break
				}
				if columnMasks[col] == 0 && ch != c[col] {
					valid = false
					break
				}
			}
			if !valid {
				continue
			}

			for col, ch := range line {
				if ch != '.' {
					columnMasks[col] |= 1 << (ch - 'A')
				}
			}
			answer[row] = line

			remainingRows := n - row - 1
			for col := 0; col < n; col++ {
				missing := 3 - bits.OnesCount(uint(columnMasks[col]))
				if missing > remainingRows {
					valid = false
					break
				}
			}

			if valid && dfs(row+1) {
				return true
			}

			for col, ch := range line {
				if ch != '.' {
					columnMasks[col] &^= 1 << (ch - 'A')
				}
			}
		}
		return false
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if !dfs(0) {
		fmt.Fprintln(out, "No")
		return
	}

	fmt.Fprintln(out, "Yes")
	for _, line := range answer {
		fmt.Fprintln(out, string(line))
	}
}
