)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	invN := modPow(int64(n), mod-2)
	var suffix int64

	for i := n - 1; i >= 0; i-- {
		expectedFromI := suffix * invN % mod
		suffix = (suffix + a[i] + expectedFromI) % mod
	}

	answer := suffix * invN % mod
	fmt.Fprintln(out, answer)
}
