		graph[b] = append(graph[b], a[i])
	}

	color := make([]int, n)
	for i := range color {
		color[i] = -1
	}

	queue := make([]int, 0, n)
	for start := 0; start < n; start++ {
		if color[start] != -1 {
			continue
		}

		color[start] = 0
		queue = queue[:0]
		queue = append(queue, start)

		for head := 0; head < len(queue); head++ {
			v := queue[head]
			for _, next := range graph[v] {
				if color[next] == -1 {
					color[next] = color[v] ^ 1
					queue = append(queue, next)
				} else if color[next] == color[v] {
					fmt.Println("No")
					return
				}
			}
		}
	}

	fmt.Println("Yes")
}
