package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	u, v int
	w    int64
}

type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := 0; i < n; i++ {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) find(x int) int {
	for d.parent[x] != x {
		x = d.parent[x]
	}
	return x
}

func (d *DSU) unite(a, b int) (int, int, bool) {
	a = d.find(a)
	b = d.find(b)
	if a == b {
		return 0, 0, false
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	oldSize := d.size[a]
	d.parent[b] = a
	d.size[a] += d.size[b]
	return b, oldSize, true
}

func (d *DSU) rollback(child, oldSize int) {
	root := d.parent[child]
	d.size[root] = oldSize
	d.parent[child] = child
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	var k int64
	fmt.Fscan(in, &n, &m, &k)

	edges := make([]Edge, m)
	for i := range edges {
		fmt.Fscan(in, &edges[i].u, &edges[i].v, &edges[i].w)
		edges[i].u--
		edges[i].v--
	}

	dsu := NewDSU(n)
	answer := k

	var dfs func(index, selected int, sum int64)
	dfs = func(index, selected int, sum int64) {
		if answer == 0 {
			return
		}
		if selected == n-1 {
			if sum < answer {
				answer = sum
			}
			return
		}
		if index == m || selected+(m-index) < n-1 {
			return
		}

		e := edges[index]
		child, oldSize, merged := dsu.unite(e.u, e.v)
		if merged {
			dfs(index+1, selected+1, (sum+e.w)%k)
			dsu.rollback(child, oldSize)
		}

		dfs(index+1, selected, sum)
	}

	dfs(0, 0, 0)
	fmt.Fprintln(out, answer)
}
