import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type MinHeap []int

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x any) {
	*h = append(*h, x.(int))
}

func (h *MinHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, q int
	fmt.Fscan(in, &n, &q)

	a := make([]int, n)
	count := make([]int, n+1)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		if a[i] <= n {
			count[a[i]]++
		}
	}

	missing := &MinHeap{}
	for x := 0; x <= n; x++ {
		if count[x] == 0 {
			*missing = append(*missing, x)
		}
	}
	heap.Init(missing)

	for ; q > 0; q-- {
		var index, x int
		fmt.Fscan(in, &index, &x)
		index--

		old := a[index]
		if old <= n {
			count[old]--
			if count[old] == 0 {
				heap.Push(missing, old)
			}
		}

		a[index] = x
		if x <= n {
			count[x]++
		}

		for count[(*missing)[0]] > 0 {
			heap.Pop(missing)
		}
		fmt.Fprintln(out, (*missing)[0])
	}
}
