package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := io.ReadAll(os.Stdin)
	return &FastScanner{data: data}
}

func (fs *FastScanner) next() []byte {
	for fs.pos < len(fs.data) && fs.data[fs.pos] <= ' ' {
		fs.pos++
	}
	start := fs.pos
	for fs.pos < len(fs.data) && fs.data[fs.pos] > ' ' {
		fs.pos++
	}
	return fs.data[start:fs.pos]
}

func (fs *FastScanner) nextInt64() int64 {
	token := fs.next()
	var value int64
	for _, c := range token {
		value = value*10 + int64(c-'0')
	}
	return value
}

func main() {
	in := NewFastScanner()
	n := int(in.nextInt64())
	q := int(in.nextInt64())

	size := n + 1
	prefix := make([]int64, size*size)

	for i := 1; i <= n; i++ {
		row := in.next()
		var rowSum int64
		for j := 1; j <= n; j++ {
			if row[j-1] == 'B' {
				rowSum++
			}
			prefix[i*size+j] = prefix[(i-1)*size+j] + rowSum
		}
	}

	total := prefix[n*size+n]
	countPrefix := func(x, y int64) int64 {
		if x <= 0 || y <= 0 {
			return 0
		}

		n64 := int64(n)
		fullRows, remRows := x/n64, int(x%n64)
		fullCols, remCols := y/n64, int(y%n64)

		return fullRows*fullCols*total +
			fullRows*prefix[n*size+remCols] +
			fullCols*prefix[remRows*size+n] +
			prefix[remRows*size+remCols]
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for ; q > 0; q-- {
		a := in.nextInt64()
		b := in.nextInt64()
		c := in.nextInt64()
		d := in.nextInt64()

		answer := countPrefix(c+1, d+1) -
			countPrefix(a, d+1) -
			countPrefix(c+1, b) +
			countPrefix(a, b)

		fmt.Fprintln(out, answer)
	}
}
