func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, l int
	fmt.Fscan(in, &n, &m, &l)

	mainPrices := make([]int64, n)
	for i := range mainPrices {
		fmt.Fscan(in, &mainPrices[i])
	}

	sides := make([]SideDish, m)
	for i := range sides {
		fmt.Fscan(in, &sides[i].price)
		sides[i].index = i
	}

	forbidden := make([]map[int]struct{}, n)
	for i := 0; i < l; i++ {
		var c, d int
		fmt.Fscan(in, &c, &d)
		c--
		d--
		if forbidden[c] == nil {
			forbidden[c] = make(map[int]struct{})
		}
		forbidden[c][d] = struct{}{}
	}

	sort.Slice(sides, func(i, j int) bool {
		return sides[i].price > sides[j].price
	})

	var answer int64
	for i, mainPrice := range mainPrices {
		for _, side := range sides {
			if _, blocked := forbidden[i][side.index]; !blocked {
				price := mainPrice + side.price
				if price > answer {
					answer = price
				}
				break
			}
		}
