package main

import (
	"bufio"
	"fmt"
	"os"
)

type Permutation struct {
	p   []int
	inv int
}

func generatePermutations(n int) []Permutation {
	var result []Permutation
	p := make([]int, n)
	used := make([]bool, n)

	var dfs func(int)
	dfs = func(pos int) {
		if pos == n {
			cp := append([]int(nil), p...)
			inv := 0
			for i := 0; i < n; i++ {
				for j := i + 1; j < n; j++ {
					if p[i] > p[j] {
						inv++
					}
				}
			}
			result = append(result, Permutation{p: cp, inv: inv})
			return
		}

		for x := 0; x < n; x++ {
			if !used[x] {
				used[x] = true
				p[pos] = x
				dfs(pos + 1)
				used[x] = false
			}
		}
	}

	dfs(0)
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var h, w int
	fmt.Fscan(in, &h, &w)

	a := make([][]int64, h)
	b := make([][]int64, h)

	for i := 0; i < h; i++ {
		a[i] = make([]int64, w)
		for j := 0; j < w; j++ {
			fmt.Fscan(in, &a[i][j])
		}
	}

	for i := 0; i < h; i++ {
		b[i] = make([]int64, w)
		for j := 0; j < w; j++ {
			fmt.Fscan(in, &b[i][j])
		}
	}

	rowPerms := generatePermutations(h)
	colPerms := generatePermutations(w)

	answer := int(^uint(0) >> 1)

	for _, rp := range rowPerms {
		for _, cp := range colPerms {
			cost := rp.inv + cp.inv
			if cost >= answer {
				continue
			}

			matches := true
			for i := 0; i < h && matches; i++ {
				for j := 0; j < w; j++ {
					if a[rp.p[i]][cp.p[j]] != b[i][j] {
						matches = false
						break
					}
				}
			}

			if matches {
				answer = cost
			}
		}
	}

	if answer == int(^uint(0)>>1) {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
	}
}
