package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var h, w int
	fmt.Fscan(in, &h, &w)

	grid := make([][]byte, h)
	redCount := 0
	for i := 0; i < h; i++ {
		var s string
		fmt.Fscan(in, &s)
		grid[i] = []byte(s)
		for j := 0; j < w; j++ {
			if grid[i][j] == '.' {
				redCount++
			}
		}
	}

	n := h * w
	label := make([]int, n)
	queue := make([]int, 0, n)
	components := 0
	dx := [4]int{-1, 1, 0, 0}
	dy := [4]int{0, 0, -1, 1}

	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			start := i*w + j
			if grid[i][j] != '#' || label[start] != 0 {
				continue
			}

			components++
			label[start] = components
			queue = queue[:0]
			queue = append(queue, start)

			for head := 0; head < len(queue); head++ {
				v := queue[head]
				x, y := v/w, v%w

				for d := 0; d < 4; d++ {
					nx, ny := x+dx[d], y+dy[d]
					if nx < 0 || nx >= h || ny < 0 || ny >= w {
						continue
					}
					to := nx*w + ny
					if grid[nx][ny] == '#' && label[to] == 0 {
						label[to] = components
						queue = append(queue, to)
					}
				}
			}
		}
	}

	var sum int64
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if grid[i][j] != '.' {
				continue
			}

			var adjacent [4]int
			distinct := 0

			for d := 0; d < 4; d++ {
				ni, nj := i+dx[d], j+dy[d]
				if ni < 0 || ni >= h || nj < 0 || nj >= w {
					continue
				}

				id := label[ni*w+nj]
				if id == 0 {
					continue
				}

				seen := false
				for k := 0; k < distinct; k++ {
					if adjacent[k] == id {
						seen = true
						break
					}
				}
				if !seen {
					adjacent[distinct] = id
					distinct++
				}
			}

			sum += int64(components + 1 - distinct)
		}
	}

	answer := (sum % mod) * modPow(int64(redCount), mod-2) % mod
	fmt.Fprintln(out, answer)
}
