		diff[l] += change
		diff[r] -= change
	}

	answer := int64(1<<62)
	var change int64
	for edge := 1; edge <= n; edge++ {
		change += diff[edge]
		cost := base + change
		if cost < answer {
			answer = cost
		}
	}

