	for i := 0; i < n; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		chordAt[a] = i
		chordAt[b] = i
	}

	seen := make([]bool, n)
	stack := make([]int, 0, n)

	for p := 1; p <= 2*n; p++ {
		id := chordAt[p]
		if !seen[id] {
			seen[id] = true
			stack = append(stack, id)
		} else {
			if len(stack) == 0 || stack[len(stack)-1] != id {
				fmt.Fprintln(out, "Yes")
				return
			}
			stack = stack[:len(stack)-1]
		}
	}

	fmt.Fprintln(out, "No")
}
