	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	grid := make([]string, n)
	players := make([]int, 0, 2)

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &grid[i])
		for j := 0; j < n; j++ {
			if grid[i][j] == 'P' {
				players = append(players, i*n+j)
			}
		}
	}

	m := n * n
	moves := make([][4]int, m)
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			pos := r*n + c
			for d := 0; d < 4; d++ {
				nr, nc := r+dr[d], c+dc[d]
				if nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != '#' {
					moves[pos][d] = nr*n + nc
				} else {
					moves[pos][d] = pos
				}
			}
		}
	}

	a, b := players[0], players[1]
	if a > b {
		a, b = b, a
	}

	totalStates := m * m
	visited := make([]uint64, (totalStates+63)/64)

	startCode := a*m + b
	visited[startCode>>6] |= uint64(1) << uint(startCode&63)

	maxPairs := m * (m + 1) / 2
	queue := make([]int32, 1, maxPairs)
	queue[0] = int32(startCode)

	head := 0
	distance := 0

	for head < len(queue) {
		levelEnd := len(queue)

		for head < levelEnd {
			code := int(queue[head])
			head++

			p1 := code / m
			p2 := code % m

			for d := 0; d < 4; d++ {
				next1 := moves[p1][d]
				next2 := moves[p2][d]

				if next1 == next2 {
					fmt.Fprintln(out, distance+1)
					return
				}

				if next1 > next2 {
					next1, next2 = next2, next1
				}

				nextCode := next1*m + next2
				word := nextCode >> 6
				mask := uint64(1) << uint(nextCode&63)

				if visited[word]&mask == 0 {
					visited[word] |= mask
					queue = append(queue, int32(nextCode))
				}
			}
		}

		distance++
	}

	fmt.Fprintln(out, -1)
}
