package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Edge struct {
	to   int
	cost int64
}

type Item struct {
	node int
	dist int64
}

type PriorityQueue []Item

func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].dist < pq[j].dist
}
func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(Item))
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	graph := make([][]Edge, n)
	for i := 0; i < n-1; i++ {
		var a, b int64
		var x int
		fmt.Fscan(in, &a, &b, &x)
		graph[i] = append(graph[i], Edge{to: i + 1, cost: a})
		graph[i] = append(graph[i], Edge{to: x - 1, cost: b})
	}

	const inf int64 = 1 << 62
	dist := make([]int64, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[0] = 0

	pq := &PriorityQueue{{node: 0, dist: 0}}
	heap.Init(pq)

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(Item)
		if cur.dist != dist[cur.node] {
			continue
		}
		if cur.node == n-1 {
			break
		}

		for _, edge := range graph[cur.node] {
			nextDist := cur.dist + edge.cost
			if nextDist < dist[edge.to] {
				dist[edge.to] = nextDist
				heap.Push(pq, Item{node: edge.to, dist: nextDist})
			}
		}
	}

	fmt.Fprintln(out, dist[n-1])
}
