func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var h, w, n int
	var t string
	fmt.Fscan(in, &h, &w, &n)
	fmt.Fscan(in, &t)

	words := (w + 63) / 64
	land := make([]uint64, h*words)

	for r := 0; r < h; r++ {
		var s string
		fmt.Fscan(in, &s)
		for c := 0; c < w; c++ {
			if s[c] == '.' {
				land[r*words+c/64] |= uint64(1) << uint(c%64)
			}
		}
	}

	current := make([]uint64, len(land))
	copy(current, land)
	next := make([]uint64, len(land))

	for _, move := range t {
		clear(next)

		switch move {
		case 'L':
			for r := 0; r < h; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					v := current[base+k] >> 1
					if k+1 < words {
						v |= current[base+k+1] << 63
					}
					next[base+k] = v & land[base+k]
				}
			}

		case 'R':
			for r := 0; r < h; r++ {
				base := r * words
				for k := 0; k < words; k++ {
					v := current[base+k] << 1
					if k > 0 {
						v |= current[base+k-1] >> 63
					}
					next[base+k] = v & land[base+k]
				}
			}

		case 'U':
			for r := 0; r+1 < h; r++ {
				dst := r * words
				src := (r + 1) * words
				for k := 0; k < words; k++ {
					next[dst+k] = current[src+k] & land[dst+k]
				}
			}

		case 'D':
			for r := 1; r < h; r++ {
				dst := r * words
				src := (r - 1) * words
				for k := 0; k < words; k++ {
					next[dst+k] = current[src+k] & land[dst+k]
				}
			}
		}

		current, next = next, current
	}

	answer := 0
	for _, v := range current {
		answer += bits.OnesCount64(v)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
