package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, val := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		val = val*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * val
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	adj := make([][]int, n)
	for i := 0; i < m; i++ {
		u := in.NextInt() - 1
		v := in.NextInt() - 1
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	weights := make([]int, n)
	for i := range weights {
		weights[i] = in.NextInt()
	}

	pieces := make([]int64, n)
	for i := range pieces {
		pieces[i] = int64(in.NextInt())
	}

	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		return weights[order[i]] < weights[order[j]]
	})

	value := make([]int64, n)

	for _, v := range order {
		capacity := weights[v] - 1
		dp := make([]int64, capacity+1)

		for _, u := range adj[v] {
			if weights[u] >= weights[v] {
				continue
			}

			itemWeight := weights[u]
			itemValue := value[u]
			for c := capacity; c >= itemWeight; c-- {
				candidate := dp[c-itemWeight] + itemValue
				if candidate > dp[c] {
					dp[c] = candidate
				}
			}
		}

		value[v] = dp[capacity] + 1
	}

	var answer int64
	for i := 0; i < n; i++ {
		answer += pieces[i] * value[i]
	}

	fmt.Fprintln(out, answer)
}
