}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Edge struct {
	l, d, k, c int64
	from       int
}

type Item struct {
	time int64
	node int
}

type MaxHeap []Item

func (h MaxHeap) Len() int {
	return len(h)
}

func (h MaxHeap) Less(i, j int) bool {
	return h[i].time > h[j].time
}

func (h MaxHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(Item))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	m := int(in.NextInt64())

	incoming := make([][]Edge, n)
	for i := 0; i < m; i++ {
		l := in.NextInt64()
		d := in.NextInt64()
		k := in.NextInt64()
		c := in.NextInt64()
		a := int(in.NextInt64()) - 1
		b := int(in.NextInt64()) - 1

		incoming[b] = append(incoming[b], Edge{
			l:    l,
			d:    d,
			k:    k,
			c:    c,
			from: a,
		})
	}

	const inf int64 = 1 << 62
	latest := make([]int64, n)
	for i := range latest {
		latest[i] = -1
	}
	latest[n-1] = inf

	pq := &MaxHeap{{time: inf, node: n - 1}}
	heap.Init(pq)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(Item)
		if item.time != latest[item.node] {
			continue
		}

		for _, e := range incoming[item.node] {
			limit := item.time - e.c
			if limit < e.l {
				continue
			}

			index := (limit - e.l) / e.d
			if index >= e.k {
				index = e.k - 1
			}
			departure := e.l + index*e.d

			if departure > latest[e.from] {
				latest[e.from] = departure
				heap.Push(pq, Item{time: departure, node: e.from})
			}
		}
	}

	for i := 0; i < n-1; i++ {
		if latest[i] == -1 {
			fmt.Fprintln(out, "Unreachable")
		} else {
			fmt.Fprintln(out, latest[i])
		}
	}
}
