	costs := make([]int64, n)
	for i := range costs {
		fmt.Fscan(in, &costs[i])
	}

	prefix0 := make([]int64, n+1)
	prefix1 := make([]int64, n+1)

	for i := 0; i < n; i++ {
		prefix0[i+1] = prefix0[i]
		prefix1[i+1] = prefix1[i]

		expected0 := byte('0' + byte(i%2))
		expected1 := byte('0' + byte((i+1)%2))

		if s[i] != expected0 {
			prefix0[i+1] += costs[i]
		}
		if s[i] != expected1 {
			prefix1[i+1] += costs[i]
		}
	}

	total0 := prefix0[n]
	total1 := prefix1[n]
	answer := int64(^uint64(0) >> 1)

	for k := 1; k < n; k++ {
		cost := prefix0[k] + (total1 - prefix1[k])
		if cost < answer {
			answer = cost
		}

		cost = prefix1[k] + (total0 - prefix0[k])
		if cost < answer {
			answer = cost
		}
	}

	fmt.Fprintln(out, answer)
