func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var h, w, m int
	fmt.Fscan(in, &h, &w, &m)

	ops := make([]Operation, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &ops[i].t, &ops[i].a, &ops[i].x)
	}

	usedRows := make([]bool, h+1)
	usedCols := make([]bool, w+1)
	rowCount, colCount := 0, 0
	counts := make(map[int]int64)

	for i := m - 1; i >= 0; i-- {
		op := ops[i]
		if op.t == 1 {
			if usedRows[op.a] {
				continue
			}
			usedRows[op.a] = true
			counts[op.x] += int64(w - colCount)
			rowCount++
		} else {
			if usedCols[op.a] {
				continue
			}
			usedCols[op.a] = true
			counts[op.x] += int64(h - rowCount)
			colCount++
		}
	}

	counts[0] += int64(h-rowCount) * int64(w-colCount)

	colors := make([]int, 0, len(counts))
	for color, count := range counts {
		if count > 0 {
			colors = append(colors, color)
		}
	}
	sort.Ints(colors)

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	fmt.Fprintln(out, len(colors))
	for _, color := range colors {
		fmt.Fprintln(out, color, counts[color])
	}
}
