package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := int(in.NextInt64())
	graph := make([][]int, n)

	for i := 0; i < n-1; i++ {
		a := int(in.NextInt64()) - 1
		b := int(in.NextInt64()) - 1
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	weights := make([]int64, n)
	var totalWeight int64
	for i := 0; i < n; i++ {
		weights[i] = in.NextInt64()
		totalWeight += weights[i]
	}

	parent := make([]int, n)
	depth := make([]int64, n)
	order := make([]int, 0, n)
	for i := range parent {
		parent[i] = -2
	}

	parent[0] = -1
	stack := []int{0}

	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)

		for _, to := range graph[v] {
			if to == parent[v] {
				continue
			}
			parent[to] = v
			depth[to] = depth[v] + 1
			stack = append(stack, to)
		}
	}

	subtreeWeight := make([]int64, n)
	var rootCost int64
	for i := 0; i < n; i++ {
		subtreeWeight[i] = weights[i]
		rootCost += weights[i] * depth[i]
	}

	for i := n - 1; i > 0; i-- {
		v := order[i]
		subtreeWeight[parent[v]] += subtreeWeight[v]
	}

	cost := make([]int64, n)
	cost[0] = rootCost
	answer := rootCost

	for _, v := range order[1:] {
		p := parent[v]
		cost[v] = cost[p] + totalWeight - 2*subtreeWeight[v]
		if cost[v] < answer {
			answer = cost[v]
		}
	}

	fmt.Fprintln(out, answer)
}
