package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

var (
	values [9]int64
	memo   [1 << 18]int8
	lines  = [8]int{
		0b000000111,
		0b000111000,
		0b111000000,
		0b001001001,
		0b010010010,
		0b100100100,
		0b100010001,
		0b001010100,
	}
)

func hasLine(mask int) bool {
	for _, line := range lines {
		if mask&line == line {
			return true
		}
	}
	return false
}

func takahashiWins(red, blue int) bool {
	key := (red << 9) | blue
	if memo[key] != 0 {
		return memo[key] == 1
	}

	if hasLine(red) {
		memo[key] = 1
		return true
	}
	if hasLine(blue) {
		memo[key] = -1
		return false
	}

	used := red | blue
	if used == (1<<9)-1 {
		var redScore, blueScore int64
		for i := 0; i < 9; i++ {
			if red&(1<<i) != 0 {
				redScore += values[i]
			} else {
				blueScore += values[i]
			}
		}
		if redScore > blueScore {
			memo[key] = 1
			return true
		}
		memo[key] = -1
		return false
	}

	takahashiTurn := bits.OnesCount(uint(used))%2 == 0

	if takahashiTurn {
		for i := 0; i < 9; i++ {
			bit := 1 << i
			if used&bit == 0 && takahashiWins(red|bit, blue) {
				memo[key] = 1
				return true
			}
		}
		memo[key] = -1
		return false
	}

	for i := 0; i < 9; i++ {
		bit := 1 << i
		if used&bit == 0 && !takahashiWins(red, blue|bit) {
			memo[key] = -1
			return false
		}
	}
	memo[key] = 1
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	for i := 0; i < 9; i++ {
		fmt.Fscan(in, &values[i])
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if takahashiWins(0, 0) {
		fmt.Fprintln(out, "Takahashi")
	} else {
		fmt.Fprintln(out, "Aoki")
	}
}
