	"os"
	"sort"
)

type Fenwick struct {
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int64, n+1)}
}

func (f *Fenwick) Add(index int, value int64) {
	for index < len(f.tree) {
		f.tree[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int64 {
	var result int64
	for index > 0 {
		result += f.tree[index]
		index -= index & -index
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	a := make([]int, n)
	values := make([]int, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
		values[i] = a[i]
	}

	sort.Ints(values)
	unique := values[:0]
	for _, v := range values {
		if len(unique) == 0 || unique[len(unique)-1] != v {
			unique = append(unique, v)
		}
	}

	countTree := NewFenwick(len(unique))
	sumTree := NewFenwick(len(unique))

	var answer int64
	for _, value := range a {
		rank := sort.SearchInts(unique, value) + 1

		countLess := countTree.Sum(rank - 1)
		sumLess := sumTree.Sum(rank - 1)
		answer += int64(value)*countLess - sumLess

		countTree.Add(rank, 1)
		sumTree.Add(rank, int64(value))
	}

	fmt.Fprintln(out, answer)
}
