	pos := make([]int, n+1)
	for i := 1; i <= n; i++ {
		var value int
		fmt.Fscan(in, &value)
		pos[value] = i
	}

	minDeque := make([]int, n)
	maxDeque := make([]int, n)
	minHead, minTail := 0, 0
	maxHead, maxTail := 0, 0
	answer := n

	for value := 1; value <= n; value++ {
		for minHead < minTail && pos[minDeque[minTail-1]] >= pos[value] {
			minTail--
		}
		minDeque[minTail] = value
		minTail++

		for maxHead < maxTail && pos[maxDeque[maxTail-1]] <= pos[value] {
			maxTail--
