		maxDeque[maxTail] = value
		maxTail++

		left := value - k + 1
		if left < 1 {
			continue
		}

		for minHead < minTail && minDeque[minHead] < left {
			minHead++
		}
		for maxHead < maxTail && maxDeque[maxHead] < left {
