package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Operation struct {
	cost     int64
	vertices []int
}

type DSU struct {
	parent []int
	size   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	return &DSU{parent: parent, size: size}
}

func (d *DSU) Find(x int) int {
	for d.parent[x] != x {
		d.parent[x] = d.parent[d.parent[x]]
		x = d.parent[x]
	}
	return x
}

func (d *DSU) Union(a, b int) bool {
	a = d.Find(a)
	b = d.Find(b)
	if a == b {
		return false
	}
	if d.size[a] < d.size[b] {
		a, b = b, a
	}
	d.parent[b] = a
	d.size[a] += d.size[b]
	return true
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	operations := make([]Operation, m)
	for i := 0; i < m; i++ {
		var k int
		var c int64
		fmt.Fscan(in, &k, &c)

		vertices := make([]int, k)
		for j := 0; j < k; j++ {
			fmt.Fscan(in, &vertices[j])
			vertices[j]--
		}
		operations[i] = Operation{cost: c, vertices: vertices}
	}

	sort.Slice(operations, func(i, j int) bool {
		return operations[i].cost < operations[j].cost
	})

	dsu := NewDSU(n)
	var answer int64
	edgesUsed := 0

	for _, op := range operations {
		base := op.vertices[0]
		for i := 1; i < len(op.vertices); i++ {
			if dsu.Union(base, op.vertices[i]) {
				answer += op.cost
				edgesUsed++
			}
		}
	}

	if edgesUsed != n-1 {
		fmt.Fprintln(out, -1)
	} else {
		fmt.Fprintln(out, answer)
	}
}
