	length := n + 1
	var answer uint64

	for bit := uint(0); bit < 60; bit++ {
		if (m>>bit)&1 == 0 {
			continue
		}

		half := uint64(1) << bit
		cycle := half << 1

		ones := (length / cycle) * half
		remainder := length % cycle
		if remainder > half {
			ones += remainder - half
		}

		answer = (answer + ones%mod) % mod
	}

	fmt.Fprintln(out, answer)
