import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	freq := make([]int, 1_000_001)
	maxValue := 0

	for i := 0; i < n; i++ {
		a := in.NextInt()
		freq[a]++
		if a > maxValue {
			maxValue = a
		}
	}

	prefix := make([]int, maxValue+1)
	for value := 1; value <= maxValue; value++ {
		prefix[value] = prefix[value-1] + freq[value]
	}

	var answer int64

	for x := 1; x <= maxValue; x++ {
		if freq[x] == 0 {
			continue
		}

		f := int64(freq[x])
		answer += f * (f - 1) / 2

		for quotient := 1; quotient*x <= maxValue; quotient++ {
			left := quotient * x
			right := (quotient+1)*x - 1

			if quotient == 1 {
				left = x + 1
			}
			if right > maxValue {
				right = maxValue
			}
			if left > right {
				continue
			}

			count := prefix[right] - prefix[left-1]
			answer += f * int64(quotient) * int64(count)
		}
	}

	fmt.Fprintln(out, answer)
}
