import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	next := make([]int, n)
	indegree := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &next[i])
		next[i]--
		indegree[next[i]]++
	}

	queue := make([]int, 0, n)
	for i := 0; i < n; i++ {
		if indegree[i] == 0 {
			queue = append(queue, i)
		}
	}

	order := make([]int, 0, n)
	for head := 0; head < len(queue); head++ {
		v := queue[head]
		order = append(order, v)

		to := next[v]
		indegree[to]--
		if indegree[to] == 0 {
			queue = append(queue, to)
		}
	}

	reachable := make([]int64, n)
	visited := make([]bool, n)

	for i := 0; i < n; i++ {
		if indegree[i] > 0 && !visited[i] {
			cycle := make([]int, 0)
			v := i
			for !visited[v] {
				visited[v] = true
				cycle = append(cycle, v)
				v = next[v]
			}

			length := int64(len(cycle))
			for _, node := range cycle {
				reachable[node] = length
			}
		}
	}

	for i := len(order) - 1; i >= 0; i-- {
		v := order[i]
		reachable[v] = reachable[next[v]] + 1
	}

	var answer int64
	for _, count := range reachable {
		answer += count
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
