package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(base, exp int64) int64 {
	base %= mod
	if base < 0 {
		base += mod
	}
	var result int64 = 1
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	fmt.Fscan(in, &n, &k)

	invN := modPow(n, mod-2)
	inv2 := (mod + 1) / 2

	ratio := (n - 2) % mod
	if ratio < 0 {
		ratio += mod
	}
	ratio = ratio * invN % mod

	answer := (n + 1) % mod * inv2 % mod
	subtract := (n - 1) % mod * inv2 % mod * modPow(ratio, k) % mod
	answer = (answer - subtract + mod) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
