package main

import (
	"bufio"
	"fmt"
	"os"
)

func mobius(n int) int {
	x := n
	primeFactors := 0
	for p := 2; p*p <= x; p++ {
		if x%p != 0 {
			continue
		}
		exponent := 0
		for x%p == 0 {
			x /= p
			exponent++
		}
		if exponent >= 2 {
			return 0
		}
		primeFactors++
	}
	if x > 1 {
		primeFactors++
	}
	if primeFactors%2 == 0 {
		return 1
	}
	return -1
}

func powerLE(base uint64, exponent int, limit uint64) bool {
	result := uint64(1)
	for i := 0; i < exponent; i++ {
		if result > limit/base {
			return false
		}
		result *= base
	}
	return true
}

func integerRoot(n uint64, exponent int) uint64 {
	lo, hi := uint64(1), uint64(1_000_000_001)
	for hi-lo > 1 {
		mid := lo + (hi-lo)/2
		if powerLE(mid, exponent, n) {
			lo = mid
		} else {
			hi = mid
		}
	}
	return lo
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n uint64
	fmt.Fscan(in, &n)

	answer := int64(1) // 1 = 1^b for every b >= 2
	for exponent := 2; exponent <= 60; exponent++ {
		mu := mobius(exponent)
		if mu == 0 {
			continue
		}
		root := integerRoot(n, exponent)
		answer += int64(-mu) * int64(root-1)
	}

	fmt.Fprintln(out, answer)
}
