	fmt.Fscan(in, &n, &x, &y)

	const inf = int(1e9)
	dp := make([][]int, n+1)
	for k := 0; k <= n; k++ {
		dp[k] = make([]int, x+1)
		for s := 0; s <= x; s++ {
			dp[k][s] = inf
		}
