					continue
				}
				if dp[k][s]+b < dp[k+1][s+a] {
					dp[k+1][s+a] = dp[k][s] + b
				}
			}
		}
	}

	maxSafe := 0
	for k := 0; k <= n; k++ {
		for s := 0; s <= x; s++ {
			if dp[k][s] <= y {
				maxSafe = k
				break
			}
		}
	}

	answer := maxSafe + 1
	if answer > n {
		answer = n
	}
