	var n int
	var s string
	fmt.Fscan(in, &n, &s)

	const neg = -1 << 30
	dp := [3]int{neg, neg, neg}

	moveIndex := func(c byte) int {
		switch c {
		case 'R':
			return 0
		case 'P':
			return 1
		default:
			return 2
		}
	}

	for i := 0; i < n; i++ {
		aoki := moveIndex(s[i])
		win := (aoki + 1) % 3
		next := [3]int{neg, neg, neg}

		for move := 0; move < 3; move++ {
			if move != aoki && move != win {
				continue
			}

			score := 0
			if move == win {
				score = 1
			}

			if i == 0 {
				next[move] = score
				continue
			}

			for prev := 0; prev < 3; prev++ {
				if prev != move && dp[prev] != neg {
					value := dp[prev] + score
					if value > next[move] {
						next[move] = value
					}
				}
			}
		}
		dp = next
	}

	answer := dp[0]
	for i := 1; i < 3; i++ {
		if dp[i] > answer {
			answer = dp[i]
		}
	}

	out := bufio.NewWriter(os.Stdout)
