	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	const bits = 30
	var ones [bits]int64
	prefix := 0
	var singleSum int64

	for i := 0; i < n; i++ {
		var a int
		fmt.Fscan(in, &a)
		singleSum += int64(a)
		prefix ^= a

		for bit := 0; bit < bits; bit++ {
			if prefix&(1<<bit) != 0 {
				ones[bit]++
			}
		}
	}

	totalPrefixes := int64(n + 1)
	var answer int64
	for bit := 0; bit < bits; bit++ {
		zeros := totalPrefixes - ones[bit]
		answer += ones[bit] * zeros * (int64(1) << bit)
	}

	// Remove subarrays of length one.
	answer -= singleSum
	fmt.Fprintln(out, answer)
}
