		if len(s[i]) > maxLen {
			maxLen = len(s[i])
		}
	}

	for j := 0; j < maxLen; j++ {
		t := make([]byte, 0, n)
		for i := n - 1; i >= 0; i-- {
			if j < len(s[i]) {
				t = append(t, s[i][j])
			} else {
				t = append(t, '*')
			}
		}
