type Function struct {
	a, b int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, k int
	fmt.Fscan(in, &n, &k)

	functions := make([]Function, n)
	for i := range functions {
		fmt.Fscan(in, &functions[i].a, &functions[i].b)
	}

	// Sort in the order in which the functions are applied,
	// from the innermost function to the outermost function.
	sort.Slice(functions, func(i, j int) bool {
		left := functions[i].b * (functions[j].a - 1)
		right := functions[j].b * (functions[i].a - 1)
		return left > right
	})

	dp := make([]int64, k+1)
	for i := 1; i <= k; i++ {
		dp[i] = -1
	}
	dp[0] = 1

	for i, f := range functions {
		upper := k - 1
		if i < upper {
			upper = i
		}
		for selected := upper; selected >= 0; selected-- {
			if dp[selected] < 0 {
				continue
			}
			value := f.a*dp[selected] + f.b
			if value > dp[selected+1] {
				dp[selected+1] = value
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, dp[k])
}
