	for i := 0; i < n-1; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}

	markedCount := make([]int, n)
	for i := 0; i < k; i++ {
		var v int
		fmt.Fscan(in, &v)
		markedCount[v-1] = 1
	}

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)

		for _, next := range graph[v] {
			if next == parent[v] {
				continue
			}
			parent[next] = v
			stack = append(stack, next)
		}
	}

	edges := 0
	for i := n - 1; i > 0; i-- {
		v := order[i]
		if markedCount[v] > 0 && markedCount[v] < k {
			edges++
		}
		markedCount[parent[v]] += markedCount[v]
	}

