		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := int(in.NextInt64())
	m := int(in.NextInt64())
	x1 := in.NextInt64()

	a := make([]int, m)
	b := make([]int, m)
	s := make([]int64, m)
	t := make([]int64, m)
	x := make([]int64, m)

	for i := 0; i < m; i++ {
		a[i] = int(in.NextInt64()) - 1
		b[i] = int(in.NextInt64()) - 1
		s[i] = in.NextInt64()
		t[i] = in.NextInt64()
	}
	x[0] = x1

	departureOrder := make([]int, m)
	arrivalOrder := make([]int, m)
	for i := 0; i < m; i++ {
		departureOrder[i] = i
		arrivalOrder[i] = i
