		if train == 0 {
			continue
		}

		required := maxArrival[a[train]] - s[train]
		if required > 0 {
			x[train] = required
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for i := 1; i < m; i++ {
		if i > 1 {
