	for i := 0; i < n; i++ {
		var a int
		fmt.Fscan(in, &a)

		primeFactors := 0
		for a > 1 {
			a /= spf[a]
			primeFactors++
		}
		nimSum ^= primeFactors
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if nimSum != 0 {
		fmt.Fprintln(out, "Anna")
	} else {
		fmt.Fprintln(out, "Bruno")
	}
}
