package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	to int
	w  int64
}

type HeapNode struct {
	value       int64
	left, right *HeapNode
	rank        int
}

func heapRank(h *HeapNode) int {
	if h == nil {
		return 0
	}
	return h.rank
}

func meld(a, b *HeapNode) *HeapNode {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	if a.value < b.value {
		a, b = b, a
	}

	a.right = meld(a.right, b)
	if heapRank(a.left) < heapRank(a.right) {
		a.left, a.right = a.right, a.left
	}
	a.rank = heapRank(a.right) + 1
	return a
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	graph := make([][]Edge, n)
	for i := 0; i < n-1; i++ {
		var u, v int
		var w int64
		fmt.Fscan(in, &u, &v, &w)
		u--
		v--
		graph[u] = append(graph[u], Edge{to: v, w: w})
		graph[v] = append(graph[v], Edge{to: u, w: w})
	}

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	order = append(order, 0)
	for i := 0; i < len(order); i++ {
		v := order[i]
		for _, e := range graph[v] {
			if e.to == parent[v] {
				continue
			}
			parent[e.to] = v
			order = append(order, e.to)
		}
	}

	heaps := make([]*HeapNode, n)

	for i := n - 1; i >= 0; i-- {
		v := order[i]
		var h *HeapNode
		hasChild := false

		for _, e := range graph[v] {
			if parent[e.to] != v {
				continue
			}
			hasChild = true
			childHeap := heaps[e.to]
			childHeap.value += e.w
			h = meld(h, childHeap)
		}

		if !hasChild {
			h = &HeapNode{rank: 1}
		}
		heaps[v] = h
	}

	gains := make([]int64, 0)
	h := heaps[0]
	for h != nil {
		gains = append(gains, h.value)
		h = meld(h.left, h.right)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var sum int64
	for k := 1; k <= n; k++ {
		if k <= len(gains) {
			sum += gains[k-1]
		}
		fmt.Fprintln(out, 2*sum)
	}
}
