package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, k int
	fmt.Fscan(in, &n, &k)

	prefix := make([]int64, 2*n+1)
	var total int64
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		total += a[i]
	}
	for i := 0; i < 2*n; i++ {
		prefix[i+1] = prefix[i] + a[i%n]
	}

	// Boundary nodes are 0..2N. root represents an unreachable endpoint.
	nodeCount := 2*n + 1
	root := nodeCount

	head := make([]int, nodeCount+1)
	sibling := make([]int, nodeCount)
	path := make([]int, nodeCount+1)
	iter := make([]int, nodeCount+1)

	// Returns how many circular boundaries can be used in a partition
	// into K parts, each having mass at least x.
	evaluate := func(x int64, stopAtFirst bool) int {
		clear(head)

		j := 0
		for i := 0; i <= 2*n; i++ {
			if j < i {
				j = i
			}
			for j < 2*n && prefix[j]-prefix[i] < x {
				j++
			}

			parent := root
			if prefix[j]-prefix[i] >= x {
				parent = j
			}

			sibling[i] = head[parent]
			head[parent] = i + 1
		}

		count := 0
		path[0] = root
		iter[0] = head[root]
		pathLen := 1

		for pathLen > 0 {
			top := pathLen - 1
			link := iter[top]
			if link == 0 {
				pathLen--
				continue
			}

			child := link - 1
			iter[top] = sibling[child]

			path[pathLen] = child
			iter[pathLen] = head[child]
			pathLen++

			depth := pathLen - 1
			if child < n && depth >= k {
				kthEndpoint := path[depth-k]
				if kthEndpoint <= child+n {
					count++
					if stopAtFirst {
						return count
					}
				}
			}
		}

		return count
	}

	low := int64(0)
	high := total/int64(k) + 1

	for high-low > 1 {
		mid := low + (high-low)/2
		if evaluate(mid, true) > 0 {
			low = mid
		} else {
			high = mid
		}
	}

	cuttable := evaluate(low, false)
	neverCut := n - cuttable

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, low, neverCut)
}
