```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var sign, value int64 = 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return value * sign
}

type SegmentTree struct {
	n       int
	sum     []int64
	max     []int64
	lazy    []int64
	hasLazy []bool
}

func NewSegmentTree(a []int64) *SegmentTree {
	n := len(a)
	st := &SegmentTree{
		n:       n,
		sum:     make([]int64, 4*n),
		max:     make([]int64, 4*n),
		lazy:    make([]int64, 4*n),
		hasLazy: make([]bool, 4*n),
	}
	st.build(1, 0, n, a)
	return st
}

func (st *SegmentTree) build(node, left, right int, a []int64) {
	if right-left == 1 {
		st.sum[node] = a[left]
		st.max[node] = a[left]
		return
	}
	mid := (left + right) / 2
	st.build(node*2, left, mid, a)
	st.build(node*2+1, mid, right, a)
	st.pull(node)
}

func (st *SegmentTree) pull(node int) {
	st.sum[node] = st.sum[node*2] + st.sum[node*2+1]
	if st.max[node*2] > st.max[node*2+1] {
		st.max[node] = st.max[node*2]
	} else {
		st.max[node] = st.max[node*2+1]
	}
}

func (st *SegmentTree) apply(node, left, right int, value int64) {
	st.sum[node] = value * int64(right-left)
	st.max[node] = value
	st.lazy[node] = value
	st.hasLazy[node] = true
}

func (st *SegmentTree) push(node, left, right int) {
	if !st.hasLazy[node] || right-left == 1 {
		return
	}
	mid := (left + right) / 2
	value := st.lazy[node]
	st.apply(node*2, left, mid, value)
	st.apply(node*2+1, mid, right, value)
	st.hasLazy[node] = false
}

func (st *SegmentTree) Assign(ql, qr int, value int64) {
	st.assign(1, 0, st.n, ql, qr, value)
}

func (st *SegmentTree) assign(node, left, right, ql, qr int, value int64) {
	if qr <= left || right <= ql {
		return
	}
	if ql <= left && right <= qr {
		st.apply(node, left, right, value)
		return
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	st.assign(node*2, left, mid, ql, qr, value)
	st.assign(node*2+1, mid, right, ql, qr, value)
	st.pull(node)
}

func (st *SegmentTree) QuerySum(ql, qr int) int64 {
	return st.querySum(1, 0, st.n, ql, qr)
}

func (st *SegmentTree) querySum(node, left, right, ql, qr int) int64 {
	if qr <= left || right <= ql {
		return 0
	}
	if ql <= left && right <= qr {
		return st.sum[node]
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	return st.querySum(node*2, left, mid, ql, qr) +
		st.querySum(node*2+1, mid, right, ql, qr)
}

func (st *SegmentTree) Get(index int) int64 {
	return st.get(1, 0, st.n, index)
}

func (st *SegmentTree) get(node, left, right, index int) int64 {
	if right-left == 1 {
		return st.sum[node]
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if index < mid {
		return st.get(node*2, left, mid, index)
	}
	return st.get(node*2+1, mid, right, index)
}

func (st *SegmentTree) LowerBoundGE(value int64) int {
	if st.max[1] < value {
		return st.n
	}
	return st.lowerBoundGE(1, 0, st.n, value)
}

func (st *SegmentTree) lowerBoundGE(node, left, right int, value int64) int {
	if right-left == 1 {
		return left
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if st.max[node*2] >= value {
		return st.lowerBoundGE(node*2, left, mid, value)
	}
	return st.lowerBoundGE(node*2+1, mid, right, value)
}

func (st *SegmentTree) LowerBoundGT(value int64) int {
	if st.max[1] <= value {
		return st.n
	}
	return st.lowerBoundGT(1, 0, st.n, value)
}

func (st *SegmentTree) lowerBoundGT(node, left, right int, value int64) int {
	if right-left == 1 {
		return left
	}
	st.push(node, left, right)
	mid := (left + right) / 2
	if st.max[node*2] > value {
		return st.lowerBoundGT(node*2, left, mid, value)
	}
	return st.lowerBoundGT(node*2+1, mid, right, value)
}

func main() {
	in := NewFastScanner()
	n := int(in.NextInt64())

	values := make([]int64, n)
	for i := 0; i < n; i++ {
		x := in.NextInt64()
		values[i] = x - int64(i+1)
	}

	st := NewSegmentTree(values)
	q := int(in.NextInt64())
	var answer int64

	for ; q > 0; q-- {
		t := int(in.NextInt64()) - 1
		g := in.NextInt64()
		target := g - int64(t+1)
		current := st.Get(t)

		if current < target {
			right := st.LowerBoundGE(target)
			oldSum := st.QuerySum(t, right)
			newSum := target * int64(right-t)
			answer += newSum - oldSum
			st.Assign(t, right, target)
		} else if current > target {
			left := st.LowerBoundGT(target)
			oldSum := st.QuerySum(left, t+1)
			newSum := target * int64(t+1-left)
			answer += oldSum - newSum
			st.Assign(left, t+1, target)
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
