package main

import (
	"bufio"
	"fmt"
	"os"
)

type factor struct {
	prime int
	power int
}

func modInverse(a, mod int) int {
	b, u, v := mod, 1, 0
	for b != 0 {
		t := a / b
		a, b = b, a-t*b
		u, v = v, u-t*v
	}
	u %= mod
	if u < 0 {
		u += mod
	}
	return u
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	p := make([]int, n)
	a := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	spf := make([]int, n+1)
	for i := 2; i <= n; i++ {
		if spf[i] != 0 {
			continue
		}
		spf[i] = i
		if i <= n/i {
			for j := i * i; j <= n; j += i {
				if spf[j] == 0 {
					spf[j] = i
				}
			}
		}
	}

	maxPower := make([]int, n+1)
	remainder := make([]int, n+1)
	visited := make([]bool, n)
	answer := make([]int, n)

	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		cycle := make([]int, 0)
		for cur := start; !visited[cur]; cur = p[cur] {
			visited[cur] = true
			cycle = append(cycle, cur)
		}

		length := len(cycle)
		x := length
		factors := make([]factor, 0)

		for x > 1 {
			prime := spf[x]
			power := 1
			for x%prime == 0 {
				x /= prime
				power *= prime
			}
			factors = append(factors, factor{prime: prime, power: power})
		}

		// Reconstruct the already-fixed residue modulo gcd(M, length),
		// where M is the LCM of previously processed cycle lengths.
		base, modulus := 0, 1
		for _, f := range factors {
			component := f.power
			if maxPower[f.prime] < component {
				component = maxPower[f.prime]
			}
			if component <= 1 {
				continue
			}

			target := remainder[f.prime] % component
			delta := (target - base) % component
			if delta < 0 {
				delta += component
			}

			inv := modInverse(modulus%component, component)
			t := (delta * inv) % component
			base += modulus * t
			modulus *= component
			base %= modulus
		}

		bestShift := base
		bestValue := n + 1
		for shift := base; shift < length; shift += modulus {
			value := a[cycle[shift]]
			if value < bestValue {
				bestValue = value
				bestShift = shift
			}
		}

		for _, f := range factors {
			if f.power > maxPower[f.prime] {
				maxPower[f.prime] = f.power
				remainder[f.prime] = bestShift % f.power
			}
		}

		for i, index := range cycle {
			answer[index] = a[cycle[(i+bestShift)%length]]
		}
	}

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}
