func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, k int
	fmt.Fscan(in, &n, &m, &k)

	x := make([]int, m)
	y := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(in, &x[i], &y[i])
		x[i]--
		y[i]--
	}

	// At time t, phase p represents vertex (p+t) mod n.
	// Ordinary cycle edges preserve the phase.
	dp := make([]int64, n)
	dp[0] = 1

	values := make([]int64, m)
	total := int64(1)

	for t := 0; t < k; t++ {
		shift := t % n

		// Read all source values before applying any extra edge.
		for i := 0; i < m; i++ {
			idx := x[i] - shift
			if idx < 0 {
				idx += n
			}
			values[i] = dp[idx]
		}

		nextShift := shift + 1
		if nextShift == n {
			nextShift = 0
		}

		for i := 0; i < m; i++ {
			v := values[i]
			idx := y[i] - nextShift
			if idx < 0 {
				idx += n
			}

			dp[idx] += v
			if dp[idx] >= mod {
				dp[idx] -= mod
			}

			total += v
			if total >= mod {
				total -= mod
			}
		}
	}

	fmt.Fprintln(out, total)
}
