```go
package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

type Line struct {
	a, b int64
	d    int64
}

func ceilDiv(p, q int64) int64 {
	v := p / q
	if p%q > 0 {
		v++
	}
	return v
}

// Returns sum_{i=0}^{n-1} floor((a*i+b)/m).
func floorSum(n, m, a, b int64) int64 {
	var ans int64

	if a >= m {
		ans += (n * (n - 1) / 2) * (a / m)
		a %= m
	}
	if b >= m {
		ans += n * (b / m)
		b %= m
	}

	for {
		yMax := a*n + b
		if yMax < m {
			break
		}
		n = yMax / m
		b = yMax % m
		m, a = a, m
		if a >= m {
			ans += (n * (n - 1) / 2) * (a / m)
			a %= m
		}
		if b >= m {
			ans += n * (b / m)
			b %= m
		}
	}
	return ans
}

func main() {
	in := NewFastScanner()
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	T := int(in.NextInt64())
	for ; T > 0; T-- {
		N := int(in.NextInt64())
		lines := make([]Line, 0, N)
		valid := true
		var xMax int64 = math.MaxInt64

		for i := 0; i < N; i++ {
			a := in.NextInt64()
			b := in.NextInt64()
			c := in.NextInt64()

			// Set x=X+1 and y=Y+1. The inequality becomes:
			// a*X + b*Y <= c-a-b-1.
			d := c - a - b - 1
			if d < 0 {
				valid = false
			} else {
				if d/a < xMax {
					xMax = d / a
				}
				lines = append(lines, Line{a: a, b: b, d: d})
			}
		}

		if !valid {
			fmt.Fprintln(out, 0)
			continue
		}

		// Sort by a/b increasingly, i.e. line slopes -a/b decreasingly.
		sort.Slice(lines, func(i, j int) bool {
			left := lines[i].a * lines[j].b
			right := lines[j].a * lines[i].b
			if left != right {
				return left < right
			}
			// For equal slopes, lower intercept d/b is better.
			left = lines[i].d * lines[j].b
			right = lines[j].d * lines[i].b
			return left < right
		})

		// Remove redundant lines with equal slopes.
		unique := make([]Line, 0, len(lines))
		for i := 0; i < len(lines); {
			best := lines[i]
			j := i + 1
			for j < len(lines) &&
				lines[j].a*lines[i].b == lines[i].a*lines[j].b {
				if lines[j].d*best.b < best.d*lines[j].b {
					best = lines[j]
				}
				j++
			}
			unique = append(unique, best)
			i = j
		}

		// Build the lower envelope on integer X.
		hull := make([]Line, 0, len(unique))
		start := make([]int64, 0, len(unique))

		for _, ln := range unique {
			if len(hull) == 0 {
				hull = append(hull, ln)
				start = append(start, math.MinInt64)
				continue
			}

			for {
				last := hull[len(hull)-1]
				// First integer X where ln(X) <= last(X).
				p := ln.d*last.b - last.d*ln.b
				q := ln.a*last.b - last.a*ln.b
				k := ceilDiv(p, q)

				if len(hull) == 1 || k > start[len(start)-1] {
					hull = append(hull, ln)
					start = append(start, k)
					break
				}

				hull = hull[:len(hull)-1]
				start = start[:len(start)-1]
			}
		}

		var answer int64
		for i, ln := range hull {
			l := start[i]
			if l < 0 {
				l = 0
			}
			if l > xMax {
				break
			}

			r := xMax
			if i+1 < len(hull) && start[i+1]-1 < r {
				r = start[i+1] - 1
			}
			if l > r {
				continue
			}

			n := r - l + 1
			base := ln.d - ln.a*r
			sumY := floorSum(n, ln.b, ln.a, base)

			// For each X, Y ranges from 0 through floor(boundary).
			answer += sumY + n
		}

		fmt.Fprintln(out, answer)
	}
}
