func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	var k int64
	fmt.Fscan(in, &n, &m, &k)

	candidates := make([]Candidate, n)
	var counted int64
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &candidates[i].v)
		candidates[i].idx = i
		counted += candidates[i].v
	}

	remaining := k - counted
	ans := make([]int64, n)

	if m == n {
		for i := 0; i < n; i++ {
			if i > 0 {
				fmt.Fprint(out, " ")
			}
			fmt.Fprint(out, 0)
		}
		fmt.Fprintln(out)
		return
	}

	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].v == candidates[j].v {
			return candidates[i].idx < candidates[j].idx
		}
		return candidates[i].v < candidates[j].v
	})

	values := make([]int64, n)
	prefix := make([]int64, n+1)
	for i, c := range candidates {
		values[i] = c.v
		prefix[i+1] = prefix[i] + c.v
	}

	for pos, c := range candidates {
		guaranteed := func(x int64) bool {
			target := c.v + x
			needVote := target + 1

			var left int
			excludeSelf := false

			if pos < n-m {
				left = n - m
			} else {
				left = n - m - 1
				excludeSelf = true
			}

			q := sort.Search(n, func(i int) bool {
				return values[i] >= needVote
			})
			if q < left {
				q = left
			}

			cost := needVote*int64(q-left) - (prefix[q] - prefix[left])
			if excludeSelf {
				cost -= needVote - c.v
			}

			return cost > remaining-x
		}

		if !guaranteed(remaining) {
			ans[c.idx] = -1
			continue
		}

		low, high := int64(-1), remaining
		for high-low > 1 {
			mid := low + (high-low)/2
			if guaranteed(mid) {
				high = mid
			} else {
				low = mid
			}
		}
		ans[c.idx] = high
	}

	for i, v := range ans {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v)
	}
	fmt.Fprintln(out)
}
