package main

import (
	"bufio"
	"fmt"
	"os"
)

type Line struct {
	m, b int64
}

func (l Line) value(x int64) int64 {
	return l.m*x + l.b
}

func redundant(a, b, c Line) bool {
	return (a.b-b.b)*(c.m-b.m) >= (b.b-c.b)*(b.m-a.m)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, W int
	fmt.Fscan(in, &n, &W)

	dp := make([]int64, W+1)

	for i := 0; i < n; i++ {
		var w int
		var v int64
		fmt.Fscan(in, &w, &v)

		next := make([]int64, W+1)

		for r := 0; r < w && r <= W; r++ {
			hull := make([]Line, 0, (W-r)/w+1)
			head := 0

			for j, pos := 0, r; pos <= W; j, pos = j+1, pos+w {
				t := int64(j)
				line := Line{
					m: 2 * t,
					b: dp[pos] - t*v - t*t,
				}

				for len(hull)-head >= 2 &&
					redundant(hull[len(hull)-2], hull[len(hull)-1], line) {
					hull = hull[:len(hull)-1]
				}
				hull = append(hull, line)

				x := t
				for len(hull)-head >= 2 &&
					hull[head].value(x) <= hull[head+1].value(x) {
					head++
				}

				next[pos] = t*v - t*t + hull[head].value(x)
			}
		}

		dp = next
	}

	fmt.Fprintln(out, dp[W])
}
