func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	var x int64
	fmt.Fscan(in, &n, &k, &x)

	t := make([]int64, n)
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &t[i])
		prefix[i+1] = prefix[i] + t[i]
	}

	// dp[i][s] is the minimum dissatisfaction for the first i orders
	// when the last shipment is made on day s.
	dp := make([]map[int64]int64, n+1)
	dp[0] = map[int64]int64{0: 0}

	for done := 0; done < n; done++ {
		for lastDay, currentCost := range dp[done] {
			maxBatch := k
			if n-done < maxBatch {
				maxBatch = n - done
			}

			for size := 1; size <= maxBatch; size++ {
				next := done + size
				shipDay := t[next-1]

				if done > 0 && lastDay+x > shipDay {
					shipDay = lastDay + x
				}

				addedCost := int64(size)*shipDay - (prefix[next] - prefix[done])
				newCost := currentCost + addedCost

				if dp[next] == nil {
					dp[next] = make(map[int64]int64)
				}
				oldCost, exists := dp[next][shipDay]
				if !exists || newCost < oldCost {
					dp[next][shipDay] = newCost
				}
			}
		}
	}

	var answer int64 = 1<<63 - 1
	for _, cost := range dp[n] {
		if cost < answer {
			answer = cost
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
