	var n int
	fmt.Fscan(in, &n)

	grid := make([]byte, n*n)
	for i := 0; i < n; i++ {
		var row string
		fmt.Fscan(in, &row)
		copy(grid[i*n:(i+1)*n], row)
	}

	result := make([]byte, n*n)

	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			depth := r
			if c < depth {
				depth = c
			}
			if n-1-r < depth {
				depth = n - 1 - r
			}
			if n-1-c < depth {
				depth = n - 1 - c
			}

			rotations := (depth + 1) % 4
			var nr, nc int

			switch rotations {
			case 0:
				nr, nc = r, c
			case 1:
				nr, nc = c, n-1-r
			case 2:
				nr, nc = n-1-r, n-1-c
			case 3:
				nr, nc = n-1-c, r
			}

			result[nr*n+nc] = grid[r*n+c]
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for r := 0; r < n; r++ {
		out.Write(result[r*n : (r+1)*n])
		out.WriteByte('\n')
	}
