	}

	target := total / 3
	for _, b := range strengths {
		if b > target {
			fmt.Fprintln(out, -1)
			return
		}
	}

	width := target + 1
	size := width * width
	dp := make([]int16, size)
	next := make([]int16, size)

	for i := range dp {
		dp[i] = -1
	}
	dp[0] = 0

	processed := 0
	for i := 0; i < n; i++ {
		for j := range next {
			next[j] = -1
		}

		a, b := teams[i], strengths[i]

		for x := 0; x <= target; x++ {
			base := x * width
			for y := 0; y <= target; y++ {
				idx := base + y
				cur := dp[idx]
				if cur < 0 {
					continue
				}

				z := processed - x - y

				if x+b <= target {
					nidx := (x+b)*width + y
					value := cur
