func moveCost(n, start, target, blocked int) int {
	clockwise := (target - start + n) % n
	toBlocked := (blocked - start + n) % n

	if toBlocked < clockwise {
		return n - clockwise
	}
	return clockwise
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
