		var target int
		fmt.Fscan(in, &hand, &target)
		target--

		if hand == "L" {
			total += moveCost(n, left, target, right)
			left = target
		} else {
			total += moveCost(n, right, target, left)
			right = target
		}
	}

	fmt.Fprintln(out, total)
