	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	graph := make([][]int, n)
	incomingToOne := make([]int, 0)

	for i := 0; i < m; i++ {
		a := in.NextInt() - 1
		b := in.NextInt() - 1
		graph[a] = append(graph[a], b)
		if b == 0 {
			incomingToOne = append(incomingToOne, a)
		}
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}

	queue := make([]int, 0, n)
	dist[0] = 0
	queue = append(queue, 0)

	for head := 0; head < len(queue); head++ {
		v := queue[head]
		for _, next := range graph[v] {
			if dist[next] == -1 {
				dist[next] = dist[v] + 1
				queue = append(queue, next)
