func modPow(base, exp, mod int64) int64 {
	result := int64(1 % mod)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	p := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}

	answer := make([]int, n)
	visited := make([]bool, n)

	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		cycle := make([]int, 0)
		for current := start; !visited[current]; current = p[current] {
			visited[current] = true
			cycle = append(cycle, current)
		}

		length := len(cycle)
		shift := int(modPow(2, k, int64(length)))

		for i, vertex := range cycle {
			answer[vertex] = cycle[(i+shift)%length]
		}
	}

	for i, value := range answer {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value+1)
	}
	fmt.Fprintln(out)
}
