	defer out.Flush()

	var n int64
	var m int
	fmt.Fscan(in, &n, &m)

	rows := make(map[int64]struct{})
	cols := make(map[int64]struct{})
	sums := make(map[int64]struct{})
	diffs := make(map[int64]struct{})

	rowList := make([]int64, 0, m)
	colList := make([]int64, 0, m)
	sumList := make([]int64, 0, m)
	diffList := make([]int64, 0, m)

	for k := 0; k < m; k++ {
		var a, b int64
		fmt.Fscan(in, &a, &b)

		if _, ok := rows[a]; !ok {
			rows[a] = struct{}{}
			rowList = append(rowList, a)
		}
		if _, ok := cols[b]; !ok {
			cols[b] = struct{}{}
			colList = append(colList, b)
		}

		s := a + b
		if _, ok := sums[s]; !ok {
			sums[s] = struct{}{}
			sumList = append(sumList, s)
		}

		d := a - b
		if _, ok := diffs[d]; !ok {
			diffs[d] = struct{}{}
			diffList = append(diffList, d)
		}
	}

	availableRows := n - int64(len(rowList))
	availableCols := n - int64(len(colList))
	answer := availableRows * availableCols

	var attackedBySum int64
	for _, s := range sumList {
		low := int64(1)
		if s-n > low {
			low = s - n
		}
		high := n
		if s-1 < high {
			high = s - 1
		}

		count := high - low + 1

		for _, r := range rowList {
			c := s - r
			if 1 <= c && c <= n {
				count--
			}
		}
		for _, c := range colList {
			r := s - c
			if 1 <= r && r <= n {
				count--
			}
		}
		for _, r := range rowList {
			c := s - r
			if _, ok := cols[c]; ok {
				count++
			}
		}

		attackedBySum += count
	}

	var attackedByDiff int64
	for _, d := range diffList {
		absD := d
		if absD < 0 {
			absD = -absD
		}
		count := n - absD

		for _, r := range rowList {
			c := r - d
			if 1 <= c && c <= n {
				count--
			}
		}
		for _, c := range colList {
			r := c + d
			if 1 <= r && r <= n {
				count--
			}
		}
		for _, r := range rowList {
			c := r - d
			if _, ok := cols[c]; ok {
				count++
			}
		}

		attackedByDiff += count
	}

	var attackedByBoth int64
	for _, s := range sumList {
		for _, d := range diffList {
			if (s+d)%2 != 0 {
				continue
			}

			r := (s + d) / 2
			c := (s - d) / 2
			if r < 1 || r > n || c < 1 || c > n {
				continue
			}
			if _, blocked := rows[r]; blocked {
				continue
			}
			if _, blocked := cols[c]; blocked {
				continue
			}
			attackedByBoth++
		}
	}

	answer -= attackedBySum + attackedByDiff - attackedByBoth
	fmt.Fprintln(out, answer)
}
