package main

import (
	"bufio"
	"fmt"
	"os"
)

type Fenwick struct {
	tree []int64
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{tree: make([]int64, n+1)}
}

func (f *Fenwick) Add(index int, value int64) {
	for index < len(f.tree) {
		f.tree[index] += value
		index += index & -index
	}
}

func (f *Fenwick) Sum(index int) int64 {
	var result int64
	for index > 0 {
		result += f.tree[index]
		index -= index & -index
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	counts := NewFenwick(m)
	counts.Add(1, 1) // Initial prefix sum residue 0.

	var prefix int64
	var sumPrevious int64
	var answer int64

	for j := 1; j <= n; j++ {
		var a int64
		fmt.Fscan(in, &a)

		prefix = (prefix + a) % int64(m)

		// Fenwick index for residue x is x+1. Sum(x+1) counts residues <= x.
		lessOrEqual := counts.Sum(int(prefix) + 1)
		greater := int64(j) - lessOrEqual

		answer += int64(j)*prefix - sumPrevious + int64(m)*greater

		sumPrevious += prefix
		counts.Add(int(prefix)+1, 1)
	}

	fmt.Fprintln(out, answer)
}
