package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, val := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		val = val*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * val
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()

	h := make([]int, n)
	for i := range h {
		h[i] = in.NextInt()
	}

	size := 1
	for size < n {
		size <<= 1
	}
	seg := make([]int, 2*size)
	for i := 0; i < n; i++ {
		seg[size+i] = h[i]
	}
	for i := size - 1; i >= 1; i-- {
		if seg[i<<1] > seg[i<<1|1] {
			seg[i] = seg[i<<1]
		} else {
			seg[i] = seg[i<<1|1]
		}
	}

	rangeMax := func(left, right int) int {
		left += size
		right += size
		result := 0
		for left < right {
			if left&1 == 1 {
				if seg[left] > result {
					result = seg[left]
				}
				left++
			}
			if right&1 == 1 {
				right--
				if seg[right] > result {
					result = seg[right]
				}
			}
			left >>= 1
			right >>= 1
		}
		return result
	}

	var findFirst func(node, nl, nr, ql, threshold int) int
	findFirst = func(node, nl, nr, ql, threshold int) int {
		if nr <= ql || seg[node] <= threshold {
			return -1
		}
		if nr-nl == 1 {
			if nl < n {
				return nl
			}
			return -1
		}
		mid := (nl + nr) >> 1
		if result := findFirst(node<<1, nl, mid, ql, threshold); result != -1 {
			return result
		}
		return findFirst(node<<1|1, mid, nr, ql, threshold)
	}

	// chainLength[i] is the number of record-high buildings obtained by
	// starting at i and repeatedly moving to the nearest taller building.
	chainLength := make([]int, n)
	stack := make([]int, 0, n)
	for i := n - 1; i >= 0; i-- {
		for len(stack) > 0 && h[stack[len(stack)-1]] < h[i] {
			stack = stack[:len(stack)-1]
		}
		chainLength[i] = 1
		if len(stack) > 0 {
			chainLength[i] += chainLength[stack[len(stack)-1]]
		}
		stack = append(stack, i)
	}

	for ; q > 0; q-- {
		l := in.NextInt()
		r := in.NextInt()

		// In zero-based indexing, buildings l+1 through r are [l, r).
		threshold := rangeMax(l, r)
		first := findFirst(1, 0, size, r, threshold)

		if first == -1 {
			fmt.Fprintln(out, 0)
		} else {
			fmt.Fprintln(out, chainLength[first])
		}
	}
}
