package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	q := in.NextInt()

	parent := make([]int, n+1)
	size := make([]int, n+1)
	left := make([]int, n+1)
	right := make([]int, n+1)
	color := make([]int, n+1)
	colorCount := make([]int, n+1)

	for i := 1; i <= n; i++ {
		parent[i] = i
		size[i] = 1
		left[i] = i
		right[i] = i
		color[i] = i
		colorCount[i] = 1
	}

	var find func(int) int
	find = func(x int) int {
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}

	merge := func(a, b int) int {
		a = find(a)
		b = find(b)
		if a == b {
			return a
		}
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
		if left[b] < left[a] {
			left[a] = left[b]
		}
		if right[b] > right[a] {
			right[a] = right[b]
		}
		return a
	}

	for ; q > 0; q-- {
		queryType := in.NextInt()

		if queryType == 1 {
			x := in.NextInt()
			newColor := in.NextInt()

			root := find(x)
			oldColor := color[root]

			if oldColor == newColor {
				continue
			}

			colorCount[oldColor] -= size[root]
			colorCount[newColor] += size[root]
			color[root] = newColor

			if left[root] > 1 {
				neighbor := find(left[root] - 1)
				if color[neighbor] == newColor {
					root = merge(root, neighbor)
					color[root] = newColor
				}
			}

			if right[root] < n {
				neighbor := find(right[root] + 1)
				if color[neighbor] == newColor {
					root = merge(root, neighbor)
					color[root] = newColor
				}
			}
		} else {
			c := in.NextInt()
			fmt.Fprintln(out, colorCount[c])
		}
	}
