package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m, l int
	fmt.Fscan(in, &n, &m, &l)

	k := n + m + l
	values := make([]int64, k)
	for i := 0; i < k; i++ {
		fmt.Fscan(in, &values[i])
	}

	pow3 := make([]int, k+1)
	pow3[0] = 1
	for i := 0; i < k; i++ {
		pow3[i+1] = pow3[i] * 3
	}
	stateCount := pow3[k]

	// Trit 0: table, 1: Takahashi's hand, 2: Aoki's hand.
	initial := 0
	for i := 0; i < n; i++ {
		initial += pow3[i]
	}
	for i := n; i < n+m; i++ {
		initial += 2 * pow3[i]
	}

	lessMask := make([]int, k)
	for i := 0; i < k; i++ {
		for j := 0; j < k; j++ {
			if values[j] < values[i] {
				lessMask[i] |= 1 << j
			}
		}
	}

	// 0: unknown, 1: losing, 2: winning.
	memo := make([]uint8, 2*stateCount)

	var win func(code, turn int) bool
	win = func(code, turn int) bool {
		idx := turn*stateCount + code
		if memo[idx] != 0 {
			return memo[idx] == 2
		}

		owner := turn + 1
		x := code
		handMask, tableMask := 0, 0
		for i := 0; i < k; i++ {
			digit := x % 3
			x /= 3
			if digit == owner {
				handMask |= 1 << i
			} else if digit == 0 {
				tableMask |= 1 << i
			}
		}

		if handMask == 0 {
			memo[idx] = 1
			return false
		}

		for cards := handMask; cards != 0; cards &= cards - 1 {
			i := bits.TrailingZeros(uint(cards))
			afterPlay := code - owner*pow3[i]

			// Do not take a card from the table.
			if !win(afterPlay, 1-turn) {
				memo[idx] = 2
				return true
			}

			// Take a strictly smaller card from the table.
			candidates := tableMask & lessMask[i]
			for candidates != 0 {
				j := bits.TrailingZeros(uint(candidates))
				candidates &= candidates - 1
				next := afterPlay + owner*pow3[j]
				if !win(next, 1-turn) {
					memo[idx] = 2
					return true
				}
			}
		}

		memo[idx] = 1
		return false
	}

	if win(initial, 0) {
		fmt.Fprintln(out, "Takahashi")
	} else {
		fmt.Fprintln(out, "Aoki")
	}
}
