package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type Fenwick struct {
	n    int
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int, n+1),
	}
}

func (f *Fenwick) Add(i, delta int) {
	for i <= f.n {
		f.tree[i] += delta
		i += i & -i
	}
}

func (f *Fenwick) Sum(i int) int {
	result := 0
	for i > 0 {
		result += f.tree[i]
		i -= i & -i
	}
	return result
}

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, k int
	fmt.Fscan(in, &n, &k)

	p := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
	}

	// Inversion count of the entire permutation.
	globalBIT := NewFenwick(n)
	var totalInv int64
	for i, x := range p {
		totalInv += int64(i - globalBIT.Sum(x))
		globalBIT.Add(x, 1)
	}

	// Inversion counts of all length-K subarrays using a sliding window.
	windowBIT := NewFenwick(n)
	var currentInv int64
	for i := 0; i < k; i++ {
		x := p[i]
		currentInv += int64(i - windowBIT.Sum(x))
		windowBIT.Add(x, 1)
	}

	var sumWindowInv int64 = currentInv
	windowCount := n - k + 1

	for start := 1; start < windowCount; start++ {
		removed := p[start-1]
		currentInv -= int64(windowBIT.Sum(removed - 1))
		windowBIT.Add(removed, -1)

		added := p[start+k-1]
		currentInv += int64((k - 1) - windowBIT.Sum(added))
		windowBIT.Add(added, 1)

		sumWindowInv += currentInv
	}

	inv2 := (mod + 1) / 2
	pairCount := int64(k) * int64(k-1) / 2
	expectedShuffledInternal := (pairCount % mod) * inv2 % mod

	averageOriginalInternal := (sumWindowInv % mod) *
		modPow(int64(windowCount), mod-2) % mod

	answer := (totalInv%mod + expectedShuffledInternal - averageOriginalInternal) % mod
	if answer < 0 {
		answer += mod
	}

	fmt.Fprintln(out, answer)
}
