	pref2 := make([]int, n+1)
	prefSlash := make([]int, n+1)
	pos1 := make([]int, 0)
	pos2 := make([]int, 0)

	for i := 1; i <= n; i++ {
		pref1[i] = pref1[i-1]
		pref2[i] = pref2[i-1]
		prefSlash[i] = prefSlash[i-1]

		switch s[i-1] {
		case '1':
			pref1[i]++
			pos1 = append(pos1, i)
		case '2':
			pref2[i]++
			pos2 = append(pos2, i)
		case '/':
			prefSlash[i]++
		}
	}

	for ; q > 0; q-- {
		var l, r int
		fmt.Fscan(in, &l, &r)

		if prefSlash[r]-prefSlash[l-1] == 0 {
			fmt.Fprintln(out, 0)
			continue
		}

		count1 := pref1[r] - pref1[l-1]
		count2 := pref2[r] - pref2[l-1]
		maxK := count1
		if count2 < maxK {
			maxK = count2
		}

		lo, hi := 0, maxK+1
		for hi-lo > 1 {
			k := (lo + hi) / 2

			// Position of the k-th '1' from the left in [l, r].
			rank1 := pref1[l-1] + k
			a := pos1[rank1-1]

			// Position of the k-th '2' from the right in [l, r].
			rank2 := pref2[r] - k + 1
			b := pos2[rank2-1]

			// A valid slash must lie strictly between a and b.
			if a < b && prefSlash[b-1]-prefSlash[a] > 0 {
				lo = k
			} else {
				hi = k
			}
		}

