package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Bar struct {
	r, c, l int
	id      int
}

type SegmentTree struct {
	n    int
	min  []int
	lazy []int
}

func NewSegmentTree(n, initial int) *SegmentTree {
	st := &SegmentTree{
		n:    n,
		min:  make([]int, 4*n),
		lazy: make([]int, 4*n),
	}
	st.build(1, 1, n, initial)
	return st
}

func (st *SegmentTree) build(node, left, right, value int) {
	st.min[node] = value
	st.lazy[node] = value
	if left == right {
		return
	}
	mid := (left + right) / 2
	st.build(node*2, left, mid, value)
	st.build(node*2+1, mid+1, right, value)
}

func (st *SegmentTree) apply(node, value int) {
	st.min[node] = value
	st.lazy[node] = value
}

func (st *SegmentTree) push(node int) {
	if st.lazy[node] != -1 {
		st.apply(node*2, st.lazy[node])
		st.apply(node*2+1, st.lazy[node])
		st.lazy[node] = -1
	}
}

func (st *SegmentTree) assign(node, left, right, ql, qr, value int) {
	if ql <= left && right <= qr {
		st.apply(node, value)
		return
	}
	st.push(node)
	mid := (left + right) / 2
	if ql <= mid {
		st.assign(node*2, left, mid, ql, qr, value)
	}
	if mid < qr {
		st.assign(node*2+1, mid+1, right, ql, qr, value)
	}
	if st.min[node*2] < st.min[node*2+1] {
		st.min[node] = st.min[node*2]
	} else {
		st.min[node] = st.min[node*2+1]
	}
}

func (st *SegmentTree) Assign(left, right, value int) {
	st.assign(1, 1, st.n, left, right, value)
}

func (st *SegmentTree) query(node, left, right, ql, qr int) int {
	if ql <= left && right <= qr {
		return st.min[node]
	}
	st.push(node)
	mid := (left + right) / 2
	result := int(^uint(0) >> 1)
	if ql <= mid {
		v := st.query(node*2, left, mid, ql, qr)
		if v < result {
			result = v
		}
	}
	if mid < qr {
		v := st.query(node*2+1, mid+1, right, ql, qr)
		if v < result {
			result = v
		}
	}
	return result
}

func (st *SegmentTree) Query(left, right int) int {
	return st.query(1, 1, st.n, left, right)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var H, W, N int
	fmt.Fscan(in, &H, &W, &N)

	bars := make([]Bar, N)
	for i := 0; i < N; i++ {
		fmt.Fscan(in, &bars[i].r, &bars[i].c, &bars[i].l)
		bars[i].id = i
	}

	sort.Slice(bars, func(i, j int) bool {
		if bars[i].r != bars[j].r {
			return bars[i].r > bars[j].r
		}
		return bars[i].id < bars[j].id
	})

	st := NewSegmentTree(W, H+1)
	answer := make([]int, N)

	for _, bar := range bars {
		left := bar.c
		right := bar.c + bar.l - 1
		finalRow := st.Query(left, right) - 1
		answer[bar.id] = finalRow
		st.Assign(left, right, finalRow)
	}

	for i := 0; i < N; i++ {
		fmt.Fprintln(out, answer[i])
	}
}
