```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1 << 62

type Matrix [2][2]int64

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func floorDiv(a, b int64) int64 {
	q := a / b
	r := a % b
	if r < 0 {
		q--
	}
	return q
}

func floorMod(a, b int64) int64 {
	r := a % b
	if r < 0 {
		r += b
	}
	return r
}

func parity(x int64) int64 {
	r := x % 2
	if r < 0 {
		r += 2
	}
	return r
}

func matMul(a, b Matrix) Matrix {
	var c Matrix
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			c[i][j] = INF
			for k := 0; k < 2; k++ {
				if a[i][k] >= INF || b[k][j] >= INF {
					continue
				}
				v := a[i][k] + b[k][j]
				if v < c[i][j] {
					c[i][j] = v
				}
			}
		}
	}
	return c
}

func apply(v [2]int64, m Matrix) [2]int64 {
	res := [2]int64{INF, INF}
	for j := 0; j < 2; j++ {
		for i := 0; i < 2; i++ {
			if v[i] >= INF || m[i][j] >= INF {
				continue
			}
			x := v[i] + m[i][j]
			if x < res[j] {
				res[j] = x
			}
		}
	}
	return res
}

func applyPow(v [2]int64, m Matrix, e int64) [2]int64 {
	for e > 0 {
		if e&1 == 1 {
			v = apply(v, m)
		}
		m = matMul(m, m)
		e >>= 1
	}
	return v
}

// Direction 0 is X, direction 1 is Y.
func transitionMatrix(startParity, r, badCost, lambda int64) Matrix {
	var m Matrix
	intermediateParity := (startParity + r) & 1
	for from := 0; from < 2; from++ {
		for to := 0; to < 2; to++ {
			cost := int64(0)
			if from == to {
				if (to == 0 && intermediateParity == 1) ||
					(to == 1 && intermediateParity == 0) {
					cost += badCost
				}
			}
			if to == 0 {
				cost += lambda
			}
			m[from][to] = cost
		}
	}
	return m
}

func lagrangianCost(n, xCount, startParity, badCost int64, first, last int) int64 {
	if n == 1 {
		if first != last {
			return INF
		}
		expected := int64(0)
		if first == 0 {
			expected = 1
		}
		if xCount != expected {
			return INF
		}
		return 0
	}

	fixedX := int64(0)
	if first == 0 {
		fixedX++
	}
	if last == 0 {
		fixedX++
	}
	if xCount < fixedX || xCount > fixedX+n-2 {
		return INF
	}

	best := -INF
	for lambda := int64(-20); lambda <= 20; lambda++ {
		v := [2]int64{INF, INF}
		v[first] = 0
		if first == 0 {
			v[first] += lambda
		}

		transitions := n - 1
		m1 := transitionMatrix(startParity, 1, badCost, lambda)
		m2 := transitionMatrix(startParity, 2, badCost, lambda)
		pair := matMul(m1, m2)

		v = applyPow(v, pair, transitions/2)
		if transitions&1 == 1 {
			v = apply(v, m1)
		}

		if v[last] < INF {
			candidate := v[last] - lambda*xCount
			if candidate > best {
				best = candidate
			}
		}
	}
	return best
}

func endpointPenalty(
	K, k int64,
	orientation, direction int,
	sign int64,
	isStart bool,
) int64 {
	// Horizontal tiles are unrestricted when crossing in X.
	// Vertical tiles are unrestricted when crossing in Y.
	if (orientation == 0 && direction == 0) ||
		(orientation == 1 && direction == 1) {
		return 0
	}

	var required int64
	if isStart {
		if sign > 0 {
			required = K - 1
		} else {
			required = 0
		}
	} else {
		if sign > 0 {
			required = 0
		} else {
			required = K - 1
		}
	}

	d := abs64(k - required)
	return min64(d, 2)
}

func solve(K, sx, sy, tx, ty int64) int64 {
	si := floorDiv(sx, K)
	sj := floorDiv(sy, K)
	ti := floorDiv(tx, K)
	tj := floorDiv(ty, K)

	sOrientation := int(parity(si + sj)) // 0: horizontal, 1: vertical
	tOrientation := int(parity(ti + tj))

	var sk, tk int64
	if sOrientation == 0 {
		sk = floorMod(sy, K)
	} else {
		sk = floorMod(sx, K)
	}
	if tOrientation == 0 {
		tk = floorMod(ty, K)
	} else {
		tk = floorMod(tx, K)
	}

	if si == ti && sj == tj {
		return min64(abs64(sk-tk), 2)
	}

	dx := ti - si
	dy := tj - sj
	xCount := abs64(dx)
	yCount := abs64(dy)
	n := xCount + yCount

	var xSign, ySign int64
	if dx > 0 {
		xSign = 1
	} else if dx < 0 {
		xSign = -1
	}
	if dy > 0 {
		ySign = 1
	} else if dy < 0 {
		ySign = -1
	}

	badCost := min64(K-1, 2)
	startParity := parity(si + sj)
	answer := INF

	for first := 0; first < 2; first++ {
		if (first == 0 && xCount == 0) || (first == 1 && yCount == 0) {
			continue
		}
		for last := 0; last < 2; last++ {
			if (last == 0 && xCount == 0) || (last == 1 && yCount == 0) {
				continue
			}

			internal := lagrangianCost(
				n, xCount, startParity, badCost, first, last,
			)
			if internal >= INF {
				continue
			}

			var firstSign, lastSign int64
			if first == 0 {
				firstSign = xSign
			} else {
				firstSign = ySign
			}
			if last == 0 {
				lastSign = xSign
			} else {
				lastSign = ySign
			}

			startCost := endpointPenalty(
				K, sk, sOrientation, first, firstSign, true,
			)
			endCost := endpointPenalty(
				K, tk, tOrientation, last, lastSign, false,
			)

			total := n + internal + startCost + endCost
			if total < answer {
				answer = total
			}
		}
	}

	return answer
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var T int
	fmt.Fscan(in, &T)

	for ; T > 0; T-- {
		var K, sx, sy, tx, ty int64
		fmt.Fscan(in, &K, &sx, &sy, &tx, &ty)
		fmt.Fprintln(out, solve(K, sx, sy, tx, ty))
	}
}
