package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type Cell struct {
	strength int64
	index    int
}

type MinHeap []Cell

func (h MinHeap) Len() int           { return len(h) }
func (h MinHeap) Less(i, j int) bool { return h[i].strength < h[j].strength }
func (h MinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MinHeap) Push(x any) {
	*h = append(*h, x.(Cell))
}

func (h *MinHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var H, W int
	var X int64
	fmt.Fscan(in, &H, &W, &X)

	var P, Q int
	fmt.Fscan(in, &P, &Q)
	P--
	Q--

	n := H * W
	strengths := make([]int64, n)
	for i := range strengths {
		fmt.Fscan(in, &strengths[i])
	}

	start := P*W + Q
	current := strengths[start]

	visited := make([]bool, n)
	visited[start] = true

	pq := &MinHeap{}
	heap.Init(pq)

	directions := [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

	addNeighbors := func(index int) {
		r, c := index/W, index%W
		for _, d := range directions {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nr >= H || nc < 0 || nc >= W {
				continue
			}
			next := nr*W + nc
			if visited[next] {
				continue
			}
			visited[next] = true
			heap.Push(pq, Cell{strength: strengths[next], index: next})
		}
	}

	addNeighbors(start)

	for pq.Len() > 0 {
		cell := (*pq)[0]

		// cell.strength * X < current, written without overflow.
		if cell.strength > (current-1)/X {
			break
		}

		heap.Pop(pq)
		current += cell.strength
		addNeighbors(cell.index)
	}

	fmt.Fprintln(out, current)
}
