type stat struct {
	count int
	sum   int64
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]int, n)
	var total int64
	maxA := 0

	for i := range a {
		fmt.Fscan(in, &a[i])
		total += int64(a[i])
		if a[i] > maxA {
			maxA = a[i]
		}
	}

	answer := int64(n+1) * total
	maxSum := 2 * maxA

	const arrayLimit = 1 << 20
	counts := make([]int32, arrayLimit)
	sums := make([]int64, arrayLimit)
	used := 0

	for mod := 2; mod <= maxSum; mod <<= 1 {
		mask := mod - 1
		var divisibleSum int64

		if mod <= arrayLimit {
			for i := 0; i < used; i++ {
				counts[i] = 0
				sums[i] = 0
			}
			used = mod

			for _, x := range a {
				r := x & mask
				complement := (-r) & mask

				divisibleSum += int64(counts[complement])*int64(x) + sums[complement]

				if r == 0 || r*2 == mod {
					divisibleSum += int64(2 * x)
				}

				counts[r]++
				sums[r] += int64(x)
			}
		} else {
			capacity := n
			if mod < capacity {
				capacity = mod
			}
			groups := make(map[int]stat, capacity)

			for _, x := range a {
				r := x & mask
				complement := (-r) & mask

				s := groups[complement]
				divisibleSum += int64(s.count)*int64(x) + s.sum

				if r == 0 || r*2 == mod {
					divisibleSum += int64(2 * x)
				}

				s = groups[r]
				s.count++
				s.sum += int64(x)
				groups[r] = s
			}
		}

		answer -= divisibleSum / int64(mod)
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
