package main

import (
	"bufio"
	"fmt"
	"os"
)

func primitiveRootLength(s string) int64 {
	n := len(s)
	pi := make([]int, n)
	for i := 1; i < n; i++ {
		j := pi[i-1]
		for j > 0 && s[i] != s[j] {
			j = pi[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		pi[i] = j
	}
	p := n - pi[n-1]
	if n%p != 0 {
		p = n
	}
	return int64(p)
}

func countBits(s string) (zeros, ones int64) {
	for i := 0; i < len(s); i++ {
		if s[i] == '0' {
			zeros++
		} else {
			ones++
		}
	}
	return
}

func solve(s, x, y string) bool {
	if x == y {
		return true
	}

	x0, x1 := countBits(x)
	y0, y1 := countBits(y)

	a := x0 - y0
	b := x1 - y1

	if b == 0 {
		return a == 0
	}

	// Length equality requires:
	// a*|S| + b*|T| = 0.
	numerator := -a * int64(len(s))
	if numerator%b != 0 {
		return false
	}
	tLen := numerator / b
	if tLen < 0 {
		return false
	}
	if tLen == 0 {
		return true
	}

	rootLen := primitiveRootLength(s)
	return tLen%rootLen == 0
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var t int
	fmt.Fscan(in, &t)

	for ; t > 0; t-- {
		var s, x, y string
		fmt.Fscan(in, &s, &x, &y)
		if solve(s, x, y) {
			fmt.Fprintln(out, "Yes")
		} else {
			fmt.Fprintln(out, "No")
		}
	}
}
