package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Fenwick struct {
	n    int
	tree []int
}

func NewFenwick(n int) *Fenwick {
	return &Fenwick{
		n:    n,
		tree: make([]int, n+1),
	}
}

func (f *Fenwick) Add(i, v int) {
	for i <= f.n {
		f.tree[i] += v
		i += i & -i
	}
}

func (f *Fenwick) Sum(i int) int {
	res := 0
	for i > 0 {
		res += f.tree[i]
		i -= i & -i
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	leftInversions := make([]int, n+1)
	fw := NewFenwick(n)
	var inversions int64

	for pos := 1; pos <= n; pos++ {
		var value int
		fmt.Fscan(in, &value)

		notGreater := fw.Sum(value)
		greater := (pos - 1) - notGreater
		leftInversions[pos] = greater
		inversions += int64(greater)

		fw.Add(value, 1)
	}

	var m int
	fmt.Fscan(in, &m)

	a := make([]int, m)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	diff := make([]int64, m+1)

	for pos := 1; pos <= n; pos++ {
		count := leftInversions[pos]
		if count == 0 {
			continue
		}

		start := sort.Search(m, func(i int) bool {
			return a[i] >= pos
		})
		if start == m {
			continue
		}

		end := start + count
		if end > m {
			end = m
		}

		diff[start]++
		diff[end]--
	}

	var swapsThisOperation int64
	for i := 0; i < m; i++ {
		swapsThisOperation += diff[i]
		inversions -= swapsThisOperation
		fmt.Fprintln(out, inversions)
	}
}
