package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"sort"
)

type FastScanner struct {
	r *bufio.Reader
}

func NewFastScanner() *FastScanner {
	return &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
}

func (fs *FastScanner) NextInt64() int64 {
	var n int64
	var sign int64 = 1
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, err = fs.r.ReadByte()
	}
	return n * sign
}

// floorSum returns sum_{i=0}^{n-1} floor((a*i+b)/m).
func floorSum(n, m, a, b int64) int64 {
	var ans int64
	for {
		if a >= m {
			ans += (n - 1) * n * (a / m) / 2
			a %= m
		}
		if b >= m {
			ans += n * (b / m)
			b %= m
		}

		yMax := a*n + b
		if yMax < m {
			return ans
		}

		n = yMax / m
		b = yMax % m
		m, a = a, m
	}
}

func main() {
	in := NewFastScanner()

	n := int(in.NextInt64())
	m := in.NextInt64()
	c := in.NextInt64()
	k := in.NextInt64()

	a := make([]int64, n)
	for i := range a {
		a[i] = in.NextInt64()
	}
	sort.Slice(a, func(i, j int) bool {
		return a[i] < a[j]
	})

	baseFloorSum := floorSum(k, m, c, 0)

	// Sum of (c*i mod m), calculated with big integers to avoid
	// overflow in c*k*(k-1)/2 before cancellation.
	residueSumBig := new(big.Int).Mul(big.NewInt(k), big.NewInt(k-1))
	residueSumBig.Div(residueSumBig, big.NewInt(2))
	residueSumBig.Mul(residueSumBig, big.NewInt(c))

	sub := new(big.Int).Mul(big.NewInt(m), big.NewInt(baseFloorSum))
	residueSumBig.Sub(residueSumBig, sub)
	residueSum := residueSumBig.Int64()

	// less[j] is the number of i such that
	// (c*i mod m) < m-a[j].
	less := make([]int64, n)
	for i := 0; i < n; i++ {
		less[i] = k + baseFloorSum - floorSum(k, m, c, a[i])
	}

	constantSum := less[n-1] * a[0]

	for i := 0; i < n; i++ {
		var upper int64
		if i == 0 {
			upper = k
		} else {
			upper = less[i-1]
		}
		count := upper - less[i]
		constantSum += count * (a[i] - m)
	}

	answer := residueSum + constantSum

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
