		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	n := in.NextInt()
	m := in.NextInt()

	inf := n + 1
	ban := make([][]int, n+1)
	for x := 1; x <= n; x++ {
		ban[x] = make([]int, n+2)
		for l := 1; l <= n; l++ {
			ban[x][l] = inf
		}
	}

	for i := 0; i < m; i++ {
		l := in.NextInt()
		r := in.NextInt()
		x := in.NextInt()
		if r < ban[x][l] {
			ban[x][l] = r
		}
	}

	// ban[x][l] is the minimum R among conditions (L,R,x) with L >= l.
	for x := 1; x <= n; x++ {
		for l := n - 1; l >= 1; l-- {
			if ban[x][l+1] < ban[x][l] {
				ban[x][l] = ban[x][l+1]
			}
		}
	}

	comb := make([][]int64, n+1)
	for i := 0; i <= n; i++ {
		comb[i] = make([]int64, i+1)
		comb[i][0] = 1
		comb[i][i] = 1
		for j := 1; j < i; j++ {
			comb[i][j] = comb[i-1][j-1] + comb[i-1][j]
			if comb[i][j] >= mod {
				comb[i][j] -= mod
			}
		}
	}

	dp := make([][]int64, n+2)
	for i := 0; i <= n+1; i++ {
		dp[i] = make([]int64, n+1)
	}
	for i := 1; i <= n+1; i++ {
		dp[i][i-1] = 1
	}

	for length := 1; length <= n; length++ {
		for l := 1; l+length-1 <= n; l++ {
			r := l + length - 1
			var ways int64

			for root := l; root <= r; root++ {
				// Choosing root as the maximum is invalid if some condition
				// (L,R,root) is fully contained in [l,r].
				if ban[root][l] <= r {
					continue
				}

				cur := dp[l][root-1] * dp[root+1][r] % mod
				cur = cur * comb[length-1][root-l] % mod
				ways += cur
				if ways >= mod {
					ways -= mod
				}
			}
			dp[l][r] = ways
		}
	}

	fmt.Fprintln(out, dp[1][n])
}
