		if phi[p] == int64(p) {
			for x := p; x <= maxA; x += p {
				phi[x] = phi[x] / int64(p) * int64(p-1)
			}
		}
	}

	divisors := make([][]int, maxA+1)
	for d := 1; d <= maxA; d++ {
		for x := d; x <= maxA; x += d {
			divisors[x] = append(divisors[x], d)
		}
	}

