	fmt.Fscan(in, &n, &q)

	maxValue := n * n
	words := maxValue/64 + 1

	dp := make([][][]uint64, n+1)
	for r := 0; r <= n; r++ {
		dp[r] = make([][]uint64, n+1)
		for c := 0; c <= n; c++ {
			dp[r][c] = make([]uint64, words)
		}
	}
	dp[0][0][0] = 1

	for r := 0; r <= n; r++ {
		for c := 0; c <= n; c++ {
			src := dp[r][c]

			nonempty := false
			for _, x := range src {
				if x != 0 {
					nonempty = true
					break
				}
			}
			if !nonempty {
				continue
			}

			for a := 2; r+a <= n; a++ {
				for b := 2; c+b <= n; b++ {
					shift := a * b
					wordShift := shift / 64
					bitShift := uint(shift % 64)
					dst := dp[r+a][c+b]

					for w, x := range src {
						if x == 0 {
							continue
						}
						idx := w + wordShift
						if idx < words {
							dst[idx] |= x << bitShift
						}
						if bitShift != 0 && idx+1 < words {
							dst[idx+1] |= x >> (64 - bitShift)
						}
					}
				}
			}
		}
	}

	possibleNonFixed := make([]bool, maxValue+1)
	for r := 0; r <= n; r++ {
		for c := 0; c <= n; c++ {
			for value := 0; value <= maxValue; value++ {
				if (dp[r][c][value/64]>>(uint(value%64)))&1 != 0 {
					possibleNonFixed[value] = true
				}
			}
		}
	}

