package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

type Box struct {
	v int64
	p int64
}

type MaxHeap []int64

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int64))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var T int
	fmt.Fscan(in, &T)

	for ; T > 0; T-- {
		var n, m int
		fmt.Fscan(in, &n, &m)

		boxes := make([]Box, n)
		for i := range boxes {
			fmt.Fscan(in, &boxes[i].v, &boxes[i].p)
		}

		sort.Slice(boxes, func(i, j int) bool {
			if boxes[i].v != boxes[j].v {
				return boxes[i].v > boxes[j].v
			}
			return boxes[i].p < boxes[j].p
		})

		suffix := make([]int64, n+1)
		for i := n - 1; i >= 0; i-- {
			gain := boxes[i].v - boxes[i].p
			if gain < 0 {
				gain = 0
			}
			suffix[i] = suffix[i+1] + gain
		}

		k := m - 1
		if k == 0 {
			fmt.Fprintln(out, suffix[0])
			continue
		}

		var answer int64
		var sumP int64
		h := &MaxHeap{}
		heap.Init(h)

		for i := 0; i < n; i++ {
			if h.Len() == k-1 {
				candidate := suffix[i+1] + int64(k) - sumP - boxes[i].p
				if candidate > answer {
					answer = candidate
				}
			}

			heap.Push(h, boxes[i].p)
			sumP += boxes[i].p

			if h.Len() > k-1 {
				sumP -= heap.Pop(h).(int64)
			}
		}

		fmt.Fprintln(out, answer)
	}
}
