	"os"
)

const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	b := make([]int, n)
	totalUnknown := 0
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &b[i])
		if b[i] == -1 {
			totalUnknown++
		}
	}

	// powers[e][x] = x^e modulo mod.
	width := m + 1
	powers := make([]uint32, (totalUnknown+1)*width)
	for x := 0; x <= m; x++ {
		powers[x] = 1
	}
	for e := 1; e <= totalUnknown; e++ {
		cur := e * width
		prev := (e - 1) * width
		for x := 0; x <= m; x++ {
			powers[cur+x] = uint32(int64(powers[prev+x]) * int64(x) % mod)
		}
	}

	pow := func(base, exp int) int64 {
		return int64(powers[exp*width+base])
	}

	// suffixMax[i] is the maximum fixed value in B[i:].
	suffixMax := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixMax[i] = suffixMax[i+1]
		if b[i] != -1 && b[i] > suffixMax[i] {
			suffixMax[i] = b[i]
		}
	}

	// Every completion contributes at least one connected component.
	answer := pow(m, totalUnknown)

	leftUnknown := 0
	leftMinFixed := m + 1

	for k := 0; k < n-1; k++ {
		if b[k] == -1 {
			leftUnknown++
		} else if b[k] < leftMinFixed {
			leftMinFixed = b[k]
		}

		rightUnknown := totalUnknown - leftUnknown
		rightMaxFixed := suffixMax[k+1]

		lower := rightMaxFixed
		if lower < 1 {
			lower = 1
		}
		upper := leftMinFixed - 1
		if upper > m {
			upper = m
		}

		var ways int64
		for t := lower; t <= upper; t++ {
			currentRight := pow(t, rightUnknown)

			var previousRight int64
			if t-1 >= rightMaxFixed {
				previousRight = pow(t-1, rightUnknown)
			}

			exactRightMax := currentRight - previousRight
			if exactRightMax < 0 {
				exactRightMax += mod
			}

			leftWays := pow(m-t, leftUnknown)
			ways += leftWays * exactRightMax % mod
			if ways >= mod {
				ways -= mod
			}
		}

		answer += ways
		if answer >= mod {
			answer -= mod
		}
	}

	fmt.Fprintln(out, answer)
}
