const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	a := make([]int, n)
	b := make([]int, n)
	owner := make([]int, n)
	for i := range owner {
		owner[i] = -1
	}

	valid := true
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		group := (a[i] - 1) / 2
		if owner[group] != -1 {
			valid = false
		} else {
			owner[group] = i
		}
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &b[i])
	}

	if !valid {
		fmt.Fprintln(out, 0)
		return
	}

	next := make([]int, n)
	indegree := make([]int, n)
	for i := range next {
		next[i] = -1
	}

	for j := 0; j < n; j++ {
		if b[j] == -1 {
			continue
		}

		group := (b[j] - 1) / 2
		p := owner[group]

		expected := a[p]
		if expected%2 == 1 {
			expected++
		} else {
			expected--
		}

		if b[j] != expected || next[p] != -1 {
			valid = false
			break
		}

		next[p] = j
		indegree[j]++
		if indegree[j] > 1 {
			valid = false
			break
		}
	}

	if !valid {
		fmt.Fprintln(out, 0)
		return
	}

	visited := make([]bool, n)
	pureOdd, pureEven, mixed := 0, 0, 0

	// Components beginning at indegree-zero vertices are directed paths.
	for start := 0; start < n; start++ {
		if indegree[start] != 0 {
			continue
		}

		hasOdd, hasEven := false, false
		cur := start
		for cur != -1 {
			visited[cur] = true
			if a[cur]%2 == 1 {
				hasOdd = true
			} else {
				hasEven = true
			}
			cur = next[cur]
		}

		if hasOdd && hasEven {
			mixed++
		} else if hasOdd {
			pureOdd++
		} else {
			pureEven++
		}
	}

	// Remaining components are already closed cycles.
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}

		hasOdd, hasEven := false, false
		cur := start
		for !visited[cur] {
			visited[cur] = true
			if a[cur]%2 == 1 {
				hasOdd = true
			} else {
				hasEven = true
			}
			cur = next[cur]
		}

		if !(hasOdd && hasEven) {
			fmt.Fprintln(out, 0)
			return
		}
	}

	k := pureOdd + pureEven + mixed
	if k == 0 {
		fmt.Fprintln(out, 1)
		return
	}

	fact := make([]int64, k+1)
	fact[0] = 1
	for i := 1; i <= k; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	ans := fact[k]
	ans = (ans - int64(pureOdd+pureEven)*fact[k-1]) % mod
	if k >= 2 {
		ans = (ans + int64(pureOdd)*int64(pureEven)%mod*fact[k-2]) % mod
	}
	if ans < 0 {
		ans += mod
	}

	fmt.Fprintln(out, ans)
}
