package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func requiredSequence(n, x int, balls, perm []int) ([]int, bool) {
	inverse := make([]int, n)
	for i, to := range perm {
		inverse[to] = i
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}
	nodeAtDist := make([]int, n)

	dist[x] = 0
	cur := inverse[x]
	d := 1
	for cur != x {
		dist[cur] = d
		nodeAtDist[d] = cur
		cur = inverse[cur]
		d++
	}

	maxDist := 0
	for i, count := range balls {
		if count == 0 || i == x {
			continue
		}
		if dist[i] == -1 {
			return nil, false
		}
		if dist[i] > maxDist {
			maxDist = dist[i]
		}
	}

	sequence := make([]int, 0, maxDist)
	for d := maxDist; d >= 1; d-- {
		sequence = append(sequence, nodeAtDist[d])
	}
	return sequence, true
}

func lcsLength(a, b []int, n int) int {
	position := make([]int, n)
	for i := range position {
		position[i] = -1
	}
	for i, v := range b {
		position[v] = i
	}

	tails := make([]int, 0)
	for _, v := range a {
		p := position[v]
		if p == -1 {
			continue
		}
		i := sort.SearchInts(tails, p)
		if i == len(tails) {
			tails = append(tails, p)
		} else {
			tails[i] = p
		}
	}
	return len(tails)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, x int
	fmt.Fscan(in, &n, &x)
	x--

	a := make([]int, n)
	b := make([]int, n)
	p := make([]int, n)
	q := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	for i := range b {
		fmt.Fscan(in, &b[i])
	}
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}
	for i := range q {
		fmt.Fscan(in, &q[i])
		q[i]--
	}

	redSequence, possible := requiredSequence(n, x, a, p)
	if !possible {
		fmt.Fprintln(out, -1)
		return
	}

	blueSequence, possible := requiredSequence(n, x, b, q)
	if !possible {
		fmt.Fprintln(out, -1)
		return
	}

	common := lcsLength(redSequence, blueSequence, n)
	answer := len(redSequence) + len(blueSequence) - common
	fmt.Fprintln(out, answer)
}
