package main

import (
	"bufio"
	"fmt"
	"os"
)

const negInf int64 = -(1 << 60)

var (
	n       int
	segC    []int64
	segD    []int64
	segSize int
)

// Returns the first index i >= ql such that segC[i] >= value.
// Returns n if no such index exists.
func firstGE(node, left, right, ql int, value int64) int {
	if right <= ql || segC[node] < value {
		return n
	}
	if right-left == 1 {
		if left < n {
			return left
		}
		return n
	}

	mid := (left + right) >> 1
	res := firstGE(node<<1, left, mid, ql, value)
	if res != n {
		return res
	}
	return firstGE(node<<1|1, mid, right, ql, value)
}

// Returns the last index i < qr such that segD[i] >= value.
// Returns -1 if no such index exists.
func lastGE(node, left, right, qr int, value int64) int {
	if qr <= left || segD[node] < value {
		return -1
	}
	if right-left == 1 {
		if left < n {
			return left
		}
		return -1
	}

	mid := (left + right) >> 1
	res := lastGE(node<<1|1, mid, right, qr, value)
	if res != -1 {
		return res
	}
	return lastGE(node<<1, left, mid, qr, value)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	prefix := make([]int64, n+1)
	var maxA int64

	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		prefix[i+1] = prefix[i] + a[i]
		if a[i] > maxA {
			maxA = a[i]
		}
	}

	c := make([]int64, n)
	d := make([]int64, n)
	for i := 0; i < n; i++ {
		c[i] = a[i] - prefix[i]
		d[i] = a[i] + prefix[i+1]
	}

	segSize = 1
	for segSize < n {
		segSize <<= 1
	}
	segC = make([]int64, segSize<<1)
	segD = make([]int64, segSize<<1)

	for i := range segC {
		segC[i] = negInf
		segD[i] = negInf
	}
	for i := 0; i < n; i++ {
		segC[segSize+i] = c[i]
		segD[segSize+i] = d[i]
	}
	for i := segSize - 1; i >= 1; i-- {
		if segC[i<<1] > segC[i<<1|1] {
			segC[i] = segC[i<<1]
		} else {
			segC[i] = segC[i<<1|1]
		}
		if segD[i<<1] > segD[i<<1|1] {
			segD[i] = segD[i<<1]
		} else {
			segD[i] = segD[i<<1|1]
		}
	}

	total := prefix[n]
	ans := make([]int64, n)

	for k := 0; k < n; k++ {
		l, r := k, k

		for {
			if prefix[r+1]-prefix[l] > maxA {
				l, r = 0, n-1
				break
			}

			changed := false

			// Expand to the left as far as possible.
			leftThreshold := prefix[r+1]
			if l > 0 && d[l-1] < leftThreshold {
				blocker := lastGE(1, 0, segSize, l, leftThreshold)
				l = blocker + 1
				changed = true
			}

			if prefix[r+1]-prefix[l] > maxA {
				l, r = 0, n-1
				break
			}

			// Expand to the right as far as possible.
			rightThreshold := -prefix[l]
			if r+1 < n && c[r+1] < rightThreshold {
				blocker := firstGE(1, 0, segSize, r+1, rightThreshold)
				if blocker == n {
					r = n - 1
				} else {
					r = blocker - 1
				}
				changed = true
			}

			if !changed {
				break
			}
		}

		if l == 0 && r == n-1 {
			ans[k] = total
		} else {
			ans[k] = prefix[r+1] - prefix[l]
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	for i, v := range ans {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, v)
	}
	fmt.Fprintln(out)
	out.Flush()
}
